var HOWTO = {"neon-demon-hunter": {"m": ["Black hoodie, black pants, chunky sneakers, 1 set (own)", "Neon fabric paint in 2 to 3 colors, 1 tube each (buy: craft store)", "Glow-in-the-dark temporary tattoos or neon eyeliner, 1 pack (buy: drugstore)", "Toy sword prop, 1 (buy: toy store)", "Hair gel or temporary neon hair spray, 1 (buy: drugstore)", "Black leather-look jacket or vest, 1 (buy: thrift store, optional)"], "s": ["Buy the neon fabric paint, temporary tattoos, toy sword prop, and hair spray. Lay the black hoodie, black pants, and chunky sneakers flat.", "Sketch the demon-slaying symbols on paper FIRST. Crooked symbols cannot be unpainted. Draw sharp neon symbols on the hoodie sleeves and pant legs with the fabric paint. Let dry 2 hours.", "Style the hair up with hair gel, or mist it with the temporary neon hair spray. Apply the neon eyeliner or glow-in-the-dark temporary tattoos on the cheeks and arms.", "Wear the black leather-look jacket over the hoodie and carry the toy sword prop. Keep the painted side facing out so the neon sigils show.", "Optional pro finish: charge the neon paint under bright light before heading out, and add one glowing green 'scar' across the cheek with face paint. The scar is the backstory, everyone will ask about it.", "Optional pro finish: charge the neon paint under bright light before heading out, and add one glowing green 'scar' across the cheek with face paint. The scar is the backstory, everyone will ask about it."], "time": "25 min", "cost": "$5-12", "effort": "Easy", "faqs": [["Does neon fabric paint actually glow?", "It glows under blacklight and looks electric in daylight. Under normal indoor light it is just bright. For true night glow, add glow-in-the-dark tape accents."], ["Toy sword or foam sword?", "Foam. Toy plastic swords snap and leave sharp edges; foam swords survive all-night duels and venue security."]]}, "classic-ghost": {"m": ["1 white flat sheet: twin size for kids under 8, full size for tweens and adults (make: use an old sheet; buy: thrift store for a dollar or two)", "Black marker, thick tip, 1 (buy: dollar store)", "Scissors, 1 pair", "2 small squares of black tulle or sheer fabric, about 4 inches each (optional, for see-through eyes; buy: craft store)"], "s": ["Pick the sheet size first: twin flat for a small kid, full for a bigger kid or adult. Bigger than you need is fine; smaller is not.", "Drape the sheet over the wearer and have them stand still. Mark both eye spots with the black marker while the sheet is on, marking blind never lines up.", "Take the sheet off. Cut the eye holes SMALL first, about the size of a quarter. You can always widen them; you cannot shrink them.", "Hold the sheet up and check: the wearer should see clearly through both holes. Widen a little at a time until they can.", "Optional pro finish: tape a square of black tulle behind each hole. From outside the eyes look dark and hollow; from inside you see straight through the mesh.", "Safety: trim the bottom so the hem clears the ground by several inches, a dragging hem is what trips a kid on a dark sidewalk. Keep nothing tight around the neck.", "Draw a wavy or smiling mouth below the eyes with the black marker. Drape it back on and go."], "time": "10 min", "cost": "$0-3", "effort": "Easy", "faqs": [["How do I make eye holes safely?", "Mark them while the sheet is on the wearer, cut small first, and widen until they see clearly. Back with black tulle so the eyes look dark but stay see-through."], ["What size sheet for a toddler ghost?", "A twin flat sheet, trimmed short. Cut it shorter than feels right, toddlers trip on hems adults would clear."]]}, "blue-dog-family": {"m": ["Blue or orange t-shirt per person, 1 each (own, or buy: clothing store)", "Headband per person, 1 each (buy: dollar store)", "Blue, orange, and white craft felt, 1 sheet of each color 9x12 inches (buy: craft store, construction paper works too)", "Safety pins, 4 per person (buy: dollar store)", "Scissors, 1 pair"], "s": ["Buy the t-shirts, headbands, craft felt, and safety pins.", "Cut one paper ear template and check it against the headband before cutting felt. Cut two floppy dog ears from the craft felt with the scissors for each person, about 5 inches long. Match ear color to shirt color.", "Pin the ears to each headband with the safety pins.", "Pin a white craft felt belly spot to the front of each blue or orange t-shirt.", "Pull on the blue or orange t-shirts.", "Put on the headbands and decide who is mama, dad, and the pups.", "Optional pro finish: stuff an old sock with tissue, pin it to the back waistband as a tail, and let it wag. Every dog family photo is better with a tail.", "Optional pro finish: stuff an old sock with tissue, pin it to the back waistband as a tail, and let it wag. Every dog family photo is better with a tail."], "time": "25 min", "cost": "$5-10", "effort": "Easy", "faqs": [["How do you tell the family members apart?", "Match the show: blue shirt for the dad dog, orange for the mom dog, mix for the pups. Add a white belly spot to the pups only, the audience reads it instantly."], ["Ears keep sliding off the headband. Fix?", "Pin the ears to the headband with two safety pins each instead of tape. Pins survive hugs; tape gives up by the second photo."]]}, "superhero-family": {"m": ["Matching red sweatsuits, 1 per person (own: from closet, or buy a set at a discount store)", "Black felt, 1 pack (buy: craft store; construction paper works too)", "Yellow felt, 1 sheet (buy: craft store)", "Plain headbands, 1 per person (buy: dollar store multi-pack)", "Safety pins, 6 to 8, or tape, 1 roll (own: from home)", "Scissors, 1 pair (own: from home)"], "s": ["Buy the felt sheets and headbands.", "Have everyone dress in the red sweatsuits.", "Safety: cut the eye holes wide enough so everyone can see clearly.", "Trace the eye holes by holding the felt strip up to each face and marking the pupil spots. Cut the eye holes SMALLER than the marks first and widen as needed, since cut felt cannot be uncut. Make the eye masks: cut a mask strip from the black felt for each person with two eye holes. Attach it to the headband with the safety pins or tape.", "Make the logos: cut one big first-initial letter per person from the yellow felt. Use the safety pins or tape to attach it to the chest of each sweatsuit.", "Everyone wears the mask headband with the letter on the chest. Each person strikes their own hero pose for the group photo.", "Optional pro finish: cut a small yellow felt lightning bolt and pin one to each sleeve, so the emblem repeats beyond the chest.", "Optional pro finish: cut a small yellow felt lightning bolt and pin one to each sleeve, so the emblem repeats beyond the chest."], "time": "30 min", "cost": "$5-10", "effort": "Easy", "faqs": [["How do the masks stay on kids?", "Attach the felt mask to a headband, not to the skin. The headband does the holding, so the mask never slips into the eyes."], ["Are safety pins safe on kids' costumes?", "Pin from the outside of the fabric so pin backs face the clothes, never the skin. For toddlers, use tape instead of pins everywhere."]]}, "blue-alien-ohana": {"m": ["Blue hoodie per alien-role person, 1 each (own, or buy: clothing store)", "Blue craft felt, 1 sheet 9x12 inches per alien (buy: craft store, construction paper works too)", "Headband per alien-role person, 1 each (buy: dollar store)", "Red t-shirt or dress per Lilo-role person, 1 each (make: from closet, or buy: thrift store)", "White craft felt or paper, 1 sheet (buy: craft store)", "Safety pins, 4 to 6 (buy: dollar store)", "Scissors, 1 pair", "Tape, 1 roll"], "s": ["Buy the blue craft felt, the headbands, the white felt or paper, and the safety pins.", "Cut one paper ear template first and hold it against the headband to check the size, alien ears should be tall, about 6 inches. Then cut two large oval ears from the blue craft felt for each alien-role person with the scissors.", "Tape one pair of ears to each headband with the tape.", "Pull on the blue hoodies.", "Lilo: cut leaf shapes from the white felt or paper with the scissors. Pin or glue the leaves across the red t-shirt or dress.", "Safety: pin from the front of the red shirt, so pin backs face the fabric and never the skin.", "Wear dark hair down for Lilo. Put the ear headbands on the aliens last.", "Optional pro finish: cut a smaller pink felt oval and glue it inside each blue ear. The inner ear is the detail that makes people recognize the character instead of just 'blue alien'.", "Optional pro finish: cut a smaller pink felt oval and glue it inside each blue ear. The inner ear is the detail that makes people recognize the character instead of just 'blue alien'."], "time": "30 min", "cost": "$5-10", "effort": "Easy", "faqs": [["How do you keep big felt ears upright?", "Cut the ears with a 1-inch tab at the base, fold the tab over the headband, and tape both sides. Tall ears need the tab; glue alone flops by hour two."], ["What if we only have one blue hoodie?", "Make the second alien a different blue: navy t-shirt plus blue face paint on the arms. The ears match, so the pair still reads."]]}, "emerald-witch": {"m": ["1 long green dress, or green fabric, 3 yards (buy: fabric store)", "1 sheet black cardboard, 22x28 inches, for the hat (buy: craft store; a box painted black works too)", "Green face paint, non-toxic, 1 tube (buy: drugstore)", "Black eyeliner, 1, and dark green eye shadow, 1 (buy: drugstore)", "Hot glue gun with glue sticks, 1 set and scissors, 1 pair", "1 broom from home for a prop (make: use what you own)"], "s": ["Buy the green fabric, black cardboard, green face paint, black eyeliner, and dark green eye shadow.", "Safety: let an adult handle the hot glue, since the nozzle and glue get very hot.", "Sew or hot glue the green fabric into a long gown, leaving the hem ragged.", "Measure the head first, then roll the black cardboard into a tall cone and tape it loosely to check the fit before gluing. Glue a wide cardboard brim to its base with the hot glue. Hot glue sets fast and cannot be repositioned, so test the cone shape dry first.", "Paint the face green with the green face paint. Draw on the black eyeliner and the dark green eye shadow.", "Carry the broom bristle-up so it does not trip anyone.", "Optional pro finish: fray the gown hem by cutting 2-inch slits every few inches. A ragged hem is the difference between green dress and witch's gown.", "Optional pro finish: fray the gown hem by cutting 2-inch slits every few inches. A ragged hem is the difference between green dress and witch's gown."], "time": "45 min + drying", "cost": "$8-15", "effort": "Medium", "faqs": [["How do you get green face paint off?", "Wash with a gentle cleanser and soap, not just water: green needs soap. Moisturize after, and patch-test on the jawline first if skin is sensitive."], ["What if I cannot sew the gown?", "Hot glue works: fold the fabric around the body and glue the seam. It holds for one night and nobody sees the seam from the front."]]}, "gloom-bloom": {"m": ["1 set black clothes from the closet (make: use what you own)", "1 set colorful clothes from the closet (make: use what you own)", "Black and white face paint, non-toxic, 1 set (buy: drugstore)", "2 hair ties for braids (make: use what you own)", "3 to 5 fake flowers (buy: dollar store; paper flowers work too)"], "s": ["Buy the black and white face paint and the fake flowers.", "Gloom: wear the black clothes, and braid the hair tightly with the hair ties.", "Paint a small black teardrop under one eye with the black and white face paint.", "Bloom: wear the colorful clothes, and pin the fake flowers in the hair.", "Paint a small flower on one cheek with the face paint, keeping it clear of the eyes.", "Stand side by side: Gloom frowns and looks away, Bloom smiles big.", "Optional pro finish: braid the gloom hair tight with a middle part, and pin the bloom flowers all on one side. Opposite styling is what makes the pair read as opposites.", "Optional pro finish: braid the gloom hair tight with a middle part, and pin the bloom flowers all on one side. Opposite styling is what makes the pair read as opposites."], "time": "15 min", "cost": "$3-8", "effort": "Easy", "faqs": [["How do you paint a teardrop that does not smear?", "Paint it small under one eye with a thin brush, not a finger, and let it set before touching the face. Fingers smudge; brushes stay sharp."], ["What makes the pair read as a duo?", "The contrast: one frowns and looks away, one smiles big. Pose the attitude, not just the clothes."]]}, "deadpan-diva": {"m": ["Black dress, 1 (own)", "Very pale foundation or white non-toxic face paint, 1 (buy: toy store)", "Dark eyeliner and lipstick, 1 set (own, or buy: dollar store)", "2 hair ties (own)"], "s": ["Braid the hair into two tight braids with the hair ties.", "Buy the white non-toxic face paint if needed.", "Test the pale foundation on the jawline first and blend fully, patchy pale makeup reads as sick, not deadpan. Apply the pale foundation evenly over the face, blending into the neck so there is no mask line.", "Add the dark eyeliner and lipstick for contrast.", "Put on the black dress, fold the arms, and hold the stare.", "Use skin-safe makeup and wash it all off before bed.", "Optional pro finish: add a thin black ribbon choker. The choker plus the braids plus the stare is the complete silhouette, without it, it is just a black dress.", "Optional pro finish: add a thin black ribbon choker. The choker plus the braids plus the stare is the complete silhouette, without it, it is just a black dress."], "time": "15 min", "cost": "$3-8", "effort": "Easy", "faqs": [["How do you get the braids right?", "Two tight braids, middle part, pulled flat against the head. Loose or messy braids break the severe look, tight is the whole point."], ["How do you take off heavy pale makeup?", "Wash with a gentle cleanser, not just water, stage-white needs soap. Moisturize after; pale foundation is drying. Never sleep in it."]]}, "safari-zoo-crew": {"m": ["Solid-color clothes in animal colors, 1 set per person (own)", "Plastic headbands, 1 per person (buy: dollar store multi-pack)", "Felt sheets in brown, black, pink, tan, 1 pack (buy: craft store; construction paper works too)", "Face paint in brown and black, 1 tube each (buy: costume aisle or craft store)", "Scissors and tape, 1 set (own)"], "s": ["Assign roles BEFORE building. One guide per three animals keeps the ratio fun. Each person picks one animal and pulls matching solid-color clothes from the closet.", "Safety: cut the felt slowly and keep fingers clear of the scissors.", "Make each animal's ears from felt: cut two rounded ears and tape them to a plastic headband.", "Safety: use non-toxic kids face paint, and keep it away from the eyes.", "Paint faces: use the face paint to add each animal's nose, whiskers, or spots.", "Wear the colored outfit and put on the ear headband. Add one felt detail, like a felt tail taped to the back, to complete each animal.", "Optional pro finish: the guide 'discovers' each animal with the binoculars throughout the night, announcing the species dramatically. The discovery bit is the group performance.", "Optional pro finish: the guide 'discovers' each animal with the binoculars throughout the night, announcing the species dramatically. The discovery bit is the group performance."], "time": "25 min", "cost": "$5-10", "effort": "Easy", "faqs": [["How many animals per guide?", "Two to four. One guide herding six animals is chaos; one guide with two animals is a duo. Three animals is the sweet spot."], ["What animals are easiest?", "Lion (ears plus painted nose), zebra (striped face paint), giraffe (ears plus spot paint). Pick animals with one iconic feature each."]]}, "fairy-tale-princesses": {"m": ["1 dress from the closet per person (make: use what you own)", "1 cereal box per crown (make: from a cereal box)", "Gold or silver paint or markers, 1 set (buy: craft store)", "Scissors, 1 pair and tape, 1 roll", "1 hair ribbon per person (buy: dollar store)"], "s": ["Buy the gold or silver markers and the hair ribbon.", "Each princess picks any dress from her own closet.", "Safety: adults handle the scissors when cutting the cardboard crowns.", "Draw the crown shape on the cereal box in pencil first and hold it against the head to check the fit. Cut the crown with the scissors, leaving a 1-inch tab to tape the ends together. Color it with the gold or silver paint or markers and let it dry.", "Tie the hair ribbon as a bow, and tape the cardboard crown on top of the head.", "Line up for a princess parade photo, and check that each cardboard crown sits snugly.", "Optional pro finish: tie the ribbon as a bow under the crown, not on top. The bow peeking out below the crown looks styled; on top it looks like wrapping.", "Optional pro finish: tie the ribbon as a bow under the crown, not on top. The bow peeking out below the crown looks styled; on top it looks like wrapping."], "time": "15 min", "cost": "$2-5", "effort": "Easy", "faqs": [["How do you keep a cardboard crown on a kid's head?", "Tape a bobby pin inside the crown and clip it to the hair. Crowns balanced on top slide off; pinned crowns survive the parade."], ["Do the princesses need matching dresses?", "No: any dress from the closet works, and different dresses look like different kingdoms. The crowns are what make it a group."]]}, "tin-hero": {"m": ["Red sweatsuit, 1 (own)", "Gold duct tape, 1 roll (buy: dollar store or hardware store)", "Battery tea light, 1 (buy: dollar store)", "Cardboard, 1 piece (own)", "Tape, 1 roll (own)", "Safety pin, 1 (own)"], "s": ["Buy the gold duct tape and the battery tea light.", "Dress in the red sweatsuit.", "Stripe the sweatsuit with the gold duct tape: strips across the chest, arms, and legs.", "Draw the reactor circle on the cardboard BEFORE cutting, and measure it against the chest first. Cover it in gold tape, then tape the tea light behind its center.", "Safety: pin from inside the sweatsuit, so the pin back faces the fabric and never the skin.", "Pin the glowing circle to the chest of the sweatsuit.", "Walk like the suit does the talking.", "Optional pro finish: pin the reactor slightly off-center, like battle damage. Perfectly centered reads as costume; off-center reads as character.", "Optional pro finish: pin the reactor slightly off-center, like battle damage. Perfectly centered reads as costume; off-center reads as character."], "time": "25 minutes", "cost": "$5-10", "effort": "Easy", "faqs": [["How does the chest reactor glow?", "A battery tea light taped behind a cardboard circle covered in gold tape. The tape diffuses the light so it glows instead of showing a bulb."], ["Will the duct tape peel off the sweatsuit?", "Press each strip down hard and smooth out air bubbles. Fresh duct tape holds all night; old tape from the junk drawer peels by dinner."]]}, "good-witch-bad-witch": {"m": ["1 black dress or set of black clothes for the bad witch (make: use your closet)", "1 pink dress or set of pink clothes for the good witch (make: use your closet)", "Green face paint, non-toxic, 1 tube (buy: drugstore)", "1 cardboard crown (make: from a cereal box)", "1 black cone hat (buy: dollar store)", "Hot glue gun, scissors, 1 pink marker, tape"], "s": ["Buy the green face paint, the black cone hat, and the pink marker.", "Bad witch: wear the black dress or black clothes.", "Safety: let an adult handle the hot glue, and keep the green face paint away from the eyes.", "Test the hat brim bend dry before gluing: fold the brim, check it in a mirror, then hot glue it. Hot glue sets in seconds and cannot be repositioned. Paint the bad witch's face and hands green with the green face paint, keeping paint away from the eyes and patch-testing sensitive skin first.", "Good witch: wear the pink dress or pink clothes. Color the cardboard crown with the pink marker, and tape it on the head.", "Optional pro finish: color the cardboard crown with the pink marker on both sides. A double-sided crown flashes pink in photos; single-sided flashes brown cardboard.", "Optional pro finish: color the cardboard crown with the pink marker on both sides. A double-sided crown flashes pink in photos; single-sided flashes brown cardboard."], "time": "20 min", "cost": "$5-12", "effort": "Easy", "faqs": [["How do you get green face paint off kids?", "Wash with gentle cleanser and soap the same night, not just water. Green needs soap. Moisturize after and never let them sleep in it."], ["What if the cone hat will not stay on?", "Tape a bobby pin inside the hat and clip it to the hair. Cone hats are top-heavy and slide without an anchor."]]}, "fuzzy-monster": {"m": ["1 pastel fuzzy sweatsuit (buy: discount store)", "2 large googly eyes, 3 inches or bigger (buy: craft store; paper circles work too)", "1 sheet white felt, 9x12 inches, for the smile (buy: craft store; construction paper works too)", "Scissors, 1 pair", "Fabric glue, 1 tube, or 4 safety pins"], "s": ["Buy the pastel fuzzy sweatsuit, the googly eyes, and the white felt.", "Glue or pin the two googly eyes to the hood of the pastel fuzzy sweatsuit.", "Safety: adults handle the scissors when cutting the white felt.", "Draw the smile on paper first and hold it against the sweatsuit chest to check the size: it should span most of the chest. Cut the stitched-style smile from the white felt with the scissors. Cut it bigger than feels right: small smiles disappear into the fuzz.", "Let the fabric glue dry fully before wearing.", "Wear the hood up so the googly eyes sit above the forehead.", "Optional pro finish: cut two small felt fangs and glue them at the smile's corners. Fangs turn a friendly monster into a funny one.", "Optional pro finish: cut two small felt fangs and glue them at the smile's corners. Fangs turn a friendly monster into a funny one."], "time": "15 min + drying", "cost": "$8-15", "effort": "Easy", "faqs": [["Googly eyes or paper circles for the eyes?", "Googly eyes photograph ten times better and cost a dollar more. Paper circles work if the budget is zero, but they curl in humidity."], ["Will the eyes stay on the hood?", "Glue them the night before so the fabric glue cures, or pin them with two safety pins each. Same-day glue plus a bouncing kid equals lost eyes."]]}, "pocket-plush": {"m": ["Fuzzy one-piece pajamas or sweatsuit, 1 (buy: thrift store, or own: from closet)", "Felt ears: two big felt circles, about 4 inches across (buy: craft store; construction paper works too)", "Fabric glue, 1 tube (buy: craft store)", "Black and white felt for eyes and smile, 1 small sheet each (buy: craft store; paper works too)", "Large shipping tag or big index card, 1 (buy: office supply store)", "Marker, 1 (own: household)"], "s": ["Buy the fuzzy one-piece pajamas, felt ears, fabric glue, and large shipping tag. Glue the felt ears to the hood of the fuzzy one-piece pajamas.", "Cut the eyes and smile from paper first and lay them on the pajama chest to check the size and spacing, glued felt cannot be repositioned. Then cut two white felt eyes and a stitched-look smile from the black felt, and glue them to the chest of the fuzzy pajamas with the fabric glue.", "Write a collector number like 'No. 001' on the large shipping tag with the marker. Tie the tag to the wrist or waistband with string.", "Wear the fuzzy one-piece pajamas with the felt ears and large shipping tag showing. The smile goes on the chest like a plush's embroidered face.", "Optional pro finish: stitch the smile with dashed lines using a white fabric marker instead of a solid line. Dashed stitches read as plush embroidery; a solid line reads as a drawing.", "Optional pro finish: stitch the smile with dashed lines using a white fabric marker instead of a solid line. Dashed stitches read as plush embroidery; a solid line reads as a drawing."], "time": "25 min + drying", "cost": "$3-8", "effort": "Easy", "faqs": [["How do the ears stay on the hood?", "Fabric glue with the hood laid flat, left to dry for 30 minutes before wearing. For a same-night build, safety-pin them from inside the hood instead, pins hold immediately."], ["What do you write on the shipping tag?", "A collector number like 'No. 001' plus the plush name. The tag is the joke, so make it look official: big number, neat letters."]]}, "soccer-squad": {"m": ["Matching jerseys or same-color t-shirts, 1 per player (own: from closet, or buy a multi-pack at a sports store)", "Black shirt and black shorts for the referee, 1 set (own: from closet)", "Soccer ball, 1 any size (buy: sports store, or borrow from home)", "Red cardstock rectangle, 3x4 inches, 1 (own: cut from a folder or colored paper)", "Black marker, 1 (own: from home)", "White athletic tape, 1 roll (buy: sports store or pharmacy)", "Scissors, 1 pair"], "s": ["Assign roles: most of the family are players, one person is the referee.", "Players: wear matching jerseys or same-color shirts. Wrap a strip of white athletic tape around one upper arm as a captain's armband. Referee: wear all black.", "Safety: cut the cardstock slowly and keep fingers clear of the scissors.", "Cut the red cardstock rectangle a little larger than 3x4 inches first, then trim to size after holding it up to check it reads at arm's length. Make the red card: cut the rectangle from the folder or colored paper. Draw a thick black border around it with the black marker so it reads as a card at a glance.", "Players carry or dribble the soccer ball. The referee practices holding the red card high in the air.", "Optional pro finish: give the referee a coin for the coin toss and a small notebook as the official match log.", "Optional pro finish: give the referee a coin for the coin toss and a small notebook as the official match log."], "time": "25 min", "cost": "$3-8", "effort": "Easy", "faqs": [["What if we do not own matching jerseys?", "Same-color t-shirts from the closet work fine. A multi-pack of plain tees from a sports store is the cheap fix for a big squad."], ["How does the captain's armband stay on?", "Wrap one strip of white athletic tape around one upper arm over the sleeve and press the ends together. It holds for the night and peels off after."]]}, "glow-skeleton": {"m": ["Black sweatsuit, 1 (buy: discount store, or own)", "Glow-in-the-dark bone tape, 1 roll (buy: craft store)", "Glow bracelets, 1 pack (buy: dollar store)", "Scissors, 1 pair", "Black face paint, non-toxic, 1 tube (buy: drugstore)"], "s": ["Buy the black sweatsuit if you do not own one, plus the bone tape and glow bracelets.", "Charge the bone tape under a lamp for 20 minutes for maximum glow.", "Safety: adults handle the scissors when cutting the bone tape.", "Cut the bone tape into rib bones: lay strips horizontally across the chest and back. Add vertical spine segments down the center, and arm and leg bones down the limbs.", "Snap the glow bracelets onto both wrists and both ankles right before heading out.", "Test the face paint on the wrist first and wait 10 minutes for any reaction. Paint simple skull eye circles with the black face paint, keeping clear of the eyes so vision stays clear.", "Optional pro finish: 'charge' the glow tape under a bright lamp for 10 minutes right before heading out. Freshly charged tape glows dramatically for the first hour, that is when the photos happen.", "Optional pro finish: 'charge' the glow tape under a bright lamp for 10 minutes right before heading out. Freshly charged tape glows dramatically for the first hour, that is when the photos happen."], "time": "20 min", "cost": "$5-10", "effort": "Easy", "faqs": [["Does glow tape really glow all night?", "No, it fades over 1 to 2 hours. Charge it under bright light right before going out, and bring the roll for touch-ups. The first hour is the magic hour."], ["Tape or paint for the bones?", "Tape. It is faster, cleaner, peels off after, and actually glows. Painted bones look better in daylight but vanish at night, which defeats the costume."]]}, "block-game-crew": {"m": ["1 large cardboard box per person, big enough to fit over the torso (make: ask a grocery store for spares)", "Acrylic paint in each hero's colors, 1 small bottle per color (buy: craft store, tempera paint works too)", "Paintbrushes, 1 wide and 1 detail per person", "Black marker, 1 (buy: dollar store)", "Scissors, 1 pair"], "s": ["Each person picks a blocky video-game hero look.", "Safety: an adult should handle the heavy cutting, and cut the eye holes generously so everyone can see clearly.", "Measure each person's head and shoulders first, then cut a head opening and eye holes in each large cardboard box with the scissors. Cut the head opening smaller than you think, cardboard cut away cannot be put back. Cut the eye holes generously so everyone can see clearly.", "Paint each box in the hero's main colors with the acrylic paint and paintbrushes. Let it dry fully.", "Draw a pixel-style square face and details on the front of each box with the black marker. Wear the boxes over regular clothes once the paint is dry.", "Optional pro finish: draw thin black grid lines across the painted box before it dries fully. The grid is what makes it read as pixels instead of just a painted box.", "Optional pro finish: draw thin black grid lines across the painted box before it dries fully. The grid is what makes it read as pixels instead of just a painted box."], "time": "45 min + drying", "cost": "$5-12", "effort": "Medium", "faqs": [["How do you keep a box costume comfortable?", "Cut arm holes wide, wear it over regular clothes, and tape the inside edges of every cut so cardboard never scratches. Keep the box at torso height, never over the face, for kids."], ["How long does the paint take to dry?", "Acrylic on cardboard needs about 1 hour to stop being tacky. Paint the night before if you can; wearing it damp smears the pixel face."]]}, "web-slinger-crew": {"m": ["Hoodies in red, black, and pink, 1 per person (own: from closet)", "Black fabric paint or black face paint, 1 tube (buy: craft store)", "White stickers or white electrical tape, 1 roll (buy: hardware store)", "Sunglasses or swim goggles, 1 per person (buy: dollar store multi-pack)", "Tape, 1 roll (own: from home)"], "s": ["Assign each person a hoodie color.", "Buy the black fabric paint or black face paint, white stickers or white electrical tape, and the multi-pack of sunglasses.", "Draw the eye-lens shape on paper first and hold it against the sunglasses to check the size before painting, since paint on lenses cannot be removed cleanly. Stick white stickers or white electrical tape in a web pattern across the front of each pair of sunglasses. Draw two black eye lenses on top with the black fabric paint or black face paint. Let them dry flat for 30 minutes.", "Make the chest webs: stick short white tape strips in a web grid across the chest of each hoodie.", "Wear the hoodie with the hood up and put on the web-patterned sunglasses. Each person picks their own web-shooting pose for the group shot.", "Optional pro finish: run short white tape strips down the outside of each sleeve as web lines, so the arms match the chest.", "Optional pro finish: run short white tape strips down the outside of each sleeve as web lines, so the arms match the chest."], "time": "30 min", "cost": "$5-10", "effort": "Easy", "faqs": [["Sunglasses or swim goggles for the eye lenses?", "Swim goggles stay on better, especially for kids running around. Sunglasses work for photos but slide off during the night."], ["Will the electrical tape come off the hoodie after?", "White electrical tape peels off clean from most hoodie fabrics. Test a hidden spot first on anything delicate."]]}, "mermaid-crew": {"m": ["T-shirt or dress in a sea color (teal, purple, red, white), 1 per person (buy: thrift store, or own)", "Face paint in a matching accent color, 1 tube (buy: drugstore)", "Plastic trident prop, 1 (buy: toy store)", "Toy crab or red paper for a cardboard crab, 1 (make: cut from red paper, or buy: toy store)", "Shell necklace, 1 (buy: craft store, or make: string pasta shells)", "Scissors and tape, 1 set (own)"], "s": ["Buy the plastic trident prop and the face paint. Assign each person a role and a sea-colored t-shirt or dress from the closet.", "Sketch the cheek detail on paper first. Face paint is hard to remove and redo once applied. Paint one small matching detail per person: scales on a cheek, a seaweed swirl, or an anchor.", "Cut a red paper body, legs, and claws with the scissors and tape them to the smallest person's shirt. Or hand them the toy crab instead.", "The sea king carries the plastic trident prop. Everyone else picks one accessory, like the shell necklace, and stands tall for the crew photo.", "Optional pro finish: dab the accent face paint along the cheekbones through a fishnet stocking as a stencil. The scale stencil photographs like movie makeup.", "Optional pro finish: dab the accent face paint along the cheekbones through a fishnet stocking as a stencil. The scale stencil photographs like movie makeup."], "time": "20 minutes", "cost": "$5-10", "effort": "Easy", "faqs": [["What if we cannot find sea-colored shirts?", "Any solid tee works with the accessories doing the work. The trident plus the shell necklace plus one painted detail reads as mermaid crew on any color."], ["How do you keep the crab on the shirt?", "Tape it from inside the shirt with a big tape loop, or pin it. Do not tape it to bare skin; sweat loosens tape in an hour."]]}, "little-pig-family": {"m": ["Pink t-shirts or pajamas, 1 per person (buy: thrift store, or own: from closet)", "Pink headband, 1 per person (buy: dollar store)", "Pink paper cup, 1 per snout (own: from the kitchen drawer)", "Pink felt or construction paper, 2 triangles per ear (buy: craft store)", "Pink string or yarn, 1 arm length per snout (own: from the craft drawer)", "Scissors, 1 pair, and clear tape, 1 roll (own: household tools)", "Pink blush or face paint for cheeks, 1 (buy: drugstore)"], "s": ["Buy the pink t-shirts and pink headbands. Gather the pink paper cups, pink felt, pink string, scissors, and clear tape from around the house.", "Poke the holes SMALL first with the scissor tip and test the string fit, holes poked too big tear through the cup and the snout falls apart. Poke two small holes in the sides of a pink paper cup.", "Cut one paper ear template first and check the size on the headband, ears should stand about 3 inches tall. Then cut two pink felt triangles with the scissors and tape them to the pink headband as ears.", "Thread the pink string through the holes, then tie the cup gently in front of the nose.", "Dab a little pink blush on each person's cheeks with a finger. Hand the little brother a toy dinosaur from the toy store or one he owns. Now he is the pig who brings the dinosaur.", "Optional pro finish: draw two small black nostril dots on the bottom of each cup snout with a marker. Nostrils are the detail that turns a taped cup into a snout.", "Optional pro finish: draw two small black nostril dots on the bottom of each cup snout with a marker. Nostrils are the detail that turns a taped cup into a snout."], "time": "25 min", "cost": "$3-8", "effort": "Easy", "faqs": [["How do you tie the snout on without it hurting?", "Thread the pink string through the holes and tie it loosely behind the head with a bow, never a knot. It should rest against the nose, not press into it, if it leaves a mark, it is too tight."], ["The ears keep flopping on the headband. Fix?", "Tape each triangle with a tab folded over the band on both sides, not just stuck on one side. The double-sided tab is what keeps felt ears upright."]]}, "enchanted-castle-crew": {"m": ["Princess: yellow fabric, 2 yards (buy: fabric store)", "Prince: 1 blue jacket and 1 pair dark pants (make: use your closet)", "Candelabra: gold face paint, 1 tube, and 1 gold headband (buy: craft store)", "Clock: 1 brown cardboard circle, about 12 inches, and painted hands (make: from a box)", "Teapot: 1 white pot or cardboard pot body (make: from a box)", "Hot glue gun, 1; scissors, 1 pair; face paint, 1 set"], "s": ["Buy the yellow fabric, gold face paint, and gold headband. Assign roles first so nobody builds the same prop twice.", "Princess: wrap and pin the yellow fabric as a simple gown. Prince: wear the blue jacket and dark pants with a sash of torn fabric.", "Safety: let an adult handle the hot glue, and keep the face paint away from the eyes.", "Cut three flame shapes from cardboard first and arrange them dry on the gold headband to check the spacing. Glue them with the hot glue. Hot glue sets in seconds and cannot be repositioned, so the dry layout is the whole step.", "Safety: adults handle the scissors when cutting the cardboard.", "Clock: paint the brown cardboard circle cream and add painted hands. Teapot: cut a rounded cardboard pot body, add a handle and spout, and wear it over the shoulders.", "Optional pro finish: add a red fabric sash to the prince's blue jacket. The sash is the one detail that turns jacket-and-pants into royalty.", "Optional pro finish: add a red fabric sash to the prince's blue jacket. The sash is the one detail that turns jacket-and-pants into royalty."], "time": "40 min + drying", "cost": "$5-12", "effort": "Medium", "faqs": [["How do you assign roles without fights?", "Assign before shopping: princess, prince, candelabra, clock, teapot. Write them on a list and let the youngest pick first."], ["How do you keep the teapot body on?", "Cut arm holes in the cardboard pot body and wear it like a vest over the shoulders. A body with no arm holes slides off by the second photo."]]}, "bumble-bee": {"m": ["Black sweatshirt and sweatpants, 1 set (own, or buy: clothing store)", "Yellow duct or electrical tape, 1 roll (buy: dollar store)", "Black headband, 1 (buy: dollar store)", "2 yellow pipe cleaners, 12 inches each (buy: craft store, floral wire works too)", "2 black pom-poms, 1 inch (buy: craft store, cotton balls work too)", "Craft glue, 1 tube (buy: craft store)"], "s": ["Buy the yellow duct or electrical tape, black headband, yellow pipe cleaners, black pom-poms, and craft glue.", "Mark stripe positions with chalk or a light pencil first so the spacing is even. Wrap three yellow duct tape stripes around the torso of the black sweatshirt and one around each arm, even spacing is what makes it read as bee instead of random tape.", "Twist the two yellow pipe cleaners into a V.", "Safety: use non-toxic craft glue, and keep the pom-poms out of reach of toddlers.", "Glue a black pom-pom to each tip of the V with the craft glue. Glue the base of the V to the black headband.", "Let the glue dry fully, then pull on the black sweatshirt and sweatpants and the black headband.", "Optional pro finish: cut two white ovals from a plastic bag and tape them to the back as wings. Bees have wings; the ten seconds it takes doubles the recognition.", "Optional pro finish: cut two white ovals from a plastic bag and tape them to the back as wings. Bees have wings; the ten seconds it takes doubles the recognition."], "time": "20 min", "cost": "$5-10", "effort": "Easy", "faqs": [["Will duct tape stick to a sweatshirt all night?", "Yes on fleece and cotton. Press each stripe firmly and smooth from the center out. It peels off clean after one evening."], ["How do you keep the antennae upright?", "Twist the two pipe cleaners into a tight V and glue the base, not just the tips, to the headband. A wide glued base is what keeps them vertical."]]}, "baby-dino": {"m": ["Green hoodie, 1 (buy: clothing store, or use your own)", "2 sheets green craft felt, 9x12 inches each (buy: craft store, construction paper works too)", "Pillow stuffing or 2 old socks (make: stuff from home)", "Safety pins, 6 to 8 (buy: dollar store)", "Masking tape, 1 roll", "Scissors, 1 pair"], "s": ["Buy the green hoodie, green craft felt, and safety pins.", "Cut a paper triangle template first and test the size on the hoodie. Then cut 6 to 8 triangle spikes from the green craft felt with the scissors, spikes cut too small look lost on the back, so go palm-size.", "Tape the spikes in a row down the back of the green hoodie with the masking tape. Pin each spike from inside the hoodie with a safety pin.", "Stuff the old socks with the pillow stuffing and tape the open ends shut with the masking tape.", "Safety: pin everything from inside the green hoodie, so pin backs face the fabric and never the skin.", "Pin the stuffed tail to the back waistband of the green hoodie.", "Optional pro finish: cut two small white felt triangles and pin them to the hoodie cuffs as claws. Claws sell the dinosaur more than the spikes do.", "Optional pro finish: cut two small white felt triangles and pin them to the hoodie cuffs as claws. Claws sell the dinosaur more than the spikes do."], "time": "20 min", "cost": "$3-8", "effort": "Easy", "faqs": [["How many spikes does a baby dinosaur need?", "Six to eight palm-size triangles down the back reads as dinosaur instantly. Fewer looks sparse; more looks cluttered."], ["How do you make a dinosaur tail that stays up?", "Stuff two old socks firmly with pillow stuffing, tape the open ends shut, and pin the tail to the back waistband, not higher, or it flops forward."]]}, "little-lion": {"m": ["Tan or brown sweatsuit, 1 (buy: discount store, or use one you own)", "Brown fuzzy fabric strip or old brown towel for the mane, about 24 inches long (buy: fabric store, or make: cut from a towel)", "Scissors, 1 pair (own)", "Safety pins or fabric glue, 6 to 8 pins or 1 tube glue (buy: dollar store or craft store)", "Brown non-toxic face paint, 1 tube (buy: drugstore)"], "s": ["Buy the tan sweatsuit and the brown fuzzy fabric strip.", "Safety: adults handle the scissors when cutting the brown fuzzy fabric.", "Cut a paper collar template first and test it around the sweatsuit hood, a mane cut too small looks like a bib, and fuzzy fabric cut away cannot be put back. Then cut the brown fuzzy fabric into a wide collar for the mane, cutting generous and trimming after the fitting.", "Pin the mane around the hood or neckline of the tan sweatsuit with the safety pins, fluffing it outward.", "Paint a brown nose and whiskers with the brown face paint, keeping clear of the eyes.", "Pin the mane flat at the back so it does not slip over the eyes while the little lion runs.", "Optional pro finish: cut a small triangle tail from the leftover fuzzy fabric and pin it to the back waistband. The tail is what other kids point at.", "Optional pro finish: cut a small triangle tail from the leftover fuzzy fabric and pin it to the back waistband. The tail is what other kids point at."], "time": "20 min", "cost": "$3-8", "effort": "Easy", "faqs": [["How do you keep the mane out of the kid's face?", "Pin the mane around the hood or neckline, not the forehead, and fluff it outward. Pin the back of the mane flat so it cannot slip forward over the eyes when they run."], ["Safety pins or fabric glue for the mane?", "Pins for anything a toddler wears, you can reposition them, and glue needs 30 minutes of stillness no toddler provides. Glue works fine for older kids who will sit still."]]}, "tiny-firefighter": {"m": ["Red sweatsuit, 1 (own: from closet)", "Toy firefighter helmet, 1 (buy: toy store)", "Toy fire hose or coiled garden hose, 1 (buy: toy store, or borrow a real coil of rope from home)", "Yellow reflective tape, 1 roll (buy: hardware store)", "Black marker, 1 (own: from home)"], "s": ["Buy the toy firefighter helmet, toy fire hose, and yellow reflective tape. Dress the kid in the red sweatsuit.", "Make the turnout stripes: wrap two horizontal bands of the yellow reflective tape around each sleeve and each leg. Press the tape firmly so it sticks.", "Safety: keep the toy firefighter helmet snug so it does not slide over the eyes.", "Put the toy firefighter helmet on and carry the toy fire hose coiled over one shoulder.", "Finishing touch: the kid holds the hose nozzle out front for the hero photo.", "Optional pro finish: wrap one band of reflective tape around the toy helmet too, so the whole uniform matches.", "Optional pro finish: wrap one band of reflective tape around the toy helmet too, so the whole uniform matches."], "time": "25 min", "cost": "$8-15", "effort": "Easy", "faqs": [["Will the reflective tape come off the sweatsuit after?", "It peels off, but it can leave sticky residue on some fabrics. Test a hidden spot first, and use a thrifted sweatsuit if you want zero risk."], ["What if the toy helmet is too big and slides over the eyes?", "Stuff folded paper towel inside the helmet until it sits snug. Keep it snug enough that it never slides over the eyes."]]}, "little-shark": {"m": ["Gray hoodie, 1 (buy: thrift store, or own: from closet)", "Gray felt, 1 sheet 9x12 inches (buy: craft store; construction paper works too)", "White felt, 1 small sheet (buy: craft store; white paper works too)", "Fabric glue, 1 tube (buy: craft store)", "Scissors, 1 pair (own: household tools)"], "s": ["Buy the gray hoodie, gray felt, and white felt from the craft store. Gather the scissors and fabric glue.", "Cut a paper fin template first and hold it against the hoodie back, a fin cut too small disappears on the hoodie, and felt cut away cannot be put back. Then cut a triangle fin about 8 inches tall from the gray felt, and a jagged row of teeth from the white felt.", "Glue the teeth inside the hood edge of the gray hoodie so they show around the face.", "Glue the fin to the back of the gray hoodie, low between the shoulders.", "Let the fabric glue dry flat for 30 minutes.", "Zip the gray hoodie over a white t-shirt and pull the hood up for the shark face.", "Optional pro finish: glue two small black felt dots on the hood as eyes above the teeth. Eyes plus teeth is what makes it a shark face instead of a gray hood with trim.", "Optional pro finish: glue two small black felt dots on the hood as eyes above the teeth. Eyes plus teeth is what makes it a shark face instead of a gray hood with trim."], "time": "25 min + drying", "cost": "$3-8", "effort": "Easy", "faqs": [["How do the teeth stay glued to the hood?", "Fabric glue on the inside hood edge, pressed flat for 30 seconds per tooth, then left to dry flat for 30 minutes. Do not wear the hoodie until the glue is fully set or the teeth peel off."], ["Where exactly does the fin go?", "Low between the shoulders on the back, not up at the neck. A fin glued too high flops forward over the hood; low and centered stands upright when they walk."]]}, "walking-taco": {"m": ["Tan vest or tan t-shirt, 1 (own: from closet)", "Brown, red, green, and yellow felt sheets, 1 pack (buy: craft store; construction paper works too)", "Fabric glue, 1 bottle (buy: craft store)", "Headband, 1 (buy: dollar store)", "Scissors, 1 pair (own: from home)"], "s": ["Buy the felt pack, fabric glue, and headband.", "Dress the kid in the tan vest or tan t-shirt.", "Safety: cut the felt slowly and keep fingers clear of the scissors.", "Pin or lay the brown felt strips on the vest first and check the fold placement in a mirror before gluing, since glued felt cannot be repositioned. Glue two curved strips of brown felt down the front of the tan vest to form the shell fold.", "Make the toppings: cut wavy strips of green felt for lettuce and red circles for tomatoes. Cut yellow rectangles for cheese and brown blobs for beef. Glue them in a row across the chest and shoulders so they spill out like a taco filling.", "Make the headband garnish: glue one green felt strip and one red felt circle to the headband. Wear it with the vest as a lettuce and tomato topper.", "Optional pro finish: glue a fringe of thin yellow felt strips along the bottom edge of the vest so cheese spills out all around.", "Optional pro finish: glue a fringe of thin yellow felt strips along the bottom edge of the vest so cheese spills out all around."], "time": "45 min", "cost": "$5-10", "effort": "Easy", "faqs": [["Can you wash the vest after Halloween?", "No. The glued felt does not survive the washing machine. Spot clean only, and use a vest you are fine keeping as a costume."], ["Felt or construction paper for the toppings?", "Felt survives the whole night; construction paper tears and wilts with any moisture. Felt is worth it for a kid who will be running around."]]}, "ramen-bowl": {"m": ["Large cardboard circle, about 2 feet wide (make: cut from a big box)", "White and red acrylic paint, 2 small bottles (buy: craft store)", "Yellow yarn, 1 skein (buy: craft store; yellow string works too)", "White craft foam or 1 foam ball (buy: craft store; white paper works too)", "Chopsticks, 1 pair (own: kitchen drawer)", "Tape and string, 1 roll and about 2 feet (own: household)", "Scissors, 1 pair"], "s": ["Buy the white and red paint, yellow yarn, and white craft foam.", "Test the bowl rim size before cutting: hold the cardboard up and mark where it should sit as a hat. Cut the cardboard circle into a wide bowl rim shape with the scissors, cutting a little larger than you think since you can trim it down but cannot add cardboard back. Paint it white with a red stripe and let it dry fully, about 1 hour.", "Make the noodles: cut dozens of 12-inch yellow yarn strands. Fasten them in a tangled layer across the top of the dry bowl rim with the tape.", "Cut the white craft foam into a half egg shape and paint a yellow yolk dot on it. Let it dry, then tape the egg on top of the noodles and stick the chopsticks in at an angle.", "Wear the bowl rim like a hat with string under the chin, noodles and egg on top. Slurp loudly for effect.", "Optional pro finish: glue two real wooden chopsticks crossed at the top of the noodles, and tape a paper logo circle to the bowl rim so it reads as a branded ramen bowl.", "Optional pro finish: glue two real wooden chopsticks crossed at the top of the noodles, and tape a paper logo circle to the bowl rim so it reads as a branded ramen bowl."], "time": "50 min", "cost": "$8-12", "effort": "Easy", "faqs": [["How do you wear the bowl so it does not fall off?", "Wear the bowl rim like a hat with string tied under the chin, noodles and egg on top. Keep the string snug but loose enough to slip a finger under."], ["What can you use instead of yellow yarn for the noodles?", "Yellow string, shredded yellow paper, or thin strips of a yellow plastic bag all read as noodles. Tape them in a tangled layer so they look piled, not combed."]]}, "tiny-snail": {"m": ["Neutral beige or tan clothes, 1 set (own: from closet)", "Large cardboard sheet or 1 flattened box (own: from home)", "Brown and tan markers or crayons, 1 set (own: from home)", "Backpack straps, 2, or 2 long ribbons (own: from home)", "Headband, 1 (buy: dollar store)", "Black pom-poms, 2 (buy: craft store; cotton balls work too)", "Tape, 1 roll (own: from home)", "Scissors, 1 pair"], "s": ["Dress the kid in the beige or tan clothes.", "Buy the headband and black pom-poms.", "Safety: cut the cardboard slowly and keep fingers clear of the scissors.", "Draw the oval on the cardboard first and hold it against the kid's back to check the size before cutting, since a too-small shell cannot be fixed. Make the shell: cut the cardboard into a large oval. Draw a spiral from the center outward with the brown marker. Tape the two backpack straps to the back so it wears like a backpack.", "Make the eyestalks: tape two short cardboard strips to the headband so they point up. Tape a black pom-pom to the top of each strip.", "Wear the shell backpack and the headband with the pom-pom eyestalks. Keep the shell light and the straps snug so it rides comfortably.", "Optional pro finish: edge the shell oval with a tan marker border and add a second smaller spiral inside the first for a realistic shell pattern.", "Optional pro finish: edge the shell oval with a tan marker border and add a second smaller spiral inside the first for a realistic shell pattern."], "time": "30 min", "cost": "$3-8", "effort": "Easy", "faqs": [["How do you keep the shell light enough for a small kid?", "Use single-ply cardboard from a cereal-style box rather than a heavy shipping box, and keep the oval modest. Tape, don't glue, so it stays light."], ["How do you keep the eyestalks standing up?", "Use short cardboard strips, about 4 inches, and small pom-poms. Tall strips with big pom-poms flop over every time."]]}, "little-witch": {"m": ["Black cape or black bedsheet, 1 (buy: dollar store, or make: cut a cape from a black t-shirt)", "Pointy witch hat, 1 (buy: dollar store)", "Black-and-white striped tights, 1 pair (buy: thrift store or online)", "Green non-toxic face paint, 1 tube (buy: drugstore or craft store)", "Safety pin or ribbon, 1 (own: from the sewing kit)"], "s": ["Buy the pointy witch hat, black-and-white striped tights, and green face paint. Pull a black cape or black bedsheet from the closet.", "Pin the cape at the shoulders with the safety pin or tie it with ribbon.", "Paint the nose, chin, and forehead lightly green with a fingertip or sponge. Use non-toxic kids' green face paint only.", "Pull on the black-and-white striped tights and the pointy witch hat.", "Carry a branch from the yard as a broom if one is handy.", "Optional pro finish: tie the ribbon in a bow at the front of the cape instead of using a safety pin. A bow at the neck reads as costume; a visible safety pin reads as craft project.", "Optional pro finish: tie the ribbon in a bow at the front of the cape instead of using a safety pin. A bow at the neck reads as costume; a visible safety pin reads as craft project."], "time": "15 min", "cost": "$3-8", "effort": "Easy", "faqs": [["How much green face paint for a little witch?", "Just the nose, chin, and forehead dabbed on lightly with a fingertip or sponge. A fully green face looks great for ten minutes and then smears on everything they touch."], ["What if the cape is too long for a toddler?", "Pin it at the shoulders so it hits mid-back, and trim the bottom if it still drags. A cape that reaches the ground on a small kid is a tripping hazard on stairs."]]}, "spider": {"m": ["Black sweatshirt and black sweatpants, 1 set (own: from closet)", "Black socks, 8 (4 pairs, own: from the sock drawer)", "Newspaper or tissue paper, 3 to 4 sheets, for stuffing (own: from home)", "Thin black rope or black yarn, 4 feet (buy: craft store)", "Black fabric glue, 1 bottle, or a needle and black thread (buy: craft store)", "Large googly eyes, 2 (buy: craft store; drawn paper circles work too)", "White face paint, 1 tube (buy: craft store or costume aisle)"], "s": ["Buy the black yarn, black fabric glue or black thread, googly eyes, and white face paint. Lay the black sweatshirt flat.", "Stuff each of the 8 socks about half full with crumpled newspaper or tissue. Leave the top half empty so each leg can bend.", "Pin the stuffed socks in place on the sweatshirt first and check the spacing in a mirror before committing. Then use the black fabric glue or a few stitches to attach 4 stuffed socks down each side of the sweatshirt, spaced so they stick out like legs, since glued legs cannot be moved.", "Poke the black yarn through the middle of each stuffed sock and tie it for a knee bend. Glue one googly eye on each shoulder of the sweatshirt. Dress in the black sweatshirt and black sweatpants, then put on the leg-covered sweatshirt.", "Safety: use non-toxic face paint, and keep the googly eyes on the shoulders, not near the face.", "Dot the white face paint around the eyes as spider markings.", "Optional pro finish: run one long strand of black yarn across the back of the sweatshirt like a web anchor line, and add small white face-paint dots down the outside of each leg.", "Optional pro finish: run one long strand of black yarn across the back of the sweatshirt like a web anchor line, and add small white face-paint dots down the outside of each leg."], "time": "45 min", "cost": "$5-10", "effort": "Medium", "faqs": [["How do you keep the sock legs from drooping?", "Stuff each sock only half full and leave the top half empty so the leg can bend. Poke the black yarn through the middle of each sock and tie it for a knee bend, which holds the shape up."], ["Can the sweatshirt be washed after?", "Spot clean only. The glued-on legs will not survive a wash, so use a sweatshirt you are fine retiring to the costume bin."]]}, "backyard-hero": {"m": ["Old pillowcase or t-shirt for the cape, 1 (make: cut up)", "Solid-color t-shirt to wear, 1 (own)", "Cardstock or foam letter for the first initial, 1 sheet (make: cut from cardstock, or buy: craft store)", "Ribbon or string for cape ties, about 2 feet (own, or buy: craft store)", "Safety pins, 2", "Scissors, 1 pair"], "s": ["Measure first: hold the pillowcase against the back and mark waist length before cutting. Cut the cape with the scissors, a cape cut too short cannot be lengthened, so leave it long and trim after the first fitting.", "Cut the first initial from the cardstock with the scissors. Pin it to the chest of the solid-color t-shirt with a safety pin.", "Safety: keep the neck bow loose and easy to pull free. Never tie anything tight around the neck.", "Thread the ribbon through the top corners of the cape. Tie it at the front of the neck in a loose quick-release bow. Trim the ribbon ends with the scissors.", "Optional pro finish: outline the felt initial with a fabric marker in a contrasting color. The outline makes the emblem readable from across the yard.", "Optional pro finish: outline the felt initial with a fabric marker in a contrasting color. The outline makes the emblem readable from across the yard."], "time": "15 min", "cost": "$0-3", "effort": "Easy", "faqs": [["How long should a kid superhero cape be?", "Waist length for under-6s (no tripping), mid-back for older kids. When in doubt, cut long and trim after they try it on."], ["How do you attach a cape without sewing?", "Thread ribbon through the top corners and tie a loose quick-release bow at the front of the neck. Never tie it tight, it must pull free."]]}, "pickle": {"m": ["Green tunic or oversized green t-shirt, 1 (buy: thrift store, or own: from closet)", "Green bubble wrap or green pom-poms, about 20 bumps (buy: craft store, or make: twist bits of green fabric)", "Fabric glue, 1 tube (buy: craft store)", "Green non-toxic face paint, 1 tube (buy: drugstore)"], "s": ["Lay out all the bumps on the tunic DRY first and step back to check the pattern is even, once fabric glue sets, bumps cannot be moved. Space them in a loose grid so no bare patches show. Buy the green tunic, green bubble wrap, and green face paint, then glue the bumps all over the front and back of the green tunic for the bumpy pickle texture.", "Let the fabric glue dry flat for 30 minutes.", "Paint the face with the green face paint, then draw on a smug grin with one raised eyebrow.", "Wear the green tunic over regular clothes and stand tall.", "Optional pro finish: add a slightly darker green felt band at the top and bottom of the tunic. The bands frame the bumps and make it read as a whole pickle instead of a bumpy shirt.", "Optional pro finish: add a slightly darker green felt band at the top and bottom of the tunic. The bands frame the bumps and make it read as a whole pickle instead of a bumpy shirt."], "time": "30 min + drying", "cost": "$3-8", "effort": "Easy", "faqs": [["Bubble wrap or pom-poms for the bumps?", "Pom-poms look better and stay put; bubble wrap pops when people hug you and goes flat by midnight. If you use bubble wrap, pop it yourself first for a dimpled texture that lasts."], ["How much of the face should be green?", "Full face in a light layer, keeping it clear of the eyes. A half-green face reads as sick; a full light-green face with a smug grin reads as pickle."]]}, "vampire": {"m": ["Black cape or black bedsheet, 1 (buy cape: costume aisle; or make: from a black sheet from home)", "Black shirt and pants, 1 set (own: from closet)", "Plastic vampire fangs, 1 pair (buy: costume aisle or dollar store)", "Hair gel or pomade, 1 (own: from home)", "Red lipstick or red face paint, 1 (buy: pharmacy or costume aisle)", "White face powder or pale face paint, 1 (buy: costume aisle)"], "s": ["Buy the black cape, vampire fangs, pale face paint, and red lipstick if needed.", "Dress in the black shirt and pants.", "Make the hair: work the hair gel through the hair with your fingers. Press it straight back until it sits flat and slick.", "Safety: use non-toxic costume makeup, and skip the vampire fangs for small kids who might choke on them.", "Make the face: dust the pale face paint over the face and neck. Dab a thin line of red lipstick at each corner of the mouth like drips of blood.", "Wear the black cape over the shoulders and pop the vampire fangs in last before photos.", "Optional pro finish: paint the nails black and pop the cape collar up high, since the collar silhouette is what reads as vampire from across the room.", "Optional pro finish: paint the nails black and pop the cape collar up high, since the collar silhouette is what reads as vampire from across the room."], "time": "25 min", "cost": "$5-10", "effort": "Easy", "faqs": [["Are the plastic fangs safe for small kids?", "Skip the fangs for small kids who might choke on them. Draw two white fang triangles on the lower lip with face paint instead."], ["How do you get the pale face without buying special makeup?", "White face powder from the costume aisle is cheapest. Whatever you use, patch-test it first on sensitive skin and wash it off the same night."]]}, "bamboo-demon": {"m": ["Pink bathrobe or kimono-style robe, 1 (own, or buy: clothing store)", "Long dark wig, 1 (buy: toy store or online)", "1 cardboard tube from wrapping paper or paper towels (make: save from home)", "Ribbon or string, about 3 feet (own, or buy: craft store)", "Red non-toxic face paint, 1 tube (buy: toy store)", "Scissors, 1 pair", "Tape, 1 roll"], "s": ["Buy the long dark wig, ribbon, and red non-toxic face paint.", "Measure the tube against the face first and mark chin width. Cut the cardboard tube slightly LONG with the scissors, you can trim it down, but a tube cut too short cannot be fixed. Tape a length of ribbon to each end of the tube.", "Safety: keep the knot loose enough to talk and breathe easily. Never tie anything tight around the head or neck.", "Tie the cardboard tube across the mouth with the ribbon, knotting loosely at the back of the head.", "Pull on the pink bathrobe. Put on the long dark wig.", "Dab a small red mouth mark on the cardboard tube with the red non-toxic face paint.", "Optional pro finish: draw bamboo segment lines along the tube with a brown marker. Three quick lines turn a cardboard tube into a bamboo muzzle.", "Optional pro finish: draw bamboo segment lines along the tube with a brown marker. Three quick lines turn a cardboard tube into a bamboo muzzle."], "time": "20 min", "cost": "$5-12", "effort": "Easy", "faqs": [["How do you keep the muzzle comfortable?", "Tie the ribbon loosely at the back of the head with a bow, not a knot, so it can be loosened fast. It should rest against the mouth, never press on it."], ["What can I use instead of a wig?", "A dark towel draped over the head works for photos. The robe and muzzle carry the costume; the wig is optional."]]}, "emoji-crew": {"m": ["1 yellow t-shirt per person (buy: craft store, or use one you own)", "1 large white paper plate, 10-inch, or cardboard circle per person (make: use what you own)", "Markers in black, red, and blue, 1 set (make: use what you own)", "Scissors, 1 pair and tape, 1 roll"], "s": ["Buy yellow t-shirts if the crew does not own them.", "Safety: adults handle the scissors when cutting the paper plates or cardboard circles.", "Draw the emoji on the paper plate first in pencil, then go over it with the markers. Trim the plate or cardboard circle only where it overhangs the design. Cut small: a plate trimmed too far looks like a scrap.", "Tape the paper plate to the chest of the yellow t-shirt, centered like a face.", "Gather the crew in a row for photos, keeping the paper plates taped flat so they do not swing.", "Optional pro finish: outline the whole plate edge in black marker. The outline makes the face pop from across the room.", "Optional pro finish: outline the whole plate edge in black marker. The outline makes the face pop from across the room."], "time": "15 min", "cost": "$0-5", "effort": "Easy", "faqs": [["How do you pick emojis for the crew?", "Assign them first so nobody duplicates. Crowd-pleasers: heart-eyes, laughing-crying, and the sunglasses face. Let the shyest person take the poop emoji: it gets the biggest laugh."], ["How do you keep the plate from swinging?", "Tape it at four points, top, bottom, and both sides, so it sits flat on the chest. Two tape points lets it flap all night."]]}, "robot-crew": {"m": ["Medium cardboard box per person, 1 each (make: from home or moving boxes)", "Small cardboard box per person for the head, 1 each (make: from cereal or shoe boxes)", "Aluminum foil, 1 large roll (buy: grocery store)", "Plastic bottle caps, about 20 total (own)", "Duct tape, 1 roll (buy: hardware store)", "Black permanent marker, 1 (own)", "Elastic string or yarn, 6 feet (buy: craft store)", "Glow sticks, 1 per person (buy: dollar store)"], "s": ["Buy the aluminum foil, duct tape, glow sticks, and elastic string.", "Cut the eye holes BIG. You can cover extra space with foil, but you cannot add cardboard back. Cut the boxes slowly and keep fingers clear of the scissors.", "Cut head and arm holes in each medium cardboard box so they slide over the torso. Cut eye holes in the small cardboard boxes for heads.", "Wrap every box in aluminum foil, taping the foil down with duct tape. Draw dials and gauges on the chest with the black permanent marker. Tape the plastic bottle caps next to the dials as buttons.", "Wrap leftover aluminum foil around each arm from wrist to shoulder and tape the ends with duct tape. Or cut the armholes in the torso box big enough to slide bare arms through.", "Each person slides into a torso box and holds or ties the small cardboard box on their head. Tie the elastic string under the chin to keep the head box on. Crack a glow stick and tape it to the chest as a power light.", "Optional pro finish: give each robot a name badge ('UNIT 7', 'BEEP BOOP'). Named robots get talked to; unnamed robots get looked at. The badge is the personality.", "Optional pro finish: give each robot a name badge ('UNIT 7', 'BEEP BOOP'). Named robots get talked to; unnamed robots get looked at. The badge is the personality."], "time": "45 minutes", "cost": "$8-12", "effort": "Medium", "faqs": [["How do you keep a robot crew looking like a crew?", "Same silver, same box proportions, different button layouts. Uniform base plus unique details, that is the crew formula."], ["What is the best robot crew move?", "Move in sync, stop, turn heads together, beep in unison. Synchronized robots are ten times funnier than individual robots."]]}, "cereal-crew": {"m": ["Solid-color shirt and pants per person, 1 set each (own)", "Empty cereal boxes, 1 per person (make: save from home)", "Markers or crayons in assorted colors, 1 pack (own)", "String, about 4 feet per person (own)", "Scissors, 1 pair", "Tape, 1 roll"], "s": ["Each person invents a cereal name.", "Open the box along the side seam and flatten it BEFORE cutting, a flat box cuts cleanly, a 3D box wobbles. Cut the front panel off an empty cereal box with the scissors, keeping the panel as large as possible.", "Decorate the panel with the markers or crayons. Draw a mascot, add a prize burst, and write the cereal name in big letters.", "Tape string to the top corners of each panel with the tape.", "Wear the panel over the solid-color shirt like a sandwich board.", "Optional pro finish: add a 'prize inside' burst and a fake nutrition joke ('100% daily value of fun') in the corner. Real cereal boxes have fine print; yours should too.", "Optional pro finish: add a 'prize inside' burst and a fake nutrition joke ('100% daily value of fun') in the corner. Real cereal boxes have fine print; yours should too."], "time": "20 min", "cost": "$2-4", "effort": "Easy", "faqs": [["What makes a fake cereal name funny?", "Puns on the person's name or a group in-joke, in big block letters across the top. 'Captain Crunch' structure: [Title] + [Crunch/O's/Flakes]."], ["How do you wear a cereal panel?", "Tape string to the top corners and wear it like a sandwich board over the solid-color shirt. One panel on the front is enough, backs are optional."]]}, "decades-crew": {"m": ["Each person's own closet clothes (make: use what you own)", "1 printed decade card per person, e.g. 70s, 80s, 90s, cardstock or paper (make: hand-letter on paper)", "Scissors, 1 pair", "Tape, 1 roll or safety pins, 1 pack", "Hair gel or spray, 1 (buy: drugstore)"], "s": ["Everyone digs through their closet clothes and picks a different decade.", "Safety: adults handle the scissors when trimming the decade cards.", "Letter the decade card BIG, 4-inch letters minimum, because the card is the costume's label. Hand-letter a decade card on paper, like '80s, and tape it to each chest. A small card nobody can read defeats the purpose.", "Build each look with closet props only: bell-bottoms and a headband for the 70s. Neon and high socks for the 80s. Flannel tied at the waist for the 90s.", "Style hair with hair gel to sell the decade: a big part for the 70s. A scrunchie side-ponytail for the 80s.", "Keep props light so the looks survive a whole night of walking.", "Optional pro finish: give each decade one era-perfect prop, an inflatable microphone for the 80s, a fake vinyl record for the 70s. One prop per person keeps it cheap and specific.", "Optional pro finish: give each decade one era-perfect prop, an inflatable microphone for the 80s, a fake vinyl record for the 70s. One prop per person keeps it cheap and specific."], "time": "20 min", "cost": "$2-5", "effort": "Easy", "faqs": [["How do you keep decades from looking random?", "Assign decades first so no two people pick the same one, and give each person ONE signature item (neon for 80s, flannel for 90s). One signature item per decade beats five vague ones."], ["What is the fastest 90s look?", "Flannel tied around the waist over a plain tee, jeans, and a middle part. Three items, all from a closet, reads instantly."]]}, "under-the-sea": {"m": ["Jellyfish: 1 clear umbrella (buy: dollar store)", "Jellyfish: pastel ribbons, 1 spool (buy: craft store; crepe paper strips work too)", "Crab: red shirt and pants, 1 set, plus red mittens or red socks, 1 pair, for hands (own: from closet)", "Fish: silver or blue clothes, 1 set, and 1 large cardboard fish cutout (own: from home)", "Seaweed: green clothes, 1 set, and long green streamers, 1 pack (buy: party store)", "Waves: blue sheet or blue blanket, 1 (own: from home)", "Tape, 1 roll, and scissors, 1 pair (own: from home)"], "s": ["Assign one sea creature per person. Buy the clear umbrella, pastel ribbons, and green streamers. Pull the colored clothes from closets.", "Safety: cut the ribbons slowly and keep fingers clear of the scissors. Hold the clear umbrella high and keep the tentacle ribbons clear of faces.", "Cut one ribbon first and tape it to the umbrella edge to test the drape before cutting the rest. Jellyfish: cut the pastel ribbons into 3-foot lengths. Tape them to the edge of the clear umbrella so they dangle like tentacles. Hold the clear umbrella overhead.", "Crab: dress in red and slide the red mittens or red socks onto the hands. Hold both hands up with fingers pinched like claws. Fish: tape the cardboard fish cutout to the chest over the silver clothes.", "Seaweed: tape the green streamers to the shoulders and arms so they wave when the arms move. Everyone together can hold the blue sheet behind the group as a wave backdrop for the photo.", "Optional pro finish: tape small silver star stickers to the ribbons as bubbles, and give the fish a paper gill slit detail with marker.", "Optional pro finish: tape small silver star stickers to the ribbons as bubbles, and give the fish a paper gill slit detail with marker."], "time": "40 min", "cost": "$5-12", "effort": "Easy", "faqs": [["Is the umbrella safe in a crowd?", "Hold the clear umbrella high and keep the tentacle ribbons clear of faces. In tight crowds, carry it closed until there is room to open it."], ["What if it actually rains?", "The jellyfish wins: the umbrella is real and functional. The ribbons may get soggy, so use crepe paper only if the forecast is dry."]]}, "dino-rangers": {"m": ["Khaki shirt, 1, and khaki pants, 1 pair, per grown-up (make: use what you own)", "Green hoodie per child, 1 each (buy: thrift store, or use one you own)", "White paper or card, 2 sheets (make: use what you own)", "1 toy dinosaur or plush per kid (buy: toy store)", "Ribbon or string, 18 inches per kid (make: use what you own)", "Tape, 1 roll and scissors, 1 pair"], "s": ["Dress the grown-ups in the khaki shirt and pants, and roll the sleeves for the field-guide look.", "Buy or dig out the green hoodie for each kid, the toy dinosaur, and the ribbon.", "Safety: adults handle the scissors when cutting the white paper.", "Draw the eye spots on paper first and hold them against the hood to check the placement. Cut two oval eye spots from the white paper with the scissors, about 3 inches tall. Cut them smaller than you think: oversized eyes slide off the hood sides.", "Safety: skip small plastic dinosaur toys for kids under three, since they are a choking hazard.", "Loop the ribbon around the toy dinosaur like a leash, and tie the other end to the kid's wrist. Keep the leash short so the toy dinosaur does not drag.", "Optional pro finish: write each kid's dinosaur name on masking tape and stick it on the khaki shirt like a field badge. Ranger plus name tag sells the explorer story.", "Optional pro finish: write each kid's dinosaur name on masking tape and stick it on the khaki shirt like a field badge. Ranger plus name tag sells the explorer story."], "time": "15 min", "cost": "$5-10", "effort": "Easy", "faqs": [["Is the wrist leash safe for a kid?", "Yes if you use a loose loop tied over the jacket sleeve, never tight on bare skin, and keep it short so it cannot catch on playground equipment."], ["What if we have no khaki clothes?", "Any neutral shirt and pants work: tan, olive, or beige. Roll the sleeves twice and the field-guide look comes through."]]}, "board-game-pieces": {"m": ["Black or white monochrome clothes, 1 set per person (own)", "Large cardboard boxes, 2 to 3 (make: collect spares)", "White and black acrylic paint, 1 small bottle each (buy: craft store, tempera paint works too)", "Paintbrushes, 1 wide and 1 detail", "Black marker, 1 (buy: dollar store)", "Ribbon or string for straps, about 4 feet per board (own)", "Scissors, 1 pair", "Tape, 1 roll"], "s": ["Each person picks a game piece to be.", "Sketch each piece on the cardboard with marker BEFORE cutting. Cut a cube shape from a large cardboard box for the die with the scissors, measure the head first and cut the opening small, widening as needed. Cut flat boards from another box for the playing card and the domino.", "Paint the die and card white and the domino black with the acrylic paint and paintbrushes. Let the paint dry fully.", "Add dots and card symbols with the black marker and the white acrylic paint once the base coats are dry.", "Safety: cut the die box eye holes generously so you can see clearly. Only wear the die box once all paint is fully dry.", "Tape ribbon straps to the flat boards so they hang front and back over the black or white monochrome clothes. Wear the die box over the head with the eye holes lined up.", "Optional pro finish: paint a thin gold border around the card and domino edges. The border is what makes them read as game pieces instead of painted cardboard.", "Optional pro finish: paint a thin gold border around the card and domino edges. The border is what makes them read as game pieces instead of painted cardboard."], "time": "45 min + drying", "cost": "$5-10", "effort": "Medium", "faqs": [["Which game pieces are easiest to recognize?", "The die (white cube, black dots), a playing card (white board, big red heart), and a domino (black board, white dots). Pick pieces with strong silhouettes."], ["How do flat boards stay on?", "Tape ribbon straps to the top corners so they hang front and back like a sandwich board over the monochrome clothes. Two straps, not one, so nothing spins."]]}, "rain-cloud-rainbow": {"m": ["Gray t-shirt or sweatshirt, 1 (buy: thrift store, or own: from closet)", "White cotton balls or polyester stuffing, 1 bag (buy: dollar store or craft store)", "Blue paper raindrops, about 15 (own: cut from blue construction paper)", "String, 1 spool, and tape, 1 roll (own: household tools)", "Fabric glue, 1 tube (buy: craft store)", "Rainbow-striped shirt, 1, or a white shirt, 1, plus rainbow fabric markers, 1 set (buy: thrift store or craft store)", "Blue non-toxic face paint for one rain streak, 1 tube (buy: drugstore, optional)"], "s": ["Buy the gray t-shirt, white cotton balls, fabric glue, and rainbow-striped shirt or rainbow fabric markers.", "Arrange the cotton balls on the shirt DRY first and step back to check the cloud coverage, once fabric glue sets, cotton balls cannot be moved. Plan for full coverage with no gray showing through the middle. Then glue the cotton balls in clumps across the gray t-shirt to make clouds.", "Fix the blue paper raindrops to short pieces of string with tape. Hang the strings from the bottom edge of the gray t-shirt so they dangle.", "The rainbow person: wear the rainbow-striped shirt, or draw rainbow arcs across a white shirt with the rainbow fabric markers.", "Stand side by side: the cloud holds arms out wide. The rainbow stands just behind, peeking out after the 'storm'. Add one blue rain streak on a cheek with the blue face paint if you like.", "Optional pro finish: hang the raindrops at staggered lengths, not all even. Uneven drops look like real rain; a straight row looks like a mobile.", "Optional pro finish: hang the raindrops at staggered lengths, not all even. Uneven drops look like real rain; a straight row looks like a mobile."], "time": "30 min + drying", "cost": "$4-10", "effort": "Easy", "faqs": [["How many cotton balls for a full cloud shirt?", "Most of a dollar-store bag, plan on 40 to 60 for an adult shirt, 25 to 35 for a kid. Skimpy clouds show gray through the middle and read as lint, not weather."], ["How do the raindrops stay hanging?", "Fix each blue paper raindrop to a short piece of string with tape, then tape the strings along the bottom edge of the shirt. Short strings, about 4 inches, tangle less than long ones."]]}, "doctor-bride": {"m": ["1 old dark suit or jacket (make: use what you own)", "Green face paint, non-toxic, 1 tube (buy: drugstore)", "2 plastic neck bolts, costume style (buy: craft store; foil-covered cardboard tubes work too)", "1 white dress or old white sheet (make: use what you own)", "White hair spray, 1 can (buy: drugstore)", "Tape, 1 roll or glue, 1 bottle", "Scissors, 1 pair", "Dark eye shadow, 1 (make: use what you own)"], "s": ["Buy the green face paint, plastic bolts, and white hair spray.", "Safety: keep face paint away from the eyes, and patch-test it first on sensitive skin. Wash it off the same night.", "The Doctor: paint the face and neck green with the green face paint.", "Tape the two plastic bolts to the sides of the neck, and wear the dark suit with the collar up.", "Put the white dress or sheet on first and mark the tear line with tape: knee length for walking, longer for photos. Tear the bottom hem into strips with your hands, starting with small tears you can widen. Torn fabric cannot be untorn, so start shorter than you want.", "Smudge dark eye shadow under the eyes.", "Optional pro finish: smudge a little green face paint onto the bride's neck and hands too. The green spreading to the bride ties the two halves of the costume together.", "Optional pro finish: smudge a little green face paint onto the bride's neck and hands too. The green spreading to the bride ties the two halves of the costume together."], "time": "25 min", "cost": "$5-12", "effort": "Easy", "faqs": [["How do you keep the neck bolts on?", "Tape each bolt to the collar, not the skin, with two strips of fashion tape or bandage tape. Skin-safe tape only: never superglue."], ["Will white hair spray wash out?", "Yes with one shampoo. Spray it outside, keep it off clothes, and test a strand first on very dark hair since it can tint temporarily."]]}, "breakfast-buffet": {"m": ["Cardboard sheets, 1 per person about 2x2 feet (make: cut from boxes)", "Markers in assorted colors, 1 pack (own, or buy: dollar store)", "String or yarn, about 4 feet per person (own)", "Scissors, 1 pair"], "s": ["Each person picks a breakfast item.", "Draw the food on paper FIRST to plan the layout, then cut a large circle or rectangle from the cardboard sheets with the scissors. Draw big, the food must read from across the room, so fill the whole board.", "Draw the food big on the cardboard with the markers. Draw a fried egg, bacon strips, buttered toast, a pancake stack, a glass of OJ, or a coffee mug.", "Safety: an adult pokes the holes in the top corners with the tip of the scissors, since pushing through cardboard takes force.", "Thread the string through the holes and wear the sign over normal clothes like a sandwich board.", "Optional pro finish: make one extra small sign that says 'BREAKFAST BUFFET, all you can eat' and have the tallest person carry it. The sign turns five food boards into one group costume.", "Optional pro finish: make one extra small sign that says 'BREAKFAST BUFFET, all you can eat' and have the tallest person carry it. The sign turns five food boards into one group costume."], "time": "25 min", "cost": "$2-5", "effort": "Easy", "faqs": [["What breakfast foods read best on a sign?", "Fried egg, bacon strips, and a coffee mug, all three are recognizable in three marker strokes. Pancakes need more detail; skip them unless someone is artistic."], ["How do you wear a cardboard sign comfortably?", "Two strings through the top corners, worn like a sandwich board over normal clothes. Keep the board at chest height so it does not bang knees."]]}, "ghost-hunters": {"m": ["1 khaki or tan jumpsuit, or matching shirt and pants, per person (buy: thrift store)", "1 small cardboard box per person, shoebox size (make: use what you own)", "White paper, 2 sheets, and markers for name patches (make: use what you own)", "1 sheet black cardboard per person (make: from a box)", "Packing tape or glue, scissors"], "s": ["Buy the khaki jumpsuit or matching shirt and pants for each person.", "Tape the small cardboard box shut for the backpack.", "Safety: adults handle the scissors when cutting the black cardboard.", "Draw the straps, dial, and hose shapes on the black cardboard with marker first and hold them against the box to check the size. Cut them with the scissors. Cut the hose shape last and widest: it is the most visible piece.", "Mark each last name on the white paper with the markers. Tape it to the chest as a name patch.", "Wear the backpack over the jumpsuit, and keep the box small and light so kids can wear it all night.", "Optional pro finish: write each person's last name on the white paper patch in block letters and tape it to the chest. The name patch is the detail that turns khaki clothes into a uniform.", "Optional pro finish: write each person's last name on the white paper patch in block letters and tape it to the chest. The name patch is the detail that turns khaki clothes into a uniform."], "time": "30 min", "cost": "$5-12", "effort": "Easy", "faqs": [["How do you keep the backpack box light enough for kids?", "Use a small box, shoebox size max, and tape it shut empty. Kids wear it all night only if it weighs almost nothing."], ["How do you attach the box to the back?", "Tape two ribbon straps to the box like a backpack. Tape alone on the shirt peels; straps distribute the weight."]]}, "haunted-animatronics": {"m": ["1 large cardboard box per person, big enough to cover the head (make: use what you own)", "2 red LED tea lights per person (buy: dollar store)", "Paint in gray, black, and one accent color, 1 small bottle each (buy: craft store)", "1 set old clothes with holes or tears (make: use what you own)", "Hot glue gun, 1; scissors, 1 pair; utility knife, 1 (adults only)"], "s": ["Buy the red LED tea lights and the paint. Pull the old clothes with holes and the large cardboard boxes from home.", "Safety: an adult handles the utility knife and the hot glue for every cut and glue step.", "Mark the eye holes and the wide jagged mouth on the OUTSIDE of the box first, then have the wearer hold the box up to check the eye placement before any cutting. Cut with the utility knife, adults only, cutting the eye holes generous and the mouth wide. Cardboard cut away cannot be put back, and small eye holes make a blind hazard.", "Paint the box gray with black scuffs and cracks. Glue one red LED tea light inside each eye hole.", "Safety: make the eye holes large, and never wear the box near stairs or traffic, since side vision is limited.", "Wear the box over the head with the eyes lined up to the holes. Wear the old clothes with holes underneath, and move in short jerky steps, freezing between moves.", "Optional pro finish: paint black scuffs and cracks around the eye holes before adding the lights. The damage detail is what reads as haunted instead of just boxy.", "Optional pro finish: paint black scuffs and cracks around the eye holes before adding the lights. The damage detail is what reads as haunted instead of just boxy."], "time": "60 min + drying", "cost": "$8-15", "effort": "Medium", "faqs": [["How do you see out of a box on your head?", "Cut the eye holes large and line your eyes up to them before the paint goes on. Never wear it near stairs or traffic: side vision is almost zero."], ["How do the red eyes stay lit all night?", "LED tea lights run 24 hours plus on one battery. Tape one inside each eye hole with the light facing out, and carry a spare set just in case."]]}, "mystery-crew": {"m": ["Orange, purple, blue, and red t-shirts, 1 each (buy: thrift store, or own: from closet)", "Dog ears headband or a brown dog costume piece, 1 (buy: dollar store)", "Fake magnifying glass, 1 (buy: dollar store, or make: a paper circle taped to a stick)", "Headband or scarf in a matching color, 1 per person (own: from the drawer)", "Brown non-toxic face paint for the dog's nose, 1 tube (buy: drugstore)"], "s": ["Buy the dog ears headband and the fake magnifying glass.", "Assign roles: orange leader, purple style icon, blue brains, red goofball, and the dog wears the ears.", "Each person: put on their color's t-shirt and tie a matching headband or scarf.", "The brains carries the fake magnifying glass. Paint a brown nose on the dog with the brown face paint.", "Group the four humans in a line with the dog in front. All point at something suspicious for the classic pose.", "Optional pro finish: write each person's role on a small paper name tag ('the brains', 'the leader'). The tags turn colored shirts into characters for anyone who does not know the reference.", "Optional pro finish: write each person's role on a small paper name tag ('the brains', 'the leader'). The tags turn colored shirts into characters for anyone who does not know the reference."], "time": "15 min", "cost": "$2-6", "effort": "Easy", "faqs": [["How do you assign the colors so people get the joke?", "Orange leader, purple style icon, blue brains, red goofball, and the dog wears the ears. Assign before anyone dresses so no two people grab the same color."], ["What if we only have four people, no dog?", "Give the fourth person the dog ears over their colored shirt, the dog role is the most recognizable part, so it beats having a second of any human color."]]}, "headless-horsemen": {"m": ["Black cape or black sheet, 1 per person (buy: dollar store, or own: black sheet)", "Small jack-o-lantern bucket or foam pumpkin, 1 per person (buy: dollar store)", "Broom or stick-horse substitute, 1 per person (own: broom from home)", "Tape, 1 roll (own)", "Glow bracelets, 1 pack (buy: dollar store)"], "s": ["Buy the black cape, the jack-o-lantern bucket, and the glow bracelets.", "Drape the black cape or black sheet over the shoulders.", "Safety: keep your real head tucked low so you can see the ground.", "Tuck the chin into the chest, and hold the jack-o-lantern bucket up at shoulder height like a carried head.", "Add a glow bracelet to each wrist so drivers can see you in the dark.", "Hold the broom between the legs like a horse, and gallop in a group line.", "Optional pro finish: put a battery tea light inside each jack-o-lantern bucket. A glowing 'head' reads from a block away and keeps the group visible.", "Optional pro finish: put a battery tea light inside each jack-o-lantern bucket. A glowing 'head' reads from a block away and keeps the group visible."], "time": "20 min", "cost": "$2-8", "effort": "Easy", "faqs": [["How does the rider see if their head is tucked?", "Tuck the chin but keep the eyes looking forward under the cape edge, the cape drapes like a hood, it does not cover the face. If vision is blocked at all, ditch the tuck and just carry the bucket high."], ["What do we use if we have no capes?", "Black trash bags with head and arm holes cut out, or any dark blanket. The silhouette is what matters: dark shoulders plus a glowing pumpkin at head height."]]}, "haunted-portraits": {"m": ["1 set old-fashioned dark clothes per person, e.g. a vest, long skirt, or button-up (make: use your closet)", "Gray and white face paint, non-toxic, 1 set (buy: drugstore)", "1 large picture frame or cardboard frame per person (buy: thrift store for the frame, or make from cardboard)", "Hair spray or powder for a grayed look, 1 (buy: drugstore)"], "s": ["Buy the gray and white face paint and the hair powder.", "Paint each face pale gray with white highlights on the cheekbones and nose, using the gray and white face paint.", "Gray the hair with the hair powder.", "Dress in the old-fashioned dark clothes from the closet.", "Hold the picture frame or cardboard frame up around the face like a living portrait.", "Pose together in a row of frames for group photos, keeping the face paint light around the eyes.", "Optional pro finish: dust the hair with the gray powder and add white highlights on the cheekbones and nose. The highlights are what read as painted portrait instead of just pale.", "Optional pro finish: dust the hair with the gray powder and add white highlights on the cheekbones and nose. The highlights are what read as painted portrait instead of just pale."], "time": "25 min", "cost": "$5-12", "effort": "Easy", "faqs": [["How do you hold the frame up all night?", "You do not: use it for photos only, and set it down between shots. Holding a frame for hours is exhausting; the portrait pose is a photo bit."], ["How do you gray the face without looking dirty?", "Paint the face pale gray, not dark, and add white highlights on the cheekbones and nose. Dark gray reads as dirt; pale gray with highlights reads as a painting."]]}, "goggle-crew": {"m": ["1 yellow t-shirt per person (buy: craft store, or use one you own)", "1 pair denim overalls per person (buy: thrift store, or use one you own)", "1 pair swim or safety goggles per person (buy: toy store)", "1 pair black gloves per person (buy: dollar store)"], "s": ["Buy the yellow t-shirts, denim overalls, goggles, and black gloves.", "Each person puts on the yellow t-shirt, the denim overalls, and the black gloves.", "Push the goggles up on the forehead like safety gear, not over the eyes, so everyone can see.", "Walk in a pack and greet people in gibberish for the full effect.", "Skip any real tools or hard hats so the look stays clearly costume, not work gear.", "Optional pro finish: push the goggles up on the forehead, never over the eyes. Forehead goggles are the character's signature; over the eyes you just look like a swimmer.", "Optional pro finish: push the goggles up on the forehead, never over the eyes. Forehead goggles are the character's signature; over the eyes you just look like a swimmer."], "time": "10 min", "cost": "$10-20", "effort": "Easy", "faqs": [["Do the overalls have to be denim?", "Denim reads best, but any overalls work. The yellow shirt plus goggles carry the costume; the overalls are the bonus."], ["How do you do the voice without annoying everyone?", "Keep the gibberish to greetings and photos, then talk normally. Full-time gibberish is funny for ten minutes and exhausting by hour two."]]}, "garden-gnome": {"m": ["Earth-tone shirt and pants, 1 set (own)", "Cardboard for the hat, 1 sheet (make: from a box)", "Blue paint for the hat, 1 small bottle (buy: craft store)", "White face paint for the beard, non-toxic, 1 tube (buy: drugstore)", "Toy fishing rod or small garden shovel, 1 (buy: dollar store)", "Scissors, 1 pair", "Tape, 1 roll"], "s": ["Buy the blue paint, the white face paint, and the toy fishing rod.", "Safety: adults handle the scissors when cutting the cardboard.", "Cut the sheet cardboard to size, roll it into a tall cone, and tape it shut.", "Paint the cone with the blue paint for the hat, and let it dry.", "Test the face paint on the inside of the wrist first and wait 10 minutes, kids' skin reacts more than you expect. Use the brown and black non-toxic face paint to draw a round nose and rosy cheeks. Keep all paint clear of the eyes and mouth.", "Wear the cone hat with the earth-tone shirt and pants, and carry the toy fishing rod.", "Optional pro finish: carry a tiny watering can or a foam mushroom. Gnomes have props, the hat and beard say gnome, the watering can says garden gnome.", "Optional pro finish: carry a tiny watering can or a foam mushroom. Gnomes have props, the hat and beard say gnome, the watering can says garden gnome."], "time": "30 minutes + drying", "cost": "$5-10", "effort": "Easy", "faqs": [["How tall should the gnome hat be?", "About as tall as the head. Too short reads as a party hat; too tall flops. Roll the cone, tape it, and test the height before painting."], ["Will the face-paint beard smear?", "Let it dry fully before the hat goes on, and keep it below the mouth. Bring the tube for touch-ups; white shows every smudge."]]}, "black-cat": {"m": ["Black shirt and pants or sweatsuit, 1 set (own)", "Plain headband, 1 (buy: dollar store)", "1 sheet black craft felt, 9x12 inches (buy: craft store, construction paper works too)", "Black construction paper, 1 sheet (make: cut a mask from it)", "Black non-toxic face paint, 1 tube (buy: toy store)", "Small drawstring bag or pillowcase, 1 (own)", "Scissors, 1 pair", "Tape, 1 roll"], "s": ["Buy the plain headband, black craft felt, and black non-toxic face paint.", "Cut two triangle ears from the black craft felt with the scissors, about 4 inches tall. Cut one eye mask shape from the black construction paper.", "Tape the ears upright to the plain headband.", "Safety: cut the eye holes wide in the mask so vision stays clear.", "Tape the mask on with long tape tabs at the temples. Or draw whiskers with the black non-toxic face paint.", "Pull on the black shirt and pants and put on the plain headband. Carry the small drawstring bag over one shoulder.", "Optional pro finish: tape three pipe cleaners to each cheek as whiskers instead of drawing them. Real whiskers catch the light and photograph ten times better.", "Optional pro finish: tape three pipe cleaners to each cheek as whiskers instead of drawing them. Real whiskers catch the light and photograph ten times better."], "time": "20 min", "cost": "$3-8", "effort": "Easy", "faqs": [["How do you make cat ears stand up?", "Cut the triangles 4 inches tall and tape them to the headband with a 1-inch tape tab folded over the band on both sides. Felt alone flops; the double-sided tape tab is the trick."], ["Mask or face paint whiskers for a toddler?", "Face paint. A paper mask slips on small faces and the eye holes never line up. Paint three whisker lines per cheek and skip the mask."]]}, "block-monster": {"m": ["Solid-color sweatsuit, any color, 1 set (own)", "1 large cardboard box (make: cut it into square blocks)", "Packing tape, 1 roll", "Scissors, 1 pair", "Non-toxic face paint, 1 tube (buy: toy store)"], "s": ["Cut the large cardboard box into square blocks with the scissors: two large (shoulder size), four medium (forearm and shin size). Test-hold each block against the body BEFORE taping, blocks taped in the wrong spot look lopsided all night.", "Tape one large block to each shoulder with the packing tape.", "Tape one medium block to each forearm and shin with the packing tape.", "Pull on the solid-color sweatsuit under the blocks.", "Safety: keep the face paint clear of the eyes.", "Draw a blocky square-toothed grin on the face with the non-toxic face paint.", "Optional pro finish: edge every block with silver duct tape. The metallic edge catches light and makes cardboard read as robot armor.", "Optional pro finish: edge every block with silver duct tape. The metallic edge catches light and makes cardboard read as robot armor."], "time": "30 min", "cost": "$3-8", "effort": "Easy", "faqs": [["How do the blocks stay on?", "Packing tape loops: tape the block to the sweatsuit sleeve or pant leg with two strips. Tape sticks to fabric well enough for one evening and peels off after."], ["What size blocks for a small kid?", "Halve everything: medium blocks become the shoulder blocks. Oversized blocks on a small kid drag and bump doorways."]]}, "space-crewmate": {"m": ["Plain sweatsuit in one solid color, red recommended, 1 set (own: from closet)", "Cardboard, 1 sheet about 12x16 inches (own: from a box flap)", "Aluminum foil, about 2 feet (own: from the kitchen)", "Backpack straps, 2, or 2 long shoelaces (own: from home)", "Markers, 3 to 4 colors (own: from home)", "Tape, 1 roll (own: from home)", "Scissors, 1 pair"], "s": ["Dress in the solid-color sweatsuit.", "If you have more than one person, give each a different color.", "Wrap the cardboard in aluminum foil for the backpack. Draw vents, dials, and one big red button with the markers. Tape the two backpack straps to the back of the cardboard.", "Wear the foil backpack with the straps over your shoulders. Tape the bottom corners snug to the sweatsuit so it does not swing.", "Finishing touch: hold one finger to your lips and say sus for the photo.", "Optional pro finish: draw a crewmate ID badge on an index card (name, color, and CREW) and tape it to the chest.", "Optional pro finish: draw a crewmate ID badge on an index card (name, color, and CREW) and tape it to the chest."], "time": "20 min", "cost": "$0-5", "effort": "Easy", "faqs": [["How do you keep the foil backpack from swinging?", "Tape the bottom corners of the cardboard snug to the sweatsuit after the straps are on. Snug at the bottom stops the swing."], ["What if more than one person wants to be the same color?", "Give each person a different color sweatsuit. The joke lands harder when the group has red, blue, yellow, and one suspicious black."]]}, "sun-moon": {"m": ["Yellow shirt and pants for the Sun, 1 set (own: from closet)", "Navy or black shirt and pants for the Moon, 1 set (own: from closet)", "Yellow cardstock, 2 sheets (buy: craft store; construction paper works too)", "Silver star stickers, 1 sheet (buy: craft store; cut paper stars work too)", "White and yellow paper, 1 sheet each, for the crescent (own: from home)", "Tape, 1 roll, and scissors, 1 pair (own: from home)"], "s": ["One person dresses head to toe in yellow, the other in navy or black.", "Buy the yellow cardstock and the silver star stickers.", "Safety: cut the cardstock slowly and keep fingers clear of the scissors.", "Cut one ray first and tape it to the neckline to test the length before cutting the other nine, since cardstock cannot be lengthened. Make the sun rays: cut 10 long triangles from the yellow cardstock, then tape them around the neckline and sleeves of the yellow shirt so they point outward.", "Cut a large crescent from the white paper and tape it to the chest of the navy shirt. Scatter the silver star stickers across the shirt and arms.", "Finishing touch: the Sun spreads arms wide to show the rays while the Moon holds one hand near the crescent.", "Optional pro finish: glue the rays in pairs back to back so they are stiff and yellow on both sides, and edge the crescent with silver marker.", "Optional pro finish: glue the rays in pairs back to back so they are stiff and yellow on both sides, and edge the crescent with silver marker."], "time": "40 min", "cost": "$5-8", "effort": "Easy", "faqs": [["How do you keep the sun rays from flopping over?", "Tape each ray in pairs back to back so the cardstock is double thick, and tape a full inch of the ray base flat to the shirt. Short wide triangles flop less than long skinny ones."], ["Will the tape damage the shirts?", "Masking tape or painter's tape peels off clean. Packing tape holds better but can pull at fabric, so stick with the gentler tapes on clothes you want to keep."]]}, "moth-porch-light": {"m": ["Neutral shirt and pants in gray, brown, or tan, 1 set (own: from closet)", "Large cardboard box, 1 (own: cut two wing shapes from it)", "Brown and tan markers or paint, 1 set (buy: craft store)", "Brown craft pipe cleaners, 2 (buy: craft store; brown yarn works too)", "Headband, 1 (own: from the drawer)", "Yellow t-shirt and yellow pants, 1 set (buy: thrift store, or own: from closet)", "Cone lampshade, 1 (buy: thrift store)", "Tape, 1 roll, and scissors, 1 pair (own: household tools)"], "s": ["Draw both wing ovals on the box first and have the moth hold their arms out to check the span, wings cut too small look like shoulder pads, and cardboard cut away cannot be put back. Cut two large oval wing shapes from the large cardboard box with the scissors. Buy the brown craft pipe cleaners, brown and tan markers, and cone lampshade.", "Draw eye spots and scalloped edges on the wings with the brown markers. Tape one wing to each arm of the neutral shirt and pants.", "Bend the brown craft pipe cleaners into feathery antennae and tape them to the headband for the moth.", "Put on the yellow t-shirt and yellow pants. Pop the cone lampshade over the head like a lampshade hat.", "Stand next to the moth with arms out, buzzing.", "Optional pro finish: curl the wing tips slightly forward and tape them so they cup inward. Real moth wings curve; flat cardboard reads as a sign.", "Optional pro finish: curl the wing tips slightly forward and tape them so they cup inward. Real moth wings curve; flat cardboard reads as a sign."], "time": "40 min", "cost": "$5-10", "effort": "Medium", "faqs": [["How do the wings stay on the arms?", "Tape one wing to each sleeve of the neutral shirt with two strips of tape per wing. Tape on fabric holds for an evening; tape the wings to the sleeves, not to skin."], ["What size lampshade for the porch light person?", "One that fits over the head like a hat without covering the eyes, a medium table-lamp shade works. Check thrift stores; they are a dollar or two."]]}, "raptor-ranger": {"m": ["Khaki shirt and hat for the ranger, 1 set (own: from closet, or buy at a thrift store)", "Green hoodie or green t-shirt for the raptor, 1 (own: from closet)", "Green felt sheet, 9x12 inches, 1 (buy: craft store; construction paper works too)", "Rope, 3 feet, or 1 toy dog leash (buy: pet aisle)", "Face paint, green and black, 1 set (buy: costume aisle or craft store)", "Scissors, 1 pair, and tape, 1 roll (own: household)"], "s": ["Decide who is the ranger and who is the raptor, then lay out both outfits. Buy the 3 ft rope or toy dog leash and the face paint if you do not have them.", "Safety: cut the green felt sheet slowly and keep fingers clear of the scissors.", "Draw the tail shape on the felt first and hold it up to the raptor's back to check the length before cutting, since a too-short tail cannot be lengthened. Then cut one long triangle from the green felt sheet for the tail. Tape it to the back of the raptor's green shirt so it hangs behind them.", "The ranger wears the khaki shirt and hat with the toy dog leash in hand. The raptor wears the green shirt with the tail attached.", "Safety: use non-toxic kids face paint, and skip any mask so the raptor can see clearly.", "Paint the raptor's snout: use the green face paint to draw a snout and two black dots for nostrils. Then the ranger holds the toy dog leash out toward the raptor for photos.", "Optional pro finish: tie the rope as a belt around the ranger's waist and clip a toy walkie-talkie to it for the field-guide look.", "Optional pro finish: tie the rope as a belt around the ranger's waist and clip a toy walkie-talkie to it for the field-guide look."], "time": "25 min", "cost": "$3-8", "effort": "Easy", "faqs": [["How long should the leash be?", "Keep the leash short, about 2 to 3 feet, so the toy dinosaur does not drag on the ground. Tie the wrist end in a loop so it cannot tighten."], ["What face paint is safe for kids?", "Use non-toxic kids face paint and skip any mask so the raptor can see clearly. Keep paint off the lips and wash it off the same night."]]}, "cat-mouse": {"m": ["2 headbands (buy: dollar store)", "1 sheet black craft felt, 9x12 inches (buy: craft store, construction paper works too)", "1 sheet gray craft felt, 9x12 inches (buy: craft store, construction paper works too)", "Black eyeliner pencil or non-toxic face paint, 1 (buy: toy store)", "Scissors, 1 pair", "Tape, 1 roll"], "s": ["Buy the headbands, black craft felt, gray craft felt, and black eyeliner pencil.", "Cut one paper ear template first, triangles for the cat, rounds for the mouse, and check both against the headbands. Cut two triangle ears from the black craft felt with the scissors.", "Cut two round ears from the gray craft felt with the scissors, about 3 inches across.", "Safety: keep the eyeliner clear of the eyes.", "Put on the headbands and draw whiskers on both faces with the black eyeliner pencil.", "Optional pro finish: glue a pink felt triangle inside each ear. Inner ears are the five-second detail that makes both animals read instantly.", "Optional pro finish: glue a pink felt triangle inside each ear. Inner ears are the five-second detail that makes both animals read instantly."], "time": "15 min", "cost": "$3-6", "effort": "Easy", "faqs": [["How do you tell the cat and mouse apart at a glance?", "Cat gets triangle ears plus drawn whiskers; mouse gets round ears plus a pink nose dot. Different ear shape plus one face detail each, never rely on color alone."], ["Eyeliner or face paint for whiskers?", "Eyeliner pencil for teens and adults (precise), non-toxic face paint for kids (gentler). Either way keep it clear of the actual eyes."]]}, "ketchup-mustard": {"m": ["1 red t-shirt, 1 yellow t-shirt (make: raid the closet)", "Red felt or construction paper, 1 sheet 9x12 inches (buy: craft store, or use paper from home)", "Yellow felt or construction paper, 1 sheet 9x12 inches (buy: craft store, or use paper from home)", "Safety pins, 8 (buy: dollar store, or raid the sewing kit)", "Scissors, 1 pair"], "s": ["Pick who is ketchup (red shirt) and who is mustard (yellow shirt). No wrong answer, but decide before you start cutting, it avoids the only argument this costume can cause.", "Cut a big blob shape from the red paper, about the size of a dinner plate. Round the edges; a neat circle reads as a sticker, a blob reads as a squeeze of ketchup.", "Cut a matching blob from the yellow paper.", "Pin the red blob to the yellow shirt and the yellow blob to the red shirt with 4 safety pins each, pinned from inside. Each person wears the OTHER condiment's color, that is the joke.", "Optional pro finish: write the nutrition facts on the back of each shirt with a marker ('Serving size: 1 awesome couple'). People will turn you around to read it.", "Safety: pin from inside the shirt so no pin backs touch skin, and keep the pins flat, nobody wants a poke during a hug.", "Stand side by side and take the photo. The internet has decided this is a top-10 couples costume; you are now contractually obligated to look delighted."], "time": "15 min", "cost": "$0-5", "effort": "Easy", "faqs": [["How do you keep the paper blobs from tearing?", "Pin from inside the shirt with four pins each, and use felt instead of paper if it might rain. Felt survives weather; paper does not."], ["Why does each person wear the other condiment's color?", "That is the joke, ketchup wears mustard's blob and mustard wears ketchup's. Same-color blobs would just be two people in colored shirts."]]}, "plumber-duo": {"m": ["Blue overalls, 2 (buy: thrift store)", "Red t-shirt and green t-shirt, 1 each (buy: thrift store, or own: from closet)", "Red cap and green cap, 1 each (buy: dollar store)", "Brown non-toxic face paint for mustaches, 1 tube (buy: drugstore)", "White circle stickers or white paper, 2 about 2 inches across (buy: dollar store)", "Marker, 1 (own: household)"], "s": ["Buy the blue overalls, red cap, green cap, white circle stickers, and brown face paint. Pull the red t-shirt and green t-shirt from the closet.", "Write a big 'M' on one white circle and an 'L' on the other with the marker. Stick or tape them to the front of the red cap and green cap.", "Each brother: wear the blue overalls over their colored t-shirt and cap. Paint on a mustache with the brown face paint. The red brother gets a big bushy one, and the green brother gets a thinner one.", "Roll the overall cuffs once and strike the jump pose with a fist in the air. Talk about fixing pipes all night.", "Optional pro finish: roll the overall cuffs once and scuff the knees with a little brown face paint. Work-worn overalls read as plumbers; crisp new ones read as a uniform costume.", "Optional pro finish: roll the overall cuffs once and scuff the knees with a little brown face paint. Work-worn overalls read as plumbers; crisp new ones read as a uniform costume."], "time": "15 min", "cost": "$5-12", "effort": "Easy", "faqs": [["How do you tell the two plumbers apart?", "Red shirt and cap with an 'M' circle for the older brother, green with an 'L' for the younger. The cap letters are the tell, get them on straight and centered."], ["How do you paint a mustache that lasts?", "Brown face paint with a fingertip, two coats, keeping it above the lip line. It fades when eating, so bring the tube for a touch-up halfway through the night."]]}, "office-couple": {"m": ["White button-down shirts, 2 (own: from closet)", "Name tags, 2 (buy: office supply store, or make: index cards with safety pins)", "Toy teapot or a small real teapot, 1 (own: from the kitchen)", "Black pants or skirts, 2 (own: from closet)", "Marker for writing names, 1 (own: household)"], "s": ["Buy name tags, or make them from index cards and safety pins. Pull the white button-down shirts and black pants or skirts from the closet.", "Write joke job titles on the name tags with the marker and pin them on the white button-down shirts.", "One person carries the toy teapot proudly all evening. The other carries a clipboard or a stack of papers.", "Tuck the white button-down shirts in and straighten each other's collars. Introduce yourselves by your fake titles to everyone you meet.", "Optional pro finish: write the fake titles in a dead-serious font, like 'Regional Teapot Manager'. The comedy is in how official the name tag looks.", "Optional pro finish: write the fake titles in a dead-serious font, like 'Regional Teapot Manager'. The comedy is in how official the name tag looks."], "time": "10 min", "cost": "$0-2", "effort": "Easy", "faqs": [["What are good joke job titles?", "Pick titles that match the props: 'Director of Teapot Operations' for the teapot carrier, 'VP of Paperwork' for the clipboard holder. Specific beats random."], ["Is a real teapot okay to carry around?", "A small empty one is fine, but a toy or plastic teapot is better, real ceramic breaks if set down hard, and a full teapot is heavy by hour two."]]}, "burger-joint-couple": {"m": ["2 white aprons (buy: dollar store or online)", "Fake mustache, 1 (buy: toy store)", "Curly red wig, 1 (buy: toy store or online)", "Costume glasses, 1 pair (buy: toy store)", "Order pad and pencil, 1 set (own, or buy: dollar store)"], "s": ["Buy the white aprons, fake mustache, curly red wig, costume glasses, and order pad.", "Test the mustache position in a mirror BEFORE peeling the adhesive, stick it on dry first, mark the spot lightly, then commit. One partner pulls on a white apron and sticks on the fake mustache with its skin-safe adhesive.", "The other partner pulls on the second white apron, the curly red wig, and the costume glasses.", "Carry the order pad and pencil and take each other's burger orders all night.", "Remove the fake mustache gently at the end of the night.", "Optional pro finish: write 'BURGER JOINT' on both aprons with a red fabric marker, plus a fake name tag each ('Ask me about the secret sauce'). Named staff beats blank aprons.", "Optional pro finish: write 'BURGER JOINT' on both aprons with a red fabric marker, plus a fake name tag each ('Ask me about the secret sauce'). Named staff beats blank aprons."], "time": "10 min", "cost": "$8-15", "effort": "Easy", "faqs": [["How do you keep a fake mustache on all night?", "Clean the skin first (no moisturizer), press for 30 seconds, and carry the adhesive for touch-ups. It loosens after eating, re-press in the bathroom."], ["What if the wig is itchy?", "Wear a thin headband or bandana underneath. The barrier layer is the difference between wearing it all night and ripping it off by nine."]]}, "plug-socket": {"m": ["Cardboard box, 1 large (own: cut two flat panels, one per person)", "Gray and white acrylic paint, 1 small bottle each (buy: craft store)", "Black markers, 1 set (own: household)", "Craft foam, 1 sheet 9x12 inches (buy: craft store; cardboard works too)", "Tape, 1 roll, and string, 1 spool, for wearing (own: household tools)", "Scissors, 1 pair (own: household tools)"], "s": ["Mark the panel size against each wearer BEFORE cutting, a panel cut too small looks like a badge and one cut too big bangs knees, and cardboard cut away cannot be put back. Cut two cardboard panels from the large box with the scissors, each about 2 feet square, one per person, cutting generous and trimming later. Buy the gray and white acrylic paint and the craft foam.", "Make the plug: paint one panel gray. Draw two prongs on the craft foam, cut them out, and tape them sticking up from the top edge.", "Make the socket: paint the other panel white. Draw two dark slots and a round outlet face with the black markers.", "Fix the string to the back corners of each panel with tape so they hang like sandwich boards. The plug person stands next to the socket person.", "Optional pro finish: paint a small lightning bolt between the two panels' meeting edges. The bolt sells the 'about to connect' joke in photos.", "Optional pro finish: paint a small lightning bolt between the two panels' meeting edges. The bolt sells the 'about to connect' joke in photos."], "time": "45 min + drying", "cost": "$3-6", "effort": "Easy", "faqs": [["How do the panels stay on?", "Fix string to the back corners of each panel with tape so they hang like sandwich boards, front and back. Two strings per panel, not one, so nothing spins around."], ["Cardboard prongs or foam prongs for the plug?", "Craft foam, it is light, it will not poke anyone, and it tapes on cleanly. Cardboard prongs snap off by the second hour."]]}, "lost-tourist": {"m": ["Button-down shirt, 1 (own, to wrinkle on purpose)", "Sunglasses and camera or phone on a strap, 1 set (own)", "Paper map, 1 (make: print one at home, or draw a fake map on printer paper)", "Luggage tag, 1 (buy: office supply store, or make: index card with string)", "Clear tape, 1 roll (own)"], "s": ["Wrinkle the button-down shirt on purpose. Stuff it in a bag overnight, or ball it up and sit on it for ten minutes.", "Write a fake name and hometown on an index card for the luggage tag. Punch a hole in the card and tie on the string.", "Tape the luggage tag backwards on one shoulder with the clear tape so it faces the wrong way.", "The map is the costume's punchline, fold it wrong-side-out and hold it upside down. A neatly folded map reads as prepared; an upside-down map reads as LOST. Commit to the upside-down.", "Hang the camera or phone around the neck and put the sunglasses on top of the head.", "Walk around looking at the map upside down.", "Optional pro finish: ask strangers for directions to somewhere obvious, in character, all night. The costume is a performance, the map gets you noticed, the bit gets you remembered.", "Optional pro finish: ask strangers for directions to somewhere obvious, in character, all night. The costume is a performance, the map gets you noticed, the bit gets you remembered."], "time": "10 min", "cost": "$0-5", "effort": "Easy", "faqs": [["What is the difference between Hawaiian shirt and lost tourist?", "The map plus the confusion. Hawaiian shirt is a vibe; lost tourist is a character. Add the upside-down map and the asking-directions bit and it becomes a costume."], ["Socks with sandals, really?", "Really. It is the single most recognizable tourist signal on earth. White socks, sandals, confidence."]]}, "tooth-fairy": {"m": ["Tooth: all-white outfit, 1 set (own: from closet)", "Tooth fairy: white dress or white shirt with a white skirt, 1 (own: from closet)", "White cardstock, 1 large sheet (buy: craft store)", "White felt wings, 1 pair, or 1 wire coat hanger with white pantyhose (buy: craft store, or make: from home)", "Small envelope and play money or a coin, 1 (own: from home)", "Glitter glue, 1 tube (buy: craft store)", "Stick and aluminum foil for the wand, 1 (own: from home)", "Tape, 1 roll, and scissors, 1 pair (own: from home)"], "s": ["Buy the white cardstock, glitter glue, and felt wings if you are not making them.", "Pull the white clothes from the closet.", "Draw the tooth outline lightly in pencil first and hold it against the chest to check the size before cutting. Make the tooth: cut a large tooth shape with two roots from the white cardstock. Edge it with the glitter glue and let it dry. Tape it to the chest of the white outfit.", "Safety: tape down any sharp wire ends from the wire coat hanger, and keep fingers clear of the scissors.", "Make the wings: stretch the white pantyhose over a reshaped wire coat hanger to form two wing loops. Tape the hanger ends to a piece of cardboard worn at the back. Tuck the envelope with play money into a pocket or waistband.", "Tooth fairy: wear the white dress and strap on the wings. Carry the wand made from the stick with an aluminum foil star taped on top.", "Optional pro finish: tuck a tiny card into the envelope that says the tooth exchange rate (one tooth equals one wish) for the full fairy bureaucracy joke.", "Optional pro finish: tuck a tiny card into the envelope that says the tooth exchange rate (one tooth equals one wish) for the full fairy bureaucracy joke."], "time": "45 min", "cost": "$5-10", "effort": "Medium", "faqs": [["How do two people split the tooth and the fairy?", "One person wears the all-white outfit with the big tooth on the chest, the other wears the white dress with the wings and carries the wand and envelope. Both read clearly side by side."], ["Is the wire hanger safe for wings?", "Yes if you tape down every sharp wire end and keep the taped ends at the back on the cardboard. For small kids, use felt wings with no wire at all."]]}, "web-hero-duo": {"m": ["Hero: red and blue sweatsuit, or red shirt with blue pants, 1 set (own: from closet)", "Partner: black jacket and black pants, 1 set (own: from closet)", "Black face paint or black eye mask, 1 (buy: costume aisle)", "White face paint or white stickers, 1 (buy: craft store)", "Red web gloves or red socks for hands, 1 pair (own: from closet)", "Tape, 1 roll (own: from home)"], "s": ["Buy the black face paint or black eye mask, and the white stickers.", "Pull the red and blue outfit and the black jacket and black pants from closets.", "Safety: use non-toxic face paint, and keep paint out of the eyes.", "Test the white web pattern on a paper towel first to check the paint flow, since painted lines cannot be undone on fabric. Hero: paint a black eye mask with the black face paint across the eyes. Add white web lines over the red shirt using the white face paint. Or tear thin strips of tape in a web pattern over the shirt. Pull the red socks onto the hands as web gloves.", "Partner: wear the black jacket and black pants and slick the hair back. Strike the brooding pose. No crafting needed beyond the outfit.", "Finishing touch: the hero throws one arm out in a web-shooting pose while the partner crosses their arms behind them.", "Optional pro finish: run the white tape web pattern across the back of the shirt too, so the costume reads from behind in photos.", "Optional pro finish: run the white tape web pattern across the back of the shirt too, so the costume reads from behind in photos."], "time": "25 min", "cost": "$3-8", "effort": "Easy", "faqs": [["Will the white paint ruin the red shirt?", "Yes, face paint stains fabric. If you want the shirt wearable after, use white stickers or thin tape strips in a web pattern instead of paint."], ["What is safer around the eyes, paint or a mask?", "A black eye mask avoids paint near the eyes entirely. If you paint, keep all paint above the cheekbones and below the brow, never on the lids."]]}, "plague-doctor": {"m": ["Long black coat or black robe, 1 (buy: thrift store)", "Wide-brim black hat, 1 (buy: dollar store)", "Black half mask or sunglasses, 1 (buy: dollar store)", "Cardboard or craft foam for the beak, 1 sheet 9x12 inches (buy: craft store; stiff paper works too)", "Black gloves, 1 pair (buy: dollar store)", "Hot glue gun, 1 (buy: craft store)", "Black spray paint or black markers, 1 can or set (buy: craft store)"], "s": ["Cut a paper beak template first and hold it against the mask to check the curve and length, a beak cut too long looks silly and one cut too short looks stubby, and neither can be fixed after cutting. Cut a long curved beak shape from the cardboard or craft foam with the scissors. Buy the coat, hat, mask, gloves, hot glue gun, and beak materials.", "Safety: let an adult handle the hot glue gun, and keep fingers away from the nozzle.", "Paint the beak black with the black spray paint and let it dry. Hot-glue the beak to the front of the black half mask so it juts out.", "Safety: fit the black half mask so the eyes are fully open. Never wear a mask that blocks peripheral vision.", "Cut round eye holes in the black half mask and fit it so the eyes are fully open.", "Wear the long black coat, wide-brim black hat, black gloves, and the beaked mask together. Carry a wooden staff or walking stick for the full effect.", "Optional pro finish: paint the finished beak with a second light coat and let it dry fully. One thin coat looks gray in flash photos; two coats read as true black.", "Optional pro finish: paint the finished beak with a second light coat and let it dry fully. One thin coat looks gray in flash photos; two coats read as true black."], "time": "60 min + drying", "cost": "$8-15", "effort": "Medium", "faqs": [["How do you attach the beak to the mask?", "Hot-glue the beak to the front of the black half mask so it juts forward, with an adult handling the glue gun. Test the fit before gluing, the mask must sit so the eyes are fully open."], ["Is the mask safe to wear while walking around?", "Only if the eyes are fully open with clear peripheral vision. Never wear a mask that blocks side vision near stairs, streets, or crowds, take it off to walk between houses."]]}, "crowd-camouflage": {"m": ["Gray hoodie, 1 (own)", "Dark pants, 1 pair (own)", "Gray beanie, 1 (own, or buy: dollar store)", "Blank adhesive name tag, 1 (buy: dollar store)", "Pen, 1 (own)"], "s": ["Pull on the gray hoodie with the hood up, the dark pants, and the gray beanie.", "Leave the blank adhesive name tag blank, that IS the joke. Write nothing on it with the pen and stick it to the chest of the gray hoodie. The one thing that ruins this costume is filling in the tag.", "Keep a blank expression, hood up, and blend into the background of every group photo.", "Optional pro finish: stand in the back row of every group photo with a perfectly blank expression. The costume only works if you commit to being forgettable, ham it up by being boring.", "Optional pro finish: stand in the back row of every group photo with a perfectly blank expression. The costume only works if you commit to being forgettable, ham it up by being boring."], "time": "5 min", "cost": "$0-2", "effort": "Easy", "faqs": [["What is the joke of this costume?", "You are camouflaged as a random background person, the blank name tag, the gray hoodie, the neutral face. It is funniest in big group photos where nobody notices you until the second look."], ["How do you make it read as a costume, not just gray clothes?", "The blank name tag is the tell. Without it you are just underdressed; with it, people get the bit."]]}, "error-404": {"m": ["1 black t-shirt (make: use your closet)", "1 pair black pants (make: use your closet)", "White fabric paint, 1 small bottle, or 1 sheet white paper (buy: craft store)", "1 old phone case or cracked-screen phone protector prop (make: use an old case)", "Scissors, 1 pair", "Tape, 1 roll (make: use what you own)"], "s": ["Buy the white fabric paint. Dig the black t-shirt, black pants, and old phone case out of the closet.", "Chalk the words 'Page Not Found' on the black t-shirt first and check them in a mirror for centering and spelling. Paint or stencil over the chalk with the white fabric paint. Painted letters cannot be fixed, so the chalk draft is the step.", "Use the white fabric paint or white paper for the letters, and let the paint dry fully.", "Tape the old phone case to one hand.", "Walk around staring at the old phone case, announcing that the page cannot be found.", "Optional pro finish: draw a fake broken-image icon above the text with the white paint. The icon plus the words makes the error message unmistakable.", "Optional pro finish: draw a fake broken-image icon above the text with the white paint. The icon plus the words makes the error message unmistakable."], "time": "15 min + drying", "cost": "$0-5", "effort": "Easy", "faqs": [["How do you keep fabric paint from cracking?", "Paint thin letters and let them dry fully flat before wearing. Thick paint cracks the first time the shirt stretches."], ["Paper or paint for the letters?", "Paint for a shirt you own, paper taped on for a borrowed shirt. Paper peels off after; paint is forever."]]}, "zombie-coworker": {"m": ["Old button-down shirt you can cut up, 1 (own: from closet)", "Old tie, 1 (own: from closet)", "Pale face paint or white face powder, 1 (buy: costume aisle)", "Dark eye makeup or black eyeshadow, 1 (buy: pharmacy)", "Coffee mug, 1 (own: from home)", "Scissors, 1 pair (own: from home)"], "s": ["Buy the pale face paint and dark eye makeup.", "Pull the old button-down shirt, old tie, and coffee mug from home.", "Safety: cut away from your fingers, and keep the scissors away from small kids. Use non-toxic costume makeup.", "Decide where every slit goes and mark the spots with chalk before cutting, since cut fabric cannot be put back. Make the torn shirt: cut jagged slits along the hem of the old button-down shirt and one sleeve. Tie the old tie loosely and crookedly around the neck.", "Make the face: cover the face with the pale face paint. Ring the eyes with the dark eye makeup. Smudge a little down one cheek like a long night at the office.", "Wear the torn shirt with the loosened tie and carry the coffee mug everywhere, mumbling about the quarterly review.", "Optional pro finish: add a lanyard with a blank ID badge worn backwards, the universal sign of someone who gave up at 3pm.", "Optional pro finish: add a lanyard with a blank ID badge worn backwards, the universal sign of someone who gave up at 3pm."], "time": "20 min", "cost": "$3-8", "effort": "Easy", "faqs": [["What if I do not want to ruin a real work shirt?", "Buy a thrift-store button-down for a few dollars and destroy that instead. It looks more authentically worn-out anyway."], ["How do you get the zombie makeup off?", "Wash it off the same night with soap and warm water. Pale face paint stains pillowcases, so wash before bed, not in the morning."]]}, "the-olympians": {"m": ["White bedsheets or large white fabric, 1 per person (own: raid the linen closet)", "Gold rope or gold cord, 2 yards per person (buy: craft store)", "Gold paper or gold craft leaves for laurel crowns, 1 pack (buy: craft store; gold paper works too)", "Gold face paint or gold eyeliner, 1 (buy: drugstore)", "Cardboard for the props, 3 pieces: lightning bolt, trident, owl (own: from boxes)", "Gold markers or gold paint pen, 1 (buy: craft store)", "Safety pins, 6 to 8; scissors, 1 pair; tape, 1 roll (own: household)"], "s": ["Buy the gold rope, gold paper, gold face paint, and gold markers. Pull the white bedsheets from the linen closet.", "Make the togas: wrap one sheet around each person over a plain t-shirt and shorts, pinning at the shoulder with a safety pin. Belt it with the gold rope.", "Safety: pin from the outside of the fabric so pin backs face the clothes, never the skin. Keep the toga above the ankles so nobody trips.", "Size the paper strip around each head and overlap it by an inch before taping, since tape cannot be repositioned cleanly. Make the laurel crowns: cut leaf shapes from the gold paper and tape them along a paper strip sized to each head.", "Make the god props: cut a lightning bolt, a trident, and an owl from the cardboard. Color them gold with the markers.", "Paint one gold detail on each face: a lightning streak, an owl feather, or a wave. Each god picks a power pose for the group photo.", "Optional pro finish: wrap gold cord around each wrist as a cuff and tie gold cord laces up the calves over the shoes for the sandal look.", "Optional pro finish: wrap gold cord around each wrist as a cuff and tie gold cord laces up the calves over the shoes for the sandal look."], "time": "45 min", "cost": "$8-15", "effort": "Medium", "faqs": [["How do you keep the toga from falling off?", "Wear a plain t-shirt and shorts under it, pin the sheet at the shoulder, and belt it with the gold rope at the natural waist. The belt does most of the holding."], ["Is a floor-length sheet a tripping hazard?", "Keep the toga hem above the ankles and pin the extra fabric up. Test walking and stairs before leaving the house."]]}, "safari-photographer": {"m": ["Khaki vest with pockets, 1 (buy: thrift store, or wear a tan button-down from closet)", "Khaki pants or shorts, 1 pair (own: from closet)", "Toy camera, 1 (buy: dollar store, or make: draw a camera on cardboard and tape a strap)", "Toy binoculars, 1 (buy: dollar store; two paper towel rolls taped together work too)", "Stuffed lion or lion cub toy, 1 (buy: thrift store or toy aisle)", "Safari hat, 1 (buy: costume aisle, or wear any wide-brim hat from home)", "Scissors, 1 pair; tape, 1 roll; marker, 1 (own: household)"], "s": ["Buy or gather the toy camera, toy binoculars, stuffed lion or lion cub toy, and safari hat.", "Pull the khaki pants and khaki vest from the closet.", "Safety: cut the cardboard slowly and keep fingers clear of the scissors.", "Sketch the camera shape on the cardboard first and cut one size up, then trim down after a test fitting. To make the camera: cut a camera shape from cardboard and draw a lens with a marker. Tape a ribbon or belt through it as a strap.", "Dress in the khaki pants, khaki vest, and safari hat. Hang the toy camera around your neck and the toy binoculars over the shoulder.", "Finishing touch: tuck the stuffed lion under one arm and practice your best explorer pose.", "Optional pro finish: make a press pass on an index card (name plus STAFF PHOTOGRAPHER) and hang it from a lanyard or string.", "Optional pro finish: make a press pass on an index card (name plus STAFF PHOTOGRAPHER) and hang it from a lanyard or string."], "time": "20 min", "cost": "$5-12", "effort": "Easy", "faqs": [["What is the cheapest way to make the binoculars?", "Tape two empty paper towel rolls together and color them black with a marker. Thread a string through them as a neck strap."], ["Do I need to buy a safari hat?", "Any wide-brim hat from home works. A straw garden hat or a floppy sun hat reads as safari instantly with the khaki outfit."]]}, "player-one-two": {"m": ["Matching t-shirts, 2, any color (buy: thrift store, or own: from closet)", "Iron-on letters or fabric markers, spelling 1 and 2 (buy: craft store)", "Toy game controllers, 2 (buy: toy store, or make: draw one on cardboard)", "Iron, 1 (own: household)"], "s": ["Buy the matching t-shirts, iron-on letters or fabric markers, and toy game controllers.", "Put a big '1' on the front and back of one t-shirt with the iron-on letters. Put a big '2' on the front and back of the other t-shirt.", "Safety: let an adult handle the hot iron on a hard surface.", "Pin or tape the letters to the shirts and check the size and position in a mirror BEFORE heating the iron, ironed letters cannot be repositioned. Iron the letters onto the t-shirts on a hard surface with an adult handling the iron, or draw them with the fabric markers.", "Each player: wear their numbered t-shirt and carry a toy game controller.", "Walk in together, controllers up, and argue good-naturedly all evening about who is really player one.", "Optional pro finish: add a small 'INSERT COIN' label under each number with a fabric marker. It is the detail that gets the laugh from anyone over thirty.", "Optional pro finish: add a small 'INSERT COIN' label under each number with a fabric marker. It is the detail that gets the laugh from anyone over thirty."], "time": "20 min", "cost": "$3-8", "effort": "Easy", "faqs": [["No iron, what is the best alternative?", "Fabric markers, drawn big. Iron-on looks cleaner but marker numbers survive the night fine, and you can skip the whole adult-with-a-hot-iron step."], ["How big should the numbers be?", "Chest-filling: about 8 inches tall on an adult shirt, 5 inches on a kid shirt. Numbers smaller than that disappear in group photos."]]}, "dinosaur-family": {"m": ["1 green sweatsuit per person (buy: discount store, or use one you own)", "1 sheet green felt per person, 9x12 inches (buy: craft store; construction paper works too)", "Scissors, 1 pair", "Fabric glue, 1 tube, or 6 safety pins per person (buy: craft store or dollar store)", "Green face paint, non-toxic, 1 tube (buy: drugstore)"], "s": ["Buy one green sweatsuit and one sheet of green felt per person.", "Safety: adults handle the scissors when cutting the green felt.", "Trace your palm on paper first and use it as the triangle template: spikes about palm-size read best. Cut 8 to 10 triangles from the green felt per person with the scissors.", "Glue or pin the green felt triangles in a row from the hood down the back of the green sweatsuit.", "Paint green spots on each cheek with the green face paint, keeping it clear of the eyes.", "Put the green sweatsuit on over regular clothes, and pin the spikes flat to the hood so they stay put.", "Optional pro finish: cut two small white felt triangles and glue them to the hood cuffs as claws. Claws make the arms part of the costume, not just the back.", "Optional pro finish: cut two small white felt triangles and glue them to the hood cuffs as claws. Claws make the arms part of the costume, not just the back."], "time": "25 min", "cost": "$8-15", "effort": "Easy", "faqs": [["How do you keep the spikes from flopping?", "Pin them flat against the hood so they point back, not up. Spikes pinned upward on soft fleece flop by the second photo."], ["Will the face paint stain?", "Use non-toxic paint marketed for kids, keep it clear of the eyes, and wash it off the same night with soap and water, not just water."]]}, "snow-sisters": {"m": ["Icy-blue dress or blue dress plus silver glitter glue, 1 set (buy glitter glue: craft store)", "Pink or lavender dress, 1 (own)", "White shirt, white pants, 3 large black felt circles (buy felt: craft store)", "Brown clothes, 2 brown pipe cleaners, 1 red pom-pom (buy: craft store)", "Silver headband, 1 (buy: dollar store)", "Tape and scissors, 1 set (own)"], "s": ["Assign roles, then buy the silver glitter glue, black felt circles, brown pipe cleaners, red pom-pom, and silver headband.", "Pull the dresses and the white and brown clothes from closets. The snow princess just wears her dress, no crafting needed.", "Test the glitter pattern on paper first. Glued glitter cannot be repositioned. Spread the silver glitter glue in thin lines along the neckline and sleeves, and let it dry FLAT for one hour. Glue dried on a hanger drips.", "Safety: cut slowly and keep fingers clear of the scissors.", "Snowman: tape the 3 black felt circles down the front of the white shirt as coal buttons. Reindeer: twist the 2 brown pipe cleaners into antler shapes and tape them to the silver headband. Tape the red pom-pom over the nose as a glowing nose.", "Wear each outfit with its accessories. The ice queen adds the silver headband as a tiara.", "Optional pro finish: the ice queen wears the silver headband as a tiara in every photo. The tiara is what separates the ice queen from a girl in a blue dress.", "Optional pro finish: the ice queen wears the silver headband as a tiara in every photo. The tiara is what separates the ice queen from a girl in a blue dress."], "time": "30 minutes + drying", "cost": "$8-12", "effort": "Easy", "faqs": [["How do you keep the glitter glue from cracking?", "Thin lines, dried flat, fully cured. Thick blobs crack when the fabric moves. One thin coat beats two thick ones."], ["What if the felt circles peel off the snowman?", "Tape them from inside the shirt, not outside. Inside tape holds through a whole night of hugs; outside tape peels by hour two."]]}, "sushi-roll": {"m": ["White bedsheet or large white t-shirt to wear, 1 (own: from closet)", "Dark green felt, 1 large sheet (buy: craft store; construction paper works too)", "Pink or orange felt, 1 large sheet (buy: craft store)", "White pom-poms, 4 large, plus 1 green pom-pom (buy: craft store; cotton balls work too)", "Toy chopsticks, 1 pair, or 2 wooden sticks (buy: toy store or craft store; pencils work too)", "Fabric glue, 1 bottle (buy: craft store)", "Scissors, 1 pair"], "s": ["Buy the green and pink felt, the pom-poms, the toy chopsticks, and the fabric glue.", "Dress in the white bedsheet or large white t-shirt.", "Safety: cut the felt slowly and keep fingers clear of the scissors.", "Wrap the felt band around the waist first and mark where it overlaps before cutting, since the band must meet around the body. Make the wrap: cut the dark green felt sheet into a wide band that goes around your waist. Glue or pin it there as the seaweed wrap.", "Make the toppings: cut the pink felt sheet into long strips and glue them across the white shirt as salmon. Glue the white pom-poms near the shoulder as rice balls and the green pom-pom as wasabi.", "Finishing touch: carry the toy chopsticks in one hand like you are about to pick up a bite.", "Optional pro finish: tie a thin red ribbon belt over the seaweed wrap like the band on a real sushi roll, and glue sesame dots (tiny white paper circles) on the salmon strips.", "Optional pro finish: tie a thin red ribbon belt over the seaweed wrap like the band on a real sushi roll, and glue sesame dots (tiny white paper circles) on the salmon strips."], "time": "40 min", "cost": "$8-12", "effort": "Easy", "faqs": [["How do you wear a bedsheet without it falling off?", "Wear a white t-shirt under it and safety-pin the sheet at both shoulders like a toga. Belt it with the seaweed wrap so it cannot unwrap."], ["Will the waistband be comfortable all night?", "Keep the band snug but loose enough to sit down in. Pinning instead of gluing lets you adjust it, and felt has a little give."]]}, "deviled-egg": {"m": ["1 white t-shirt (buy: craft store, or use one you own)", "1 sheet yellow felt, 9x12 inches (buy: craft store; construction paper works too)", "2 sheets red felt, 9x12 inches each (buy: craft store; construction paper works too)", "1 red headband (buy: dollar store)", "2 red pipe cleaners, 12 inches each (buy: craft store; twisted strips of red paper work too)", "Scissors, 1 pair; tape, 1 roll or glue, 1 bottle", "Red face paint or lipstick, 1 (buy: drugstore)"], "s": ["Buy the white t-shirt, yellow felt, red headband, and red pipe cleaners.", "Safety: adults handle the scissors when cutting the felt.", "Draw the egg-yolk oval on paper first and hold it against the white t-shirt to check the size, about dinner-plate size. Cut it from the yellow felt with the scissors. Cut it bigger rather than smaller: a yolk that covers the chest reads instantly.", "Tape or glue the yellow felt oval to the chest of the white t-shirt.", "Twist the two red pipe cleaners into small horns, and tape them to the red headband.", "Cut a long pointed tail from the red felt sheets with the scissors, about 18 inches long. Tape it to the back of the white t-shirt at two points, shoulder blades and lower back, so it stands up. Sit down once to make sure it clears the chair.", "Optional pro finish: cut a jagged white felt ring around the yellow yolk for the egg-white edge. The white rim is what makes it read as a fried egg instead of a yellow circle.", "Optional pro finish: cut a jagged white felt ring around the yellow yolk for the egg-white edge. The white rim is what makes it read as a fried egg instead of a yellow circle."], "time": "20 min", "cost": "$3-8", "effort": "Easy", "faqs": [["How big should the yolk be?", "Dinner-plate size, centered on the chest. Smaller than a dessert plate disappears across a room."], ["How do you keep the tail from flopping?", "Tape it at two points, shoulder blades and lower back. One tape point lets it swing; two keeps it standing."]]}, "pizza-slice": {"m": ["Large cardboard box, 1 (make: cut a big triangle, about 3 feet tall)", "Yellow and orange acrylic paint, 1 bottle each (buy: craft store)", "Red felt, 1 sheet (buy: craft store; red paper works too)", "Brown felt scraps for crust, or 1 brown paper bag (buy: craft store)", "Paintbrush, scissors, tape, 1 set (own)", "Fabric glue, 1 tube (buy: craft store)"], "s": ["Buy the yellow and orange acrylic paint, red felt, and fabric glue. Cut the big triangle from the large cardboard box with the scissors. Round off the wide end for the crust.", "Paint the whole triangle a golden yellow-orange with the paintbrush and let it dry 1 hour.", "Arrange the pepperoni on the triangle DRY first. Pepperoni clusters in the middle if you glue as you go. Cut red felt circles and glue them spread out, then add the brown crust strip along the wide end.", "Tape two string loops to the back so it wears like a sandwich board. Keep the crust at the top and the point at the bottom.", "Optional pro finish: add green felt 'peppers' and white felt 'cheese drips' along the top edge. Toppings are what separate a pizza slice from a yellow triangle.", "Optional pro finish: add green felt 'peppers' and white felt 'cheese drips' along the top edge. Toppings are what separate a pizza slice from a yellow triangle."], "time": "45 minutes + drying", "cost": "$8-12", "effort": "Medium", "faqs": [["How do you make it read as pizza, not just yellow?", "The crust strip along the bottom is the key, a yellow shirt with pepperoni is ambiguous, with a crust it is pizza. Add the crust."], ["Slice or whole pizza for a group?", "One slice each, standing in a circle, makes a whole pizza when you huddle. The group photo where you form the pizza is the whole point."]]}, "popcorn-bucket": {"m": ["Cardboard box, 1 medium (make: tall enough to cover the torso)", "Red and white striped wrapping paper or paint, 1 roll (buy: dollar store or craft store)", "Yellow or white balloons, 8 to 10 (buy: dollar store)", "Tape, string, scissors, 1 set (own)", "Red marker for the label, 1 (own)"], "s": ["Buy the red and white striped wrapping paper and the yellow or white balloons. Wrap the cardboard box in red-and-white stripes and write 'POPCORN' big across the front with the red marker.", "Cut the head and arm holes SMALL first and test the fit. Holes cut too big cannot be shrunk. Tape the inside edges of the holes so the cardboard does not scratch.", "Blow up the yellow or white balloons and tie them in a cluster. Tie the cluster to a string ring that sits on top of the box like overflowing popcorn.", "Step into the box and pull the string straps over the shoulders. Carry the popcorn crown carefully through doorways.", "Optional pro finish: glue a few 'popcorn' pieces to the rim as if overflowing. Overflowing reads as fresh and generous; a flat top reads as empty.", "Optional pro finish: glue a few 'popcorn' pieces to the rim as if overflowing. Overflowing reads as fresh and generous; a flat top reads as empty."], "time": "30 minutes", "cost": "$5-10", "effort": "Easy", "faqs": [["Balloons or tissue paper for the popcorn?", "Tissue paper, crumpled white tissue looks like popcorn and weighs nothing. Balloons pop and squeak all night."], ["How do you wear the bucket?", "Cut the bottom out and wear it like a tunic: head through the top, arms through side holes. The popcorn sits on your shoulders like you are the bucket."]]}, "ice-cream-cone": {"m": ["Tan paper party hat or cone, 1 (buy: dollar store)", "White t-shirt, 1 (buy: craft store, or use one you own)", "Colored dot stickers or pom-poms for sprinkles, 1 pack (buy: craft store; cut paper dots work too)", "Brown paint or marker for the cone crosshatch, 1 (buy: craft store)", "Tape, 1 roll (own)"], "s": ["Buy the tan paper party hat, the white t-shirt, the dot stickers, and the brown marker.", "Draw a waffle-cone crosshatch on the tan paper party hat with the brown marker.", "Set the tan paper party hat on the head like a hat, and tape the elastic so it sits snugly.", "Safety: keep small pom-poms away from kids under three, since they are a choking hazard.", "Cover the white t-shirt with the colored dot stickers or pom-poms, scattered like sprinkles.", "Keep the stickers off the skin.", "Optional pro finish: add a red pom-pom 'cherry' to the tip of the hat with a dot of glue. The cherry is what makes strangers say the flavor out loud.", "Optional pro finish: add a red pom-pom 'cherry' to the tip of the hat with a dot of glue. The cherry is what makes strangers say the flavor out loud."], "time": "20 min", "cost": "$2-6", "effort": "Easy", "faqs": [["How do you keep the cone hat on all night?", "Tape the hat's elastic strap so it fits snug under the chin, and add a second piece of tape inside the hat brim. Paper hats are light; they fall off because the elastic is loose, not because of wind."], ["Pom-poms or stickers for the sprinkles?", "Stickers for under-5s (no choking risk, nothing falls off). Pom-poms photograph better but shed all night and are a choking hazard for toddlers."]]}, "pbj": {"m": ["Brown t-shirt, 1 (buy: thrift store, or own: from closet)", "Purple t-shirt, 1 (buy: thrift store, or own: from closet)", "White poster board, 2 sheets (buy: dollar store)", "Markers, 1 set (own: household)", "Scissors, 1 pair, and tape or string, 1 roll or spool (own: household tools)"], "s": ["Draw the bread shape on the poster board first and hold it against the t-shirt to check the size, bread cut too small looks like a badge, and poster board cut away cannot be put back. Cut two big sandwich-bread shapes from the white poster board with the scissors, cutting generous and trimming after the fitting. Buy the brown t-shirt, purple t-shirt, and white poster board if needed.", "Write 'PB' in big letters on one bread shape and 'J' on the other with the markers.", "Tape or string one bread sign to the front of the brown t-shirt. Tape or string the other to the front of the purple t-shirt.", "Stand pressed together all evening, bread sides out. The brown-shirt person is the peanut butter and the purple-shirt person is the jelly.", "Optional pro finish: draw a wavy crust edge around each bread shape with a tan marker. The crust line is what makes it read as bread instead of a white sign.", "Optional pro finish: draw a wavy crust edge around each bread shape with a tan marker. The crust line is what makes it read as bread instead of a white sign."], "time": "20 min", "cost": "$3-8", "effort": "Easy", "faqs": [["Which side is peanut butter and which is jelly?", "Brown shirt is peanut butter, purple shirt is jelly. Label the bread signs 'PB' and 'J' big enough to read from ten feet away so nobody has to ask."], ["How do you wear the bread signs?", "Tape or string one bread sign to the front of each t-shirt like a sandwich board front panel. Two attachment points at the top corners keep it from spinning."]]}, "bacon-eggs": {"m": ["Dark red or brown shirt for the bacon, 1 (own)", "White shirt for the egg, 1 (own)", "1 sheet red-brown craft felt, 9x12 inches (buy: craft store, construction paper works too)", "1 sheet each white and yellow craft felt, 9x12 inches (buy: craft store, construction paper works too)", "Safety pins, 6 to 8 (buy: dollar store)", "Scissors, 1 pair"], "s": ["Buy the craft felt and the safety pins.", "Lay out the felt on the shirts and pin the arrangement BEFORE cutting or pinning for real. Cut 4 wavy vertical strips from the red-brown craft felt with the scissors. Cut one large white oval (dinner-plate size) and one yellow circle (saucer size) from the other felt sheets.", "Pin the wavy strips down the front of the dark red or brown shirt with a safety pin.", "Pin the white oval to the white shirt, then pin the yellow circle on top of it for the yolk.", "Put on the shirts. Have the bacon stand just behind the egg for photos, yolk side out.", "Optional pro finish: cut the bacon strips with pinking shears or a wavy line instead of straight, the sizzle edge is what makes people say 'oh! bacon' instead of 'red strips'.", "Optional pro finish: cut the bacon strips with pinking shears or a wavy line instead of straight, the sizzle edge is what makes people say 'oh! bacon' instead of 'red strips'."], "time": "20 min", "cost": "$3-6", "effort": "Easy", "faqs": [["How do you make the fried egg read clearly?", "Scale is everything: the white oval should cover most of the shirt chest, with the yellow yolk circle about a third of its size, pinned on top center."], ["Will safety pins hold felt all night?", "Yes if you pin from inside the shirt so the pin backs face the fabric. Use two pins per strip for the bacon so nothing rotates."]]}, "peas-pod": {"m": ["Green t-shirts, 1 per person for 3 to 5 people (buy: thrift store, or own: from closet)", "Green felt, 1 yard (buy: craft store; green fabric works too)", "Green fabric paint, 1 bottle (buy: craft store)", "Hot glue gun or fabric glue, 1 (buy: craft store)", "Green non-toxic face paint, 1 tube (buy: drugstore)", "Scissors, 1 pair (own: household tools)"], "s": ["Lay the group out and chalk the pod outline on the felt against their actual lineup BEFORE cutting, a pod cut too short strands a pea outside, and felt cut away cannot be put back. Cut the green felt into one long pod shape with the scissors, about 6 feet long, with a pointed top, cutting long and trimming later. Buy the green felt, green fabric paint, and hot glue gun.", "Paint darker green stripes and a center seam line down the pod with the green fabric paint. Let the paint dry for 1 hour.", "Safety: let an adult handle the hot glue gun, and keep fingers away from the nozzle.", "Glue the pod to the front of the green t-shirts so it stretches across all of them. Space the wearers evenly.", "Paint a small green circle on each person's cheek with the green face paint. Line everyone up in height order under the pod and walk together in a row.", "Optional pro finish: paint each person's name on the pod next to their spot. Named peas turn a group costume into a keepsake photo.", "Optional pro finish: paint each person's name on the pod next to their spot. Named peas turn a group costume into a keepsake photo."], "time": "60 min + drying", "cost": "$8-15", "effort": "Medium", "faqs": [["How many people make a good pea pod?", "Three to five. Two looks thin, six stretches the felt so far the pod sags. Three peas in a pod is the classic for a reason."], ["How do the peas stay lined up while walking?", "Space the wearers evenly and walk in a row at the same pace, practice once before going out. The pod is one piece, so if one person rushes, the whole pod bunches."]]}, "basketball-star": {"m": ["Basketball jersey or numbered tank top, 1 (own, or buy: sporting goods store)", "Basketball shorts, 1 pair (own)", "Black non-toxic face paint or 1 eyeliner pencil (buy: toy store)", "Basketball, 1 (own, or buy: toy store)"], "s": ["Pull on the basketball jersey and the basketball shorts.", "Safety: use only the black non-toxic face paint. Skip the eye black for very young kids who will rub their eyes.", "Draw two short black stripes under each eye with the black non-toxic face paint. Keep the stripes short and below the eye, never on the eyelid, and skip them for kids who rub their eyes.", "Carry the basketball everywhere, tucked under one arm.", "Dribble it whenever you stand still.", "Optional pro finish: add a wristband and tall socks. Athletes are uniforms plus accessories; the wristband is the cheapest one.", "Optional pro finish: add a wristband and tall socks. Athletes are uniforms plus accessories; the wristband is the cheapest one."], "time": "5 min", "cost": "$0-3", "effort": "Easy", "faqs": [["Do I need a real jersey?", "No. Any numbered tank top works, write a big number on a plain shirt with a fabric marker and it reads the same from ten feet away."], ["Is eye black safe for kids?", "Use only non-toxic face paint marketed for kids, keep it below the eye, and skip it for very young kids who rub their eyes."]]}, "referee": {"m": ["Plain black t-shirt or long-sleeve shirt, 1 (own: from closet)", "Black pants or shorts, 1 pair (own: from closet)", "White athletic tape, 1 roll (buy: sporting goods or pharmacy)", "Plastic whistle, 1 (buy: dollar store or sporting goods)", "Yellow fabric square, 6x6 inches (own: cut from an old cloth or napkin)"], "s": ["Buy the whistle, white athletic tape, and check you have a black shirt and pants ready.", "Tear horizontal strips of the white athletic tape across the front and back of the black shirt. Space them about 2 inches apart and press firmly so they stay.", "Fold the yellow fabric square in half and tie it in a knot around the whistle lanyard. Or tape it to the whistle so it waves when you blow the whistle.", "Wear the black outfit with the striped shirt and put the whistle around your neck. Tuck the yellow flag in a pocket.", "Optional pro finish: add a black wristband on one wrist and carry the yellow flag tucked in a back pocket, hidden until the call.", "Optional pro finish: add a black wristband on one wrist and carry the yellow flag tucked in a back pocket, hidden until the call."], "time": "20 min", "cost": "$2-5", "effort": "Easy", "faqs": [["Will the athletic tape stay on the shirt all night?", "Press each strip firmly onto a clean, dry shirt and the tape holds for the evening. It peels off after, though it can pull lint on fuzzy fabrics, so test a hidden spot first."], ["What can I use instead of a real whistle?", "A toy whistle from a party favor pack works, or just mime blowing it. Skip loud metal whistles around small kids."]]}, "boxer": {"m": ["Bathrobe, 1 (own)", "Toy boxing gloves, 1 pair (buy: toy store)", "Purple and yellow non-toxic face paint, 1 tube each (buy: toy store)", "Athletic shorts and sneakers, 1 set (own)", "Phone for entrance music, 1 (own)"], "s": ["Buy the toy boxing gloves and the purple and yellow non-toxic face paint.", "Pull on the athletic shorts, sneakers, and bathrobe with the hood up.", "Safety: keep the face paint clear of the eyes.", "Dab the purple and yellow face paint on one cheekbone and around one eye for bruise makeup. Less is more, one bruise reads as boxer, five bruises reads as accident. Keep all paint clear of the eyes.", "Pull on the toy boxing gloves.", "Throw a few shadow punches and play entrance music from the phone as you walk in.", "Optional pro finish: write your fighter name across the back of the robe with white duct tape letters. Walk-ins get twice the reaction when the robe has a name.", "Optional pro finish: write your fighter name across the back of the robe with white duct tape letters. Walk-ins get twice the reaction when the robe has a name."], "time": "10 min", "cost": "$5-12", "effort": "Easy", "faqs": [["How do you do bruise makeup that looks real?", "Layer purple first, then dab yellow at the edges. Real bruises are darkest in the center and yellow at the healing edge. Blend with a fingertip, not a brush."], ["Toy gloves or real gloves?", "Toy gloves only. Real boxing gloves are heavy, sweaty, and you cannot hold a drink. Toy gloves photograph identically."]]}, "cheerleader": {"m": ["Team-color t-shirt and skirt or shorts, 1 set (own)", "4 to 6 white plastic grocery bags (make: save from home)", "Hair ribbon in a team color, 1 (buy: dollar store)", "Rubber bands or tape, 1 pack (own)", "Scissors, 1 pair"], "s": ["Safety: cut the bags up right away. Keep whole bags away from very small children.", "Stack 2 to 3 white plastic grocery bags. Cut them into long strips with the scissors, stopping 3 inches from one end, do NOT cut all the way through or the pom-pom falls apart. The uncut end becomes the handle.", "Roll the uncut end tightly and wrap it with a rubber band or tape to make a handle. Fluff the strips.", "Make a second pom-pom the same way.", "Pull on the team-color t-shirt and skirt or shorts. Tie the hair ribbon in a bow and carry a pom-pom in each hand.", "Optional pro finish: roll a sheet of paper into a cone megaphone and tape it. Shouting through a megaphone is the difference between wearing the costume and performing it.", "Optional pro finish: roll a sheet of paper into a cone megaphone and tape it. Shouting through a megaphone is the difference between wearing the costume and performing it."], "time": "15 min", "cost": "$0-3", "effort": "Easy", "faqs": [["How fluffy should the pom-poms be?", "Fluff each strip individually after rolling the handle, the fluffing is 80% of the look. Flat strips read as trash bag; fluffed strips read as pom-pom."], ["Are plastic bag pom-poms safe for toddlers?", "Cut the bags up right away and keep whole bags away from very small children. For under-3s, use tissue paper pom-poms instead."]]}, "tennis-duo": {"m": ["White t-shirts and white shorts or skirts, 1 set each (own: from closet)", "White sweatbands, 2, or strips of white fabric (buy: sports store)", "Toy tennis rackets, 2 (buy: toy store; cardboard rackets work too)", "Tennis balls, 1 tube of 3 (buy: sports store)", "White socks and sneakers, 1 pair each (own: from closet)", "Scissors, 1 pair"], "s": ["Buy the toy tennis rackets, tube of tennis balls, and sweatbands.", "Pull the white outfits and sneakers from the closet.", "Dress head to toe in white and tie the sweatband across the forehead.", "Safety: cut the fabric slowly and keep fingers clear of the scissors.", "Measure the strip around the head with a finger's width of slack before cutting, then cut the 2-inch strip of white fabric. To make a sweatband: tie it around the head with a knot at the back, snug enough to stay but loose enough to be comfortable.", "Finishing touch: carry the toy tennis rackets and tuck the tube of balls under one arm for the courtside pose.", "Optional pro finish: add a white wristband on the racket arm and tuck one spare ball into the waistband for the between-points look.", "Optional pro finish: add a white wristband on the racket arm and tuck one spare ball into the waistband for the between-points look."], "time": "20 min", "cost": "$5-12", "effort": "Easy", "faqs": [["How do you make a cardboard tennis racket?", "Cut an oval with a handle from cardboard, cut out the middle, and weave string or yarn across the opening for the strings. Tape the handle for a grip."], ["How do you keep the fabric sweatband from slipping?", "Tie it with a knot at the back rather than relying on stretch. A knot you can retie stays put through the whole night."]]}, "bowling-pins": {"m": ["White shirt and pants per pin person, 1 set each (own)", "Red duct or electrical tape, 1 roll (buy: dollar store)", "Black shirt and pants for the bowler, 1 set (own)", "Toy bowling ball or black playground ball, 1 (buy: toy store)", "Scissors, 1 pair"], "s": ["Buy the red duct or electrical tape and the toy bowling ball.", "Measure first: the classic pin has two stripes around the neck area. Each pin person cuts two 12-inch red tape stripes from the roll with the scissors, cut all stripes before sticking any, so they match.", "Wrap two red tape stripes around the collar of the white shirt and one around each wrist.", "The bowler pulls on the black shirt and pants.", "Safety: use a lightweight toy ball, never a real bowling ball.", "Carry the toy bowling ball. Line the pins up in formation with the bowler at the end for photos.", "Optional pro finish: number the pins 1 through 10 with a black marker on the back. When the bowler 'knocks you down' you fall in number order, it gets the biggest laugh of the night.", "Optional pro finish: number the pins 1 through 10 with a black marker on the back. When the bowler 'knocks you down' you fall in number order, it gets the biggest laugh of the night."], "time": "15 min", "cost": "$2-5", "effort": "Easy", "faqs": [["Where exactly do the red stripes go?", "Two stripes around the collar of the white shirt and one around each wrist. That is the whole pin read, collar plus wrists."], ["Can the bowler use a real bowling ball?", "No, use a lightweight toy ball or playground ball painted black. A real ball is a weapon in a crowd and most venues ban them."]]}, "cardboard-knight": {"m": ["Large cardboard boxes, 2 to 3 (make: collect spares)", "Silver acrylic paint, 1 bottle (buy: craft store, tempera paint works too)", "Foam brush or paintbrush, 1 wide (own, or buy: craft store)", "1 pool noodle (buy: toy store or dollar store)", "Gray duct tape, 1 roll (buy: dollar store)", "Black marker, 1 (buy: dollar store)", "Scissors, 1 pair"], "s": ["Safety: an adult should handle the heavy cutting. Cut generous eye holes in the helmet so vision stays clear.", "Draw every piece on the cardboard with marker BEFORE cutting: chest plate, back plate, two shoulder pieces, helmet. Cut the helmet eye holes generously, cardboard cut away cannot be added back, and a knight who cannot see is a hazard. Cut all pieces with the scissors.", "Paint every armor piece silver with the silver acrylic paint and the foam brush. Let the paint dry fully.", "Add rivet dots and edge lines with the black marker.", "Tape the plates together with the gray duct tape so they hinge at the shoulders. Wrap the pool noodle in gray duct tape for the sword.", "Put the armor on over dark clothes once the paint is dry. Carry the noodle sword.", "Optional pro finish: tape a red crepe-paper plume to the helmet top. Knights are silver; knights with plumes are memorable.", "Optional pro finish: tape a red crepe-paper plume to the helmet top. Knights are silver; knights with plumes are memorable."], "time": "60 min + drying", "cost": "$5-10", "effort": "Medium", "faqs": [["How do you keep cardboard armor from falling apart?", "Gray duct tape hinges at the shoulders and sides, tape both sides of each joint. The tape is the armor's skeleton; the cardboard is just the skin."], ["What is the safest sword option?", "A pool noodle wrapped in gray duct tape. It looks metallic in photos and cannot hurt anyone. Never use wood or real metal, even blunted."]]}, "ninja": {"m": ["All-black outfit: t-shirt, pants, and a black beanie, 1 set (own: from closet)", "Black belt or sash, 1 (own: an old tie or scarf)", "Black headband or strip of black t-shirt, 1 strip about 3 inches wide (own: cut from an old shirt)", "Scissors, 1 pair, and tape, 1 roll (own: household tools)", "Black non-toxic face paint for a mask stripe, 1 tube (buy: drugstore, optional)"], "s": ["Measure the strip around the forehead first and mark 3 inches wide BEFORE cutting, a strip cut too narrow digs in, and fabric cut away cannot be put back. Cut the strip a little long from the old black t-shirt with the scissors; long can be trimmed, short cannot. Put on the black beanie.", "Tie the black sash around the waist with the knot at the back, and tuck the ends in.", "Safety: keep the eyes and mouth uncovered, and wrap the black headband above the eyes.", "Wrap the black headband around the forehead and tie it at the back, leaving the eyes clear.", "Paint a thin black stripe across the bridge of the nose with the black face paint. Practice the silent sneaky walk.", "Optional pro finish: tuck the headband ends in instead of letting them dangle. Clean lines read as trained ninja; loose ends read as pirate.", "Optional pro finish: tuck the headband ends in instead of letting them dangle. Clean lines read as trained ninja; loose ends read as pirate."], "time": "10 min", "cost": "$0-2", "effort": "Easy", "faqs": [["How do you wrap the headband so it is safe?", "Wrap it above the eyes on the forehead and tie it at the back with a quick-release knot. Eyes and mouth stay completely uncovered, vision first, costume second."], ["Do I need the face paint stripe?", "No. The all-black outfit plus the forehead wrap already reads as ninja. The stripe is a nice touch for photos but skip it for kids who rub their faces."]]}, "caped-duo": {"m": ["2 old twin sheets or large fabric rectangles, about 4x5 feet each (make: cut from old sheets)", "Craft felt for masks and emblems, 2 sheets 9x12 inches (buy: craft store, construction paper works too)", "Ribbon or cord for cape ties, about 3 feet per cape (own, or buy: craft store)", "Fabric glue, 1 tube (buy: craft store)", "Paper and pencil for sketching, 1 set (own)", "Scissors, 1 pair"], "s": ["Sketch a matching emblem for each of you on the paper.", "Cut the emblems from the craft felt with the scissors.", "Sketch and cut the emblems from paper first and hold them against the cape to check the size, emblems should cover a third of the cape width. Cut each sheet into a cape with the scissors, hem-side down. Glue a craft felt emblem to the back of each cape with the fabric glue.", "Cut two eye masks from the craft felt, cutting the eye holes wide. Glue ribbon ties to the ends with the fabric glue and let the glue dry.", "Safety: tie the cord in a loose bow that pulls free easily. Never tie anything tight around the neck. Keep the mask eye holes wide so vision stays clear.", "Tie the capes at the neck with the cord in a loose bow and put on the masks.", "Optional pro finish: cut the emblem in two felt colors, a base shape plus a smaller top shape. Layered emblems look designed; single-color looks cut-out.", "Optional pro finish: cut the emblem in two felt colors, a base shape plus a smaller top shape. Layered emblems look designed; single-color looks cut-out."], "time": "30 min + drying", "cost": "$5-10", "effort": "Easy", "faqs": [["How do you make two capes look like a matching duo?", "Same cape length, same emblem shape, inverted colors (your emblem is red-on-black, theirs is black-on-red). Matching shape plus inverted color reads as team instantly."], ["Fabric glue or safety pins for the emblem?", "Glue for the emblem (flat, permanent for the night), pins for anything you might reposition. Glue the emblem the night before so it cures."]]}, "hero-squad": {"m": ["Cape per person in squad colors, 1 each (buy: craft store, or make: cut from 1 yard of fabric each)", "Mask per person matching the cape color, 1 each (buy: craft store)", "T-shirt per person in the cape color, 1 each (buy: craft store)", "Fabric paint for the team emblem, 1 bottle (buy: craft store)", "Safety pins, 2 per person (own)"], "s": ["Buy the capes, masks, t-shirts, and fabric paint in the squad color.", "Sketch the team emblem on scrap paper and have the whole squad approve it BEFORE opening the paint, painted emblems cannot be unpainted. Then each hero paints the same emblem, like a lightning bolt, on the t-shirt with the fabric paint.", "Let the fabric paint dry fully before wearing.", "Safety: keep each cape short enough to clear the ground so nobody trips.", "Pin each cape at the shoulders with a safety pin, and wear the matching mask.", "End every appearance with the team pose: fists on hips, capes billowing.", "Optional pro finish: paint a matching emblem on each cape near the shoulder. Capes with emblems look designed; plain capes look borrowed.", "Optional pro finish: paint a matching emblem on each cape near the shoulder. Capes with emblems look designed; plain capes look borrowed."], "time": "40 min + drying", "cost": "$4-8 per person", "effort": "Easy", "faqs": [["How long does the fabric paint take to dry?", "About 1 to 2 hours to stop being tacky, overnight to be safe. Paint the shirts the night before the event or the emblem smears when worn."], ["How do you keep capes safe for small kids?", "Keep each cape short enough to clear the ground, and pin them with safety pins instead of tying, pinned capes pull free if snagged. Never tie a cape tight around a small child's neck."]]}, "astronaut": {"m": ["White sweatshirt and sweatpants, 1 set (buy: clothing store, or use your own)", "1 large brown paper grocery bag (buy: grocery store or craft store)", "Silver duct tape, 1 roll (buy: dollar store)", "Flag sticker or iron-on patch, 1 (buy: craft store)", "Scissors, 1 pair"], "s": ["Buy the white sweatshirt and sweatpants, paper bag, silver duct tape, and flag sticker.", "Cut the face opening SMALLER than you think with the scissors, you can always widen it, but a too-big hole flops and ruins the bag. Hold the bag up to the face and trace the opening first.", "Wrap two silver duct tape stripes around each sleeve and pant leg. Press the flag sticker onto the chest of the sweatshirt.", "Safety: cut the face opening wide enough that vision and hearing stay clear.", "Pull on the white sweatshirt and sweatpants.", "Slip the bag over your head so the face opening lines up. Crimp the top with a strip of duct tape so it holds its shape.", "Optional pro finish: print a mission patch from home (a circle with your name and 'EST. 2026') and tape it to the opposite chest from the flag. Real astronauts wear two patches.", "Optional pro finish: print a mission patch from home (a circle with your name and 'EST. 2026') and tape it to the opposite chest from the flag. Real astronauts wear two patches."], "time": "25 min", "cost": "$3-10", "effort": "Easy", "faqs": [["What size paper bag fits a kid astronaut helmet?", "A standard large brown grocery bag fits kids and most adults. For a toddler, use a small paper gift bag and cut the face opening to match their face."], ["How do you keep the paper bag helmet from slipping?", "Crimp the top of the bag with a strip of duct tape so it holds its shape, and cut the face opening wide enough that it sits on the shoulders, not the head."]]}, "robot-ranger": {"m": ["Medium cardboard box for the torso, 1 (own: from home)", "Aluminum foil, 1 roll (buy: grocery store)", "Flexible aluminum dryer vent hose, 1 section about 3 feet (buy: hardware store)", "Sticker dots or round stickers, 1 sheet (buy: craft store; punched paper circles work too)", "Duct tape, 1 roll (buy: hardware store)", "Blue or gray sweatsuit to wear underneath, 1 set (own: from closet)", "Black marker, 1 (own: from home)", "Scissors, 1 pair"], "s": ["Buy the aluminum foil, dryer vent hose, sticker dots, and duct tape.", "Safety: cut the cardboard box slowly and keep fingers clear of the scissors. The dryer vent hose has sharp wire edges, so cut carefully and tape the ends right away.", "Before cutting, wear the box over your head and trace circles for the head and arm holes a little bigger than you need. Cut the holes SMALLER than traced first, since you can widen them but cannot shrink them. Then wrap the box in aluminum foil like a gift, taping the foil flat.", "Draw two round gauges on the foil chest with the black marker. Stick the sticker dots on as dial needles and button lights.", "Hold the hose pieces against your arms to measure the length before cutting, and cut longer than you need since cut hose cannot be repaired. The dryer vent hose has sharp wire edges, so tape the ends right away so the wire ribs stay put. Tape the top of each piece to the shoulder holes of the box so arms slide inside.", "Dress in the blue or gray sweatsuit and slide the foil-wrapped cardboard box over the head and arms. Press the sticker dials on last so they sit on the chest.", "Optional pro finish: add a big red sticker dot as an emergency button on the chest, and draw a small speaker grille under it with the black marker.", "Optional pro finish: add a big red sticker dot as an emergency button on the chest, and draw a small speaker grille under it with the black marker."], "time": "1 hour", "cost": "$8-15", "effort": "Medium", "faqs": [["How do you handle the sharp edges on the vent hose?", "Cut carefully and tape both ends immediately so the wire ribs stay put. Wear the sweatsuit underneath so no foil or wire touches bare skin."], ["Can the kid see and breathe inside the box?", "Cut the head hole generous and keep the box loose on the shoulders. Never tape the box to the head, and take it off indoors in crowds."]]}, "penguin-huddle": {"m": ["Black long-sleeve shirts, 1 per person (buy: thrift store, or own: from closet)", "White felt, 1 sheet 9x12 inches per person (buy: craft store; white paper works too)", "Orange felt, 1 sheet 9x12 inches per person (buy: craft store; orange paper works too)", "Headbands, 1 per person (buy: dollar store)", "Fabric glue, 1 tube (buy: craft store)", "Scissors, 1 pair (own: household tools)"], "s": ["Cut one paper belly template first and check it against a shirt, a belly cut too small looks like a bib, and felt cut away cannot be put back. Then cut an oval white belly from the white felt with the scissors for each person. Buy the white felt, orange felt, headbands, and fabric glue.", "Cut a small orange triangle beak from the orange felt for each headband. Glue one beak to the front of each headband with the fabric glue.", "Glue the white bellies to the front of the black long-sleeve shirts. Let the fabric glue dry for 30 minutes.", "Each person: put on the black long-sleeve shirt and the headband with the beak. Tuck hands into the sleeves as flippers and waddle shoulder to shoulder in the huddle.", "Optional pro finish: cut two small orange felt feet shapes and tape them over the toes of dark shoes. Feet are the detail people notice in full-body photos.", "Optional pro finish: cut two small orange felt feet shapes and tape them over the toes of dark shoes. Feet are the detail people notice in full-body photos."], "time": "35 min + drying", "cost": "$4-10", "effort": "Easy", "faqs": [["How big should the white belly be?", "An oval that covers the chest from collarbone to waistband. Too small reads as a badge; chest-size reads as a penguin belly instantly."], ["How do you keep the beak on the headband?", "Glue one orange triangle beak to the front of each headband with fabric glue and let it dry flat for 30 minutes. Glue beats tape here, tape peels off headbands by the second hour."]]}, "prince-princess": {"m": ["Gold paper crown or plastic crown, 1 (buy: dollar store, or make: cut one from gold poster board)", "Cape or long piece of fabric, 1 about 3 feet long (buy: thrift store)", "Thrifted gown or long dress, 1 (buy: thrift store)", "Tiara, 1 (buy: dollar store)", "Toy scepter or wand, 1 (buy: dollar store)"], "s": ["Buy the gold paper crown, tiara, and toy scepter. Pick up the thrifted gown and cape at the thrift store.", "The prince: wear the gold paper crown and cape over dark clothes, and carry the toy scepter.", "The princess: wear the thrifted gown and tiara, and add the spare wand if there is one.", "Walk in with royal posture, wave slowly with a bent wrist, and address everyone as 'my good subject'.", "Optional pro finish: give the prince a sash of torn fabric across the chest. A sash plus a crown reads as royalty; a crown alone reads as a party hat.", "Optional pro finish: give the prince a sash of torn fabric across the chest. A sash plus a crown reads as royalty; a crown alone reads as a party hat."], "time": "10 min", "cost": "$5-10", "effort": "Easy", "faqs": [["How do you keep a paper crown on all night?", "Size it snug and tape the join on the inside, then add two bobby pins through the crown into the hair. Paper crowns fail at the join, so reinforce the join before anything else."], ["What should the prince wear under the cape?", "Dark clothes, black pants and a dark shirt. The cape and crown are the costume; light or busy clothes underneath fight them."]]}, "dino-herd": {"m": ["1 green poncho or green bedsheet per person, about 50x60 inches (buy: craft store or online)", "1 sheet green felt per person, 9x12 inches (buy: craft store; construction paper works too)", "1 old sock per person, white or colored (make: use one you own)", "Scrap fabric or cotton balls for stuffing, about 1 cup per person (make: use what you own)", "Fabric glue, 1 tube, or 6 safety pins per person (buy: craft store or dollar store)", "Scissors, 1 pair"], "s": ["Buy one green poncho and one green felt sheet per person, and raid the sock drawer for an old sock.", "Safety: adults handle the scissors when cutting the green felt.", "Cut one paper triangle first and hold it against the green poncho to check the size: palm-size works best. Cut 8 to 10 triangles from the green felt sheet per person with the scissors, all from the paper template so the row looks even.", "Pin the green felt triangles in a row down the back of the green poncho.", "Stuff the old sock with the scrap fabric, and pin the opening to the back waistband of the green poncho.", "Wear the green poncho over a t-shirt and jeans. Pin the spikes and tail flat so they do not poke anyone in a crowd.", "Optional pro finish: pin a row of small felt spikes along the sock tail too, so the tail matches the back and stops reading as a sock.", "Optional pro finish: pin a row of small felt spikes along the sock tail too, so the tail matches the back and stops reading as a sock."], "time": "30 min", "cost": "$5-12", "effort": "Easy", "faqs": [["How do you keep the spikes upright in a crowd?", "Pin each spike at two points, base and middle, flat against the poncho so they do not poke anyone. Flat-pinned spikes survive hugs."], ["What size poncho for small kids?", "Cut a twin bedsheet in half for kids under 8. A full poncho drags on small kids and trips them."]]}, "pixel-ghost": {"m": ["White bedsheet or white fabric, 1 twin-size (buy: thrift store)", "Black felt, 1 sheet 9x12 inches (buy: craft store; black paper works too)", "Fabric glue, 1 tube (buy: craft store)", "Scissors, 1 pair (own: household tools)", "Marker and ruler, 1 each (own: household)"], "s": ["Fold the sheet in half and chalk the zigzag line first, holding it against the wearer to check the length, a hem cut too short cannot be fixed, and this is the bottom edge of the whole costume. Cut the bottom edge into chunky square zigzags with the scissors, about 4 inches per square, cutting long and trimming later. Buy the white bedsheet and the black felt.", "Draw two square eyes and a square mouth on the black felt with the marker and ruler. Cut them out.", "Glue the felt eyes and mouth onto the top third of the white bedsheet. Let the fabric glue dry for 30 minutes.", "Safety: keep the eye area open so vision stays clear.", "Wear dark clothes underneath and drape the white bedsheet over the head with the eyes lined up. Cut two small arm slits if reaching through is hard.", "Optional pro finish: cut two small arm slits at the sides. Reaching through slits instead of lifting the whole sheet keeps the ghost shape intact all night.", "Optional pro finish: cut two small arm slits at the sides. Reaching through slits instead of lifting the whole sheet keeps the ghost shape intact all night."], "time": "30 min + drying", "cost": "$2-5", "effort": "Easy", "faqs": [["How do you keep the pixel edges crisp?", "Use the ruler and marker to draw the zigzag grid before cutting, and cut on the lines. Freehand zigzags wobble; measured squares read as pixels."], ["How does the wearer see?", "Wear dark clothes underneath, drape the sheet over the head, and leave the face area open under the felt eyes, the eyes are decoration on the sheet, not eye holes. Vision stays fully clear."]]}, "spaghetti-meatball": {"m": ["White t-shirt or sweatshirt, 1 (own: from closet)", "Yellow or cream yarn, 1 skein (buy: craft store)", "Brown pom-poms, 2 inch, 3 to 4 (buy: craft store)", "Fabric glue or hot glue gun, 1 (buy: craft store)", "Scissors, 1 pair"], "s": ["Lay the white shirt flat.", "Lay out the yarn strands on the shirt first WITHOUT glue to check the wavy rows cover the shirt the way you want. Then cut the yarn into 12-inch strands and glue them across the shirt in wavy rows to look like spaghetti, since glued strands cannot be repositioned.", "Glue 3-4 brown pom-poms on top as meatballs.", "Let dry completely before wearing.", "Optional pro finish: glue a few small white pom-poms among the yarn as grated parmesan, and add a red felt meatball-sauce splatter on one sleeve.", "Optional pro finish: glue a few small white pom-poms among the yarn as grated parmesan, and add a red felt meatball-sauce splatter on one sleeve."], "time": "40 min", "cost": "$5-10", "effort": "Easy", "faqs": [["Can you wash the shirt after?", "No. The glued yarn does not survive the washing machine. Treat it as a single-use costume shirt, so use a thrifted one you do not mind retiring."], ["How long does the glue need to dry?", "Let it dry completely before wearing, at least 1 hour for fabric glue. Lay it flat while drying so the yarn rows do not slide."]]}, "cupcake": {"m": ["Brown t-shirt or tunic for the wrapper, 1 (make: from closet)", "White pillowcase for the frosting, 1 (make: from home)", "Red pom-pom or ball for the cherry, 1 about 2 inches (buy: craft store)", "Fabric glue, 1 tube (buy: craft store)"], "s": ["Put on the brown shirt. This is the cupcake wrapper.", "Drape the white pillowcase over your head and shoulders like frosting. Mark eye positions while wearing it, take it off, and trim eye holes SMALL first, then widen. Trim the bottom edge into a wavy frosting line.", "Glue the red pom-pom on top as the cherry.", "Fluff the pillowcase edges to look like frosting swirls.", "Optional pro finish: dot the pillowcase with fabric markers in sprinkle colors before wearing. Sprinkles turn 'person in a pillowcase' into cupcake.", "Optional pro finish: dot the pillowcase with fabric markers in sprinkle colors before wearing. Sprinkles turn 'person in a pillowcase' into cupcake."], "time": "15 min", "cost": "$3-6", "effort": "Easy", "faqs": [["How do you keep the pillowcase frosting on your head?", "It drapes, no attachment needed if the pillowcase is adult-size on a kid. For adults, pin it to a headband at the forehead so it does not slide."], ["What is the wrapper part?", "The brown shirt is the cupcake liner. Vertical marker stripes on the brown shirt sell the wrapper ridges."]]}, "banana": {"m": ["Yellow sweatshirt and sweatpants, 1 set (make: from closet, or buy: clothing store)", "Green felt, 1 sheet 9x12 inches (buy: craft store)", "Headband, 1 (buy: dollar store)", "Fabric glue, 1 tube (buy: craft store)"], "s": ["Put on the yellow sweatshirt and sweatpants.", "Cut a stem shape from green felt, about 4 inches tall.", "Hold the stem against the headband and check the position in a mirror BEFORE gluing, once fabric glue sets, the stem cannot be moved. Glue the stem to the headband and let it dry flat.", "Wear the headband. You are a banana.", "Optional pro finish: glue a small brown felt rectangle at the bottom front of the sweatshirt as the banana tip. Top and bottom details make it read as banana, not yellow sweats.", "Optional pro finish: glue a small brown felt rectangle at the bottom front of the sweatshirt as the banana tip. Top and bottom details make it read as banana, not yellow sweats."], "time": "10 min", "cost": "$2-5", "effort": "Easy", "faqs": [["How big should the banana stem be?", "About 4 inches tall and 2 inches wide. Bigger looks cartoonish in a good way; smaller disappears."], ["Can I make this with zero shopping?", "Yes if you own yellow sweats: cut the stem from a green t-shirt or paper bag painted green, and tape it to any headband or hat."]]}, "hot-dog": {"m": ["Red t-shirt, 1 (own)", "Tan or beige foam pool noodle, 1 (buy: dollar store)", "Yellow fabric paint for mustard, 1 bottle (buy: craft store)", "Safety pins or fabric glue, 1 pack (buy: craft store)"], "s": ["Put on the red shirt. You are the hot dog.", "Cut the pool noodle in half lengthwise to make two bun halves.", "Paint a thin mustard squiggle down one bun half with the yellow fabric paint. You can always add more paint, but you cannot remove it, so start thin. Let dry fully before attaching.", "Attach the bun halves to your sides with safety pins or fabric glue, one on each side.", "Optional pro finish: add a white paper vendor hat. The hat turns 'person in a bun' into a ballpark vendor, and vendors get offered tips.", "Optional pro finish: add a white paper vendor hat. The hat turns 'person in a bun' into a ballpark vendor, and vendors get offered tips."], "time": "15 minutes", "cost": "$3-6", "effort": "Easy", "faqs": [["How do you make the bun halves stay on the shoulders?", "Pin each half at the shoulder seam with two safety pins from inside the shirt. They sit like epaulettes, stable all night, no glue on skin."], ["Ketchup and mustard or just mustard?", "Both, in zigzag squiggles. The zigzag is the visual shorthand for condiments, straight lines read as stripes, zigzags read as sauce."]]}, "donut": {"m": ["1 large cardboard box, about 24x24 inches flat (make: from home)", "Pink paint, 1 small bottle (buy: craft store)", "Felt sprinkles, 12 to 15 small pieces, or sticker sprinkles (buy: craft store)", "Ribbon or string, 4 feet (make: from home)", "Scissors, 1 pair and glue, 1 bottle"], "s": ["Draw the donut circle on the cardboard first and check it fits over the head: outer circle about 30 inches across, center hole about 12 inches. Cut the center hole SMALLER than the head first, then widen. Cardboard cut away cannot be put back, and a too-big hole slides off the shoulders.", "Paint it pink. Let dry.", "Glue on felt sprinkles or stickers in bright colors.", "Attach ribbon to the top so you can wear it like a sandwich board.", "Optional pro finish: paint a thin brown ring around the center hole for the fried-dough edge. The brown edge is what separates donut from pink life preserver.", "Optional pro finish: paint a thin brown ring around the center hole for the fried-dough edge. The brown edge is what separates donut from pink life preserver."], "time": "35 min + drying", "cost": "$3-8", "effort": "Easy", "faqs": [["How do you wear a big cardboard donut comfortably?", "Hang it from two ribbon straps like a sandwich board at waist height, not neck height. Waist height clears doorways and lets the arms move."], ["How long does the pink paint take to dry?", "About 1 hour for acrylic on cardboard. Paint the night before: wearing it damp smears pink onto every hug."]]}, "coffee-cup": {"m": ["White trash bag or white sheet, 1 large (make: from home)", "Cardboard tube or large cylinder, 1 (make: from home)", "Brown paper or felt for the lid, 1 sheet (buy: craft store)", "Brown marker, 1 thick (buy: dollar store)"], "s": ["Cut the arm holes first, then the head hole SMALL, stretch the bag over the head to test before cutting bigger. Cut holes in the white trash bag for head and arms with the scissors. This is the cup. A head hole cut too big slides off the shoulders.", "Draw a coffee shop logo on the front with brown marker.", "Make the lid: cut a brown paper circle bigger than your head, with a sip hole.", "Wear the bag, then the lid hat on top.", "Optional pro finish: cut a cardboard sleeve, write a coffee-shop pun on it ('Decaf? Never met her'), and tape it around the torso. The sleeve is what makes it a to-go cup instead of a white bag.", "Optional pro finish: cut a cardboard sleeve, write a coffee-shop pun on it ('Decaf? Never met her'), and tape it around the torso. The sleeve is what makes it a to-go cup instead of a white bag."], "time": "20 min", "cost": "$2-5", "effort": "Easy", "faqs": [["How do you keep a trash-bag costume from looking like a trash bag?", "The lid and the logo do all the work. A brown lid hat plus a big drawn logo reads as coffee cup; without them it reads as trash bag."], ["Is a trash bag safe to wear?", "Cut generous head and arm holes before putting it on, never pull it over the face, and keep it away from very small children. A white sheet is the safer alternative for toddlers."]]}, "salt-pepper": {"m": ["White shirt, pants, and hat for Salt, 1 set (own)", "Black shirt, pants, and hat for Pepper, 1 set (own)", "Cardboard for 2 shaker tops (make: from home)", "Gray paint or gray marker, 1 (buy: craft store)", "Black marker for the S and P, 1 (own)", "Tape or glue, 1 (own)"], "s": ["Salt dresses all in white, Pepper all in black.", "Cut two shaker tops from cardboard: a short wide cylinder or dome each, big enough to sit on a hat.", "Paint them gray and dot holes on top like a real shaker. Let dry.", "Tape each top to a hat so it rides on your head.", "Letter the caps BIG. Four-inch letters minimum, because the letter is the costume. Write a big S on Salt's shaker and a big P on Pepper's with the black marker.", "Optional pro finish: carry actual salt and pepper shakers and offer to 'season' people's costumes. The seasoning bit is the party trick, use it liberally.", "Optional pro finish: carry actual salt and pepper shakers and offer to 'season' people's costumes. The seasoning bit is the party trick, use it liberally."], "time": "15 min", "cost": "$2-5", "effort": "Easy", "faqs": [["How do you make the shaker tops?", "Cut a short wide cylinder or dome from cardboard that fits over a hat, tape it shut, paint it gray, and dot holes on top like a real shaker."], ["Who is salt and who is pepper?", "Taller person is pepper (the bigger shaker energy), or whoever wants to be. There is no wrong answer."]]}, "fruit-salad": {"m": ["Solid-color outfits in fruit colors (red, yellow, green, orange), 1 set per person (own)", "Green felt for leaf hats, 1 sheet 9x12 inches per person (buy: craft store)", "Headbands, 1 per person (buy: dollar store)", "Fabric glue, 1 tube (buy: craft store)"], "s": ["Each person picks a fruit and wears that color head to toe. Red for strawberry, yellow for banana, green for lime, orange for orange.", "Cut leaf shapes from green felt.", "Glue one leaf to each headband and let it set fully before wearing. Glued leaves cannot be repositioned, so center each leaf on the band and press for 30 seconds.", "Everyone wears their headband. Take a group photo as the fruit salad.", "Optional pro finish: snip a center vein down each felt leaf with the scissors. The vein makes flat felt read as a real leaf in photos.", "Optional pro finish: snip a center vein down each felt leaf with the scissors. The vein makes flat felt read as a real leaf in photos."], "time": "20 minutes", "cost": "$3-8", "effort": "Easy", "faqs": [["How many fruits make a good salad?", "Four to six. Three looks thin, more than six gets hard to photograph. Assign the biggest person the watermelon."], ["How do you keep the leaf hats on?", "Glue the leaf to the front-center of the headband and let it set fully. A leaf glued off-center flops forward all night."]]}, "wizard": {"m": ["Tall black pointy wizard hat, 1 (buy: costume aisle or craft store)", "Long plain black robe or graduation gown, 1 (own, or buy: thrift store)", "Tall straight wooden staff, about 5 feet (make: from a dowel or sturdy branch, or buy: craft store)", "Gray face paint or stick-on gray beard, 1 (buy: costume aisle, optional)", "Belt or rope sash, 1 (own)"], "s": ["Size the hat to the head BEFORE decorating, a hat decorated then found too small is heartbreaking. Put on the robe. Roll the paper into a tall wizard hat or use the store-bought one; confirm it sits without covering the eyes. Stick the star stickers on the robe and hat.", "Safety: keep the hat brim above the eyes so vision stays clear, and carry the staff upright. Never swing it at anyone.", "Draw on a gray beard with the face paint, or stick on the fake beard.", "Tie the belt or rope sash around the waist over the robe.", "Put on the pointy hat last, tap the staff on the ground, and strike a pose.", "Optional pro finish: tape a battery tea light to the wand tip. A wand that glows when you cast is the detail kids remember for years, the gasps are worth the tape.", "Optional pro finish: tape a battery tea light to the wand tip. A wand that glows when you cast is the detail kids remember for years, the gasps are worth the tape."], "time": "20 min", "cost": "$3-8", "effort": "Easy", "faqs": [["How tall should the wizard hat be?", "About as tall as the head. Taller looks impressive but flops without internal support, roll a cone of cardstock inside for structure."], ["What goes in the spell book?", "Write silly spells on the pages in marker ('Spell for extra dessert: say please three times'). People WILL open it, make it funny."]]}, "toy-box-crew": {"m": ["Cowboy hat, 1, and cow-print vest, 1, for the sheriff (buy: costume aisle or thrift store)", "White shirt and pants, 1 set, with purple felt accents for the space ranger (own: from closet)", "Cardboard wings and 1 clear plastic dome for the space ranger helmet (own: from craft supplies)", "Brown boots or boot covers, 1 pair, for the sheriff (own: from closet)", "Yellow shirt, 1, with a hand-drawn star badge for extra toy-box friends (own: from closet)", "Toy pull-string name tags, 1 per person (own: index cards)", "Marker, 1; scissors, 1 pair; glue, 1 bottle; tape, 1 roll (own: household)"], "s": ["Buy the cowboy hat, cow-print vest, purple felt, and clear plastic dome. Pull white clothes for the space ranger, brown boots for the sheriff, and a yellow shirt for extra toy-box friends from the closet.", "Sheriff: wear the cowboy hat, cow-print vest, and brown boots. Draw a star badge on the yellow shirt with a marker.", "Lay the felt fins and buttons on the white shirt first and check the placement in a mirror before gluing, since glued felt cannot be moved. Space ranger: cut purple felt fins and buttons and glue them to the white shirt. Tape the cardboard wings to the back and wear the clear plastic dome as a helmet.", "Safety: keep the plastic dome above the shoulders with the face fully open, and carry any toy props low so nobody gets poked.", "Tie a pull-string name tag to each wrist. Strike the sheriff pose and the space-ranger landing pose for the group photo.", "Optional pro finish: draw a round speaker circle on the space ranger's chest and write PULL on it, so the pull-string joke lands without explanation.", "Optional pro finish: draw a round speaker circle on the space ranger's chest and write PULL on it, so the pull-string joke lands without explanation."], "time": "35 min", "cost": "$8-15", "effort": "Easy", "faqs": [["Will the clear plastic dome fog up or block vision?", "Keep the dome above the shoulders with the face fully open, never sealed around the neck. It is a helmet prop, not a closed bubble."], ["How do the pull-string name tags work?", "Write each character name on an index card, punch a hole, and tie it to the wrist with string. It reads as the pull string and doubles as the name tag."]]}, "demon-boy-band": {"m": ["Oversized black or white t-shirt per person, 1 each (make: from closet)", "Baggy pants per person, 1 pair each (make: from closet)", "Neon fabric paint, 1 small bottle each in 2 colors (buy: craft store)", "Temporary tattoos or 1 neon eyeliner pencil (buy: drugstore)", "Toy microphone per person, 1 each (buy: dollar store)", "Hair gel, 1 travel-size tube (make: from the bathroom)", "Sunglasses per person, 1 each, optional (make: from the drawer)"], "s": ["Buy the neon fabric paint, temporary tattoos, toy microphones, and hair gel. Lay out the matching black or white outfits.", "Decide the pattern together first and sketch it on paper, then test the neon fabric paint on an inside seam so you know how it looks. Paint matching glowing patterns on everyone: lightning marks on the sleeves, circles on the chest. Keep all paint on the clothes, off faces and away from eyes. Let the paint dry flat for 2 hours.", "Apply neon eyeliner or temporary tattoos on cheeks and hands. Style hair up and forward with the gel.", "Safety: keep paint off faces and away from eyes.", "Wear the matching streetwear, carry a toy microphone each, line up shoulder to shoulder, and strike the synchronized album-cover pose.", "Optional pro finish: give every member the same temporary tattoo on the same cheek. One matching detail is what turns matching shirts into a band.", "Optional pro finish: give every member the same temporary tattoo on the same cheek. One matching detail is what turns matching shirts into a band."], "time": "40 min + drying", "cost": "$6-15", "effort": "Easy", "faqs": [["Will neon fabric paint glow without a black light?", "No, it needs a black light to pop. Without one it still reads as bright neon color, so check what the venue has before you count on the glow."], ["How do you keep the paint from cracking when they move?", "Paint thin lines, not thick blobs, and let it dry the full 2 hours. Thick paint cracks the first time an arm bends."]]}, "dragon-rider-duo": {"m": ["1 brown t-shirt and 1 pair dark pants for the rider (make: from closet)", "Gray felt, 2 yards, or 1 old gray blanket for the dragon tunic (buy: craft store or thrift store)", "1 large cardboard box for wings and tail (make: collect spares)", "Black and yellow craft foam, 1 sheet each for the dragon eyes (buy: craft store)", "1 faux-fur vest or brown scarf for the rider (make: from closet)", "1 headband for the dragon eyes", "Scissors, tape, and string, 6 feet (make: household tools)"], "s": ["Buy the gray felt, craft foam, scissors, and tape. Pull the brown t-shirt, dark pants, and faux-fur vest from the closet.", "Draw the wing shape on paper first and hold it against the dragon person's back: wings should reach from shoulder to hip. Cut two wing shapes and a long tail from the cardboard box with the scissors. Cut the wings smaller than the paper test, not bigger: oversized cardboard wings hit every doorway. Tape all cut edges smooth before wearing.", "Glue the black and yellow foam eyes to a headband for the dragon head. The rider wears the faux-fur vest over the brown t-shirt.", "Safety: keep wing tips above waist height and tape all cardboard edges smooth so nobody gets scratched.", "Rider stands in front with arms out like steering; dragon crouches behind with wings spread. Take the flying photo.", "Optional pro finish: tape a row of small cardboard triangles along the dragon's shoulders as back ridges. Ridges plus wings read as dragon; wings alone read as bird.", "Optional pro finish: tape a row of small cardboard triangles along the dragon's shoulders as back ridges. Ridges plus wings read as dragon; wings alone read as bird."], "time": "60 min", "cost": "$5-10", "effort": "Medium", "faqs": [["How do you keep cardboard wings up?", "Tape them to the gray felt tunic, not the person, with wide packing-tape tabs on both sides. Taped wings stay up for hours; glued wings peel."], ["What is the best pose for the photo?", "Rider stands in front with arms out like steering, dragon crouches behind with wings spread. The crouch sells the size difference."]]}, "numbered-players": {"m": ["Green sweatsuit per person, 1 each (buy: thrift store, or own: from closet)", "White t-shirt per person, 1 each (own: from closet)", "Iron-on number patches or white paper numbers, 1 per person (buy: craft store)", "White sneakers, 1 pair per person (own: from closet)", "Dalgona candy or a round cookie per person, 1 each (buy: bakery, optional prop)", "Iron, 1 (own: household)"], "s": ["Buy the green sweatsuits and number patches. Pull white t-shirts and white sneakers from the closet.", "Lay the numbers on each shirt and have the wearers confirm their number BEFORE heating the iron, iron-on numbers cannot be repositioned once pressed. Iron or tape one number onto the front of each white t-shirt and the matching number on the back.", "Wear the white t-shirt under the green sweatsuit jacket with the number showing, plus the white sneakers.", "Hand each player a dalgona candy as the prop. Line up in number order for the photo.", "Safety: if using an iron, have an adult do the pressing. Keep numbers readable and identical front and back.", "Optional pro finish: draw a thin triangle border around each number with a black fabric marker. The border is what makes the number read as a player badge instead of a sticker.", "Optional pro finish: draw a thin triangle border around each number with a black fabric marker. The border is what makes the number read as a player badge instead of a sticker."], "time": "30 min", "cost": "$4-10", "effort": "Easy", "faqs": [["Iron-on numbers or taped paper numbers?", "Iron-on for teens and adults who will keep the shirt; taped paper numbers for kids or borrowed shirts. Tape survives one evening fine and peels off clean."], ["What if we cannot find green sweatsuits?", "Any green top and pants work, the white numbered t-shirt over green is the whole read. The sweatsuit is a nice-to-have, not the costume."]]}, "emotion-crew": {"m": ["1 solid bright color outfit per person: yellow, blue, red, green, purple, or orange (make: from closet)", "Face paint matching each outfit color, 1 per person (buy: drugstore)", "1 white poster board per person (buy: dollar store)", "Markers, 1 set (make: from the house)", "Colored hair spray matching each outfit, 1 can per person, optional (buy: drugstore)"], "s": ["Pull one loud solid-color outfit per person from the closet. Buy the face paint, poster board, and markers.", "Each person picks an emotion and writes it big on poster board: Joy, Sadness, Anger, Fear, Disgust, Anxiety, Envy, Embarrassment, Ennui.", "Paint a simple face design in the matching color: a big smile, a tear, furrowed brows. Mist hair with the matching color spray if you like.", "Wear the full monochrome outfit with the emotion sign. Group up in a row like the control panel.", "Optional pro finish: paint each face design in the matching outfit color only, one color per person. Mixed colors muddy the read; monochrome reads as a character.", "Optional pro finish: paint each face design in the matching outfit color only, one color per person. Mixed colors muddy the read; monochrome reads as a character."], "time": "25 min", "cost": "$5-10", "effort": "Easy", "faqs": [["How do you stop two people picking the same emotion?", "Assign emotions before anyone shops: Joy, Sadness, Anger, Fear, Disgust, Anxiety, Envy, Embarrassment, Ennui. First come first served, written on a list."], ["How big should the emotion sign be?", "Letter it 4 inches tall minimum on the poster board. The sign is the costume's label: if nobody can read it across the room, it is decoration."]]}, "kart-racers": {"m": ["Large cardboard box, 1 per racer, big enough to fit around the torso (make: collect spares)", "Red, blue, green, and yellow paint or wrapping paper, 1 bottle or roll per color (buy: dollar store)", "Paper plates for wheels, 4 per kart (buy: dollar store)", "Racing cap or helmet, 1 per person (own: from closet)", "Scissors, 1 pair, tape, 1 roll, and string, 1 spool (own: household tools)", "Ribbon for kart straps, about 3 feet per kart (own: from closet)"], "s": ["Buy the paint or wrapping paper and paper plates. Collect one large box per racer.", "Have each racer step inside the box first and mark where the waist sits BEFORE cutting, an opening cut too big slides down, and cardboard cut away cannot be put back. Cut the top and bottom out of each box so it fits around the torso like a kart, starting with a smaller opening and widening. Paint each kart a different bright color.", "Tape two paper-plate wheels to each side. Tape ribbon straps inside so the kart hangs at waist height.", "Safety: keep the kart box at waist height so legs move freely, and tape all cut edges smooth.", "Wear the kart with the racing cap, line up side by side, and strike the starting-grid pose.", "Optional pro finish: number each kart with a big marker digit on the front. Numbered karts turn a row of boxes into a starting grid.", "Optional pro finish: number each kart with a big marker digit on the front. Numbered karts turn a row of boxes into a starting grid."], "time": "45 min + drying", "cost": "$2-6", "effort": "Medium", "faqs": [["How do you wear a cardboard kart without tripping?", "Keep the box at waist height with the ribbon straps, and keep the bottom opening wide enough that legs move freely. Tape all cut edges smooth so cardboard never scratches thighs."], ["Paint or wrapping paper for the kart color?", "Wrapping paper is faster and has zero drying time; paint looks better up close. For kids, wrapping paper wins, they can help tape it on."]]}, "tall-hat-crew": {"m": ["Tall red-and-white striped stovepipe hat, 1 (buy: costume aisle, or make: poster board)", "Red bow tie, 1 (buy: dollar store, or make: paper)", "Black shirt and pants for the cat, 1 set (own: from closet)", "Red jumpsuits or red shirts and pants for the Things, 2 sets (own: from closet)", "Blue wigs, 2 (buy: costume aisle)", "Iron-on letters or paper that says Thing 1 and Thing 2, 1 set (buy: craft store)", "Iron, 1, and scissors, 1 pair (own: household)"], "s": ["Buy the striped hat, blue wigs, red bow tie, and iron-on letters. Pull black and red clothes from the closet.", "Cat: wear the black shirt and pants, the tall striped hat, and the red bow tie.", "Position the paper letters on each chest and check the spelling and straightness in a mirror BEFORE ironing, since iron-on letters cannot be removed. Things: wear the red jumpsuits with the blue wigs. Iron or tape Thing 1 and Thing 2 onto the chests.", "The Things bounce and cause trouble; the cat looks worried. That is the whole photo.", "Optional pro finish: add white gloves for the Things and a red ribbon tail on the cat, both cheap and both sell the characters.", "Optional pro finish: add white gloves for the Things and a red ribbon tail on the cat, both cheap and both sell the characters."], "time": "20 min", "cost": "$8-15", "effort": "Easy", "faqs": [["How do you make the tall hat from poster board?", "Roll the poster board into a tall cone and tape the seam, then cut a wide circle with a hole for the brim and tape it to the base. Paint or tape on the red stripes."], ["How does the tall hat stay on?", "Thread an elastic chin string through the sides or anchor it with bobby pins through the hat into the hair. A snug inner band of folded paper helps too."]]}, "chipmunk-trio": {"m": ["Red, blue, and green sweaters or sweatshirts, 1 each (buy: thrift store)", "Iron-on letters A, S, T, 1 set (buy: craft store)", "Brown felt for ears, 3 pairs worth, 1 sheet 9x12 inches (buy: craft store)", "Headbands, 3 (buy: dollar store)", "Brown eyeliner for whiskers and a nose, 1 (buy: drugstore)", "Fabric glue, 1 tube (buy: craft store)"], "s": ["Buy the sweaters, iron-on letters, brown felt, headbands, and brown eyeliner.", "Position the letters with the sweaters laid flat and have each person confirm their letter BEFORE heating the iron, iron-on letters cannot be repositioned. Iron A onto the red sweater, S onto the blue, T onto the green. Let them cool flat.", "Cut round chipmunk ears from the brown felt and glue one pair to each headband.", "Wear the letter sweaters with the ear headbands. Draw three whisker dots and a nose on each cheek with the brown eyeliner.", "Line up tallest to shortest and sing one note together for the photo.", "Optional pro finish: stuff each cheek with a cotton ball for the group photo. Chipmunk cheeks full of 'acorns' get the laugh every single time.", "Optional pro finish: stuff each cheek with a cotton ball for the group photo. Chipmunk cheeks full of 'acorns' get the laugh every single time."], "time": "25 min", "cost": "$8-15", "effort": "Easy", "faqs": [["Which chipmunk is which?", "Red + A is the leader, blue + S is the cool one, green + T is the chubby one. Line up tallest to shortest in that order and the reference lands."], ["No iron, can I still do the letters?", "Yes: cut the letters from felt and fabric-glue them on, or safety-pin paper letters. Iron-on is cleanest, but glued felt survives the night."]]}, "galaxy-knights": {"m": ["1 brown or beige bathrobe or long coat per knight (make: from closet)", "1 toy energy-blade prop per knight (buy: toy store)", "1 wide belt or rope sash per knight (make: from closet)", "1 pair dark pants and boots per knight (make: from closet)", "Brown face paint for a hood shadow, 1 tube, optional (buy: drugstore)"], "s": ["Buy the toy energy-blade props. Pull the bathrobes, belts, dark pants, and boots from the closet.", "Wear the bathrobe over dark pants with the belt tied at the waist. Pull the hood up.", "Carry the energy blade unlit until the photo. Two stances: blade up ready, or blade down calm.", "Safety: keep the toy blades pointed up or down, never at faces. Sparring stays slow and pretend.", "Line up the knights in a row, ignite the blades, and take the council photo.", "Optional pro finish: tie the belt over the robe at the natural waist and let the robe flare below it. Belted robes read as uniform; unbelted robes read as bath time.", "Optional pro finish: tie the belt over the robe at the natural waist and let the robe flare below it. Belted robes read as uniform; unbelted robes read as bath time."], "time": "10 min", "cost": "$8-20", "effort": "Easy", "faqs": [["Are toy energy blades safe for kids?", "Yes if they are soft foam or plastic with rounded tips. Keep blades pointed up or down, never at faces, and skip hard plastic for kids under 6."], ["How do you make a bathrobe not look like a bathrobe?", "Belt it tight at the waist, pull the hood up, and wear dark pants and boots underneath. The belt and the boots do all the work."]]}, "plastic-dream-crew": {"m": ["All-pink outfit per person: dress, suit, or sweatsuit, 1 set each (own)", "Pink sunglasses, 1 per person (buy: dollar store)", "Plastic play accessories: phone, tiara, handbag, 1 per person (own)", "Pink feather boa, 1 to share (buy: dollar store, optional)", "Blonde wig, 1 per person (buy: costume aisle, optional)"], "s": ["Pull an all-pink outfit per person from the closet. Buy the pink sunglasses and feather boa.", "Everyone wears pink head to toe with the pink sunglasses. Add the tiara, handbag, or toy phone.", "Drape the feather boa over whoever is feeling the most plastic today.", "Strike the wave-and-smile pose. Everything is pink, and that is the whole point.", "Optional pro finish: give everyone the same accessory, matching sunglasses or matching purses. Uniform accessories are what turn pink outfits into a crew.", "Optional pro finish: try the wig on for 20 minutes before the party. Itchy wigs get ripped off by nine.", "Optional pro finish: give everyone the same accessory, matching sunglasses or matching purses. Uniform accessories are what turn pink outfits into a crew.", "Optional pro finish: try the wig on for 20 minutes before the party. Itchy wigs get ripped off by nine."], "time": "15 min", "cost": "$0-5", "effort": "Easy", "faqs": [["Do you need the wigs?", "No, matching pink outfits plus matching accessories carry it. Wigs help but the uniformity is the costume, not the hair."], ["How do you keep it from looking like just pink clothes?", "Commit to the bit: wave like a doll, pose like a doll, talk like everything is fantastic. The performance is the costume."]]}, "extinct-party-animal": {"m": ["1 jacket or blazer you own (own)", "1 sheet green craft felt, 9x12 inches (buy: craft store; construction paper works too)", "1 party hat (buy: dollar store or party aisle)", "1 blank name badge (buy: office supply aisle)", "Fabric glue, 1 tube (buy: craft store)", "Marker, 1", "Scissors, 1 pair"], "s": ["Buy the green craft felt, party hat, blank badge, and fabric glue.", "Cut one paper spike first and check the size against the jacket shoulder, about 3 inches tall. Cut 6 to 8 triangle spikes from the green craft felt with the scissors. Cut them all from the template so the row looks even.", "Glue the spikes in a row along the shoulders of the jacket. Let dry 15 minutes.", "Write 'Last seen 66 million years ago' on the badge with the marker.", "Pin on the badge, put on the party hat, and work the room.", "Optional pro finish: write 'Last seen 66 million years ago' in neat block letters on the badge. Neat handwriting sells the museum-label joke; scribble kills it.", "Optional pro finish: write 'Last seen 66 million years ago' in neat block letters on the badge. Neat handwriting sells the museum-label joke; scribble kills it."], "time": "20 min + drying", "cost": "$3-8", "effort": "Easy", "faqs": [["Will the spikes survive on a blazer all night?", "Yes if you glue them the night before and let the glue cure. Same-day glue peels when the jacket moves."], ["How do you make the party hat stay on?", "Tape a bobby pin to the inside of the hat and clip it to the hair. Elastic straps slip; a bobby pin holds."]]}, "dino-tourist": {"m": ["1 Hawaiian shirt (buy: thrift store, or use your own)", "1 fanny pack (own, or buy: thrift store)", "1 plush dinosaur tail (buy: toy store or online)", "1 toy camera, optional (own)", "1 pair sunglasses, optional (own)"], "s": ["Pull the Hawaiian shirt and fanny pack from the closet.", "Clip or pin the plush tail to your waistband at the back.", "Hang the toy camera around your neck.", "Put on the sunglasses, ask strangers to take your picture, and complain about the meteor.", "Optional pro finish: tuck a folded paper map into the fanny pack and let it stick out. The map is the tourist detail people laugh at.", "Optional pro finish: tuck a folded paper map into the fanny pack and let it stick out. The map is the tourist detail people laugh at."], "time": "10 min", "cost": "$0-12", "effort": "Easy", "faqs": [["How do you attach the tail so it stays on?", "Clip or pin it to the waistband at the back center with two safety pins through the tail's seam. One pin spins; two pins hold."], ["How do you make it read as dinosaur, not just tourist?", "The tail does all the work. Without it you are just a tourist: wear it high on the waistband where people see it from the side."]]}, "raptor-barista": {"m": ["Green hoodie, 1 (buy: clothing store, or use your own)", "Toy T. rex arms, 1 pair (buy: toy store or online)", "Paper coffee cup, 1 (own: from home)", "Brown eyeliner pencil, 1 (own, optional)"], "s": ["Buy the green hoodie and toy T. rex arms.", "Put on the green hoodie with the hood up.", "Strap the tiny T. rex arms over your own arms at the elbows.", "Grab the paper coffee cup with the tiny arms and serve.", "Optional pro finish: write a fake coffee order on the cup in marker, like RAWR-LATTE, and tape a paper name tag to the hoodie as your barista badge.", "Optional pro finish: write a fake coffee order on the cup in marker, like RAWR-LATTE, and tape a paper name tag to the hoodie as your barista badge."], "time": "10 min", "cost": "$0-5", "effort": "Easy", "faqs": [["How do the tiny arms stay on?", "Strap the tiny T. rex arms over your own arms at the elbows. They sit best on a hoodie with snug sleeves so they do not slide down."], ["What if I cannot find toy dinosaur arms?", "Cut two small arms from green felt and pin them to the hoodie sleeves at the elbows. They will not grip the cup, so tuck the cup between the felt arms for photos."]]}, "emotional-support-dinosaur": {"m": ["1 vest or sleeveless jacket you own (own)", "1 sheet green craft felt, 9x12 inches (buy: craft store; construction paper works too)", "1 blank badge or pin (buy: office supply aisle)", "Fabric glue, 1 tube (buy: craft store)", "Marker, 1", "Scissors, 1 pair"], "s": ["Buy the green craft felt, blank badge, and fabric glue.", "Cut one paper spike first and hold it against the vest shoulder to check the size, about 3 inches tall. Cut 6 to 8 triangle spikes from the green craft felt with the scissors using the paper template. Uniform spikes look designed; freehand spikes look ragged.", "Glue the spikes along the vest shoulders and back. Let dry 15 minutes.", "Write 'Emotional Support Dinosaur. Do not pet.' on the badge with the marker.", "Pin it on and refuse all pets.", "Optional pro finish: write 'Emotional Support Dinosaur' in all caps on the badge, then add 'Do not pet.' underneath in smaller letters. The official-looking hierarchy sells the joke.", "Optional pro finish: write 'Emotional Support Dinosaur' in all caps on the badge, then add 'Do not pet.' underneath in smaller letters. The official-looking hierarchy sells the joke."], "time": "25 min + drying", "cost": "$3-8", "effort": "Easy", "faqs": [["Will fabric glue hold spikes through a night of hugs?", "Yes if you glue the night before so it cures fully. Same-day glue is still tacky by party time and spikes slide."], ["What vest works best?", "Any vest or sleeveless jacket with structured shoulders: denim, fleece, or utility. Floppy vests let the spikes droop."]]}, "garden-fairy": {"m": ["Pink tulle, 1 yard (buy: craft store)", "Cardboard for wings, 1 large piece about 2x3 feet (make: from a shipping box)", "Fake flowers, 1 bunch (buy: dollar store)", "Headband, 1 (buy: dollar store, or own)", "Wooden dowel or stick for the wand, about 12 inches (make: from the yard)", "Cardboard star for the wand tip, 1 (make: from scraps)", "Elastic for wing straps, about 2 feet (buy: craft store)", "Glitter glue, 1 tube (buy: craft store)", "Tape, 1 roll", "Glue, 1 bottle", "Scissors, 1 pair"], "s": ["Buy the pink tulle, fake flowers, headband, and elastic.", "Draw ONE wing on paper, cut it, and trace it flipped for the second. Symmetric wings are the fairy illusion. Cut two large wing shapes from the cardboard with the scissors.", "Cover each wing with pink tulle and tape the edges down.", "Glue fake flowers around the headband for the crown.", "Tape the cardboard star to the top of the dowel for the wand.", "Safety: keep the wand away from faces during photos.", "Tape elastic straps to the back of the wings and slip arms through.", "Optional pro finish: outline the wing edges with glitter glue and add three dots down the center. The glitter edge catches light in every photo.", "Optional pro finish: outline the wing edges with glitter glue and add three dots down the center. The glitter edge catches light in every photo."], "time": "20 min", "cost": "$3-8", "effort": "Easy", "faqs": [["How do you keep cardboard wings from flopping?", "Score a center crease and tape a ruler or paint stick along the back as a spine. Flat cardboard folds; spined cardboard holds."], ["What is the fastest fairy wand?", "A stick with a star cut from cardboard, glittered, taped on. Five minutes, and every fairy photo needs the wand."]]}, "ballerina": {"m": ["Pink tulle, 2 to 3 yards (buy: craft store; about $1 a yard)", "Wide elastic, 1 inch wide, cut to the waist size plus 1 inch overlap (buy: craft store)", "Pink leotard or fitted shirt, 1 (own, or buy: clothing store)", "Pink tights, 1 pair (own, or buy: clothing store)", "Hair ties and bobby pins, 1 pack (own)", "Scissors, 1 pair"], "s": ["Measure the waist with the elastic: wrap it snug where the tutu will sit, overlap 1 inch, and cut. Tie or knot the overlap into a loop, this is the waistband. Cut it to the waist, not the hips, or the tutu slides down while twirling.", "Cut the tulle into strips about 3 inches wide and twice as long as you want the skirt. For a toddler, strips roughly 3 by 20 inches; longer for bigger kids.", "Fold one strip in half to make a loop at the top. Slip the loop under the elastic, pull the strip ends through the loop, and pull tight. Repeat side by side all the way around until the tutu looks full, usually 30 to 40 strips.", "Fluff the strips outward. Trim the bottom edge even while the tutu hangs.", "Safety: the elastic should sit snug on the waist, not the hips, so it stays up while twirling. Nothing tied around the neck.", "Wear the tutu over the leotard and tights. Pull the hair into a high bun with the hair ties and bobby pins.", "Optional pro finish: tie a short length of satin ribbon into a small bow and pin it at the back waistband. One bow is the difference between craft project and costume."], "time": "20 min", "cost": "$3-8", "effort": "Easy", "faqs": [["How much tulle for a no-sew tutu?", "2 yards for a toddler, 3 for a bigger kid. Cut strips 3 inches wide, with length equal to twice the finished skirt length."], ["How do you keep a no-sew tutu from falling down?", "Measure the elastic snug at the waist (not the hips) with a 1-inch overlap, and tie strips tight against each other so the weight stays balanced."]]}, "butterfly": {"m": ["Large cardboard for wings, 1 sheet about 3x2 feet (make: from a shipping box)", "Acrylic paint set, 1 (buy: craft store)", "Black sweatsuit, 1 set (own, or buy: clothing store)", "Elastic for wing straps, about 2 feet (buy: craft store)", "Headband, 1 (buy: dollar store, or use your own)", "Pipe cleaners for antennae, 2 (buy: craft store)", "Tape, 1 roll", "Scissors, 1 pair"], "s": ["Buy the paint, elastic, headband, and pipe cleaners. Pull black sweats from the closet.", "Draw ONE wing on paper first, cut it out, and trace it flipped for the second, symmetric wings are the whole butterfly illusion. Cut two big wing shapes from the cardboard with the scissors following the template.", "Paint both wings with bright patterns and let them dry flat.", "Tape elastic loops to the back of each wing for the arms.", "Bend pipe cleaners into antennae and tape them to the headband.", "Safety: keep wing edges away from doorways; turn sideways to pass through.", "Wear the wings over the black sweats with the antennae headband.", "Optional pro finish: outline the wing patterns with glitter glue after the paint dries. The glitter edge catches light and photographs like real wing scales.", "Optional pro finish: outline the wing patterns with glitter glue after the paint dries. The glitter edge catches light and photographs like real wing scales."], "time": "40 min + drying", "cost": "$5-10", "effort": "Medium", "faqs": [["How big should butterfly wings be?", "Wingtip to wingtip about as wide as the wearer's arm span. Bigger looks majestic in photos but will not fit through doorways, turn sideways."], ["How do you attach wings so they stay up?", "Tape two elastic loops to the back of each wing and slip arms through like a backpack. Elastic, not ribbon, it flexes when they move."]]}, "pop-star": {"m": ["Sparkly or sequin jacket, 1 (buy: thrift store)", "Toy microphone, 1 (buy: toy store or dollar store)", "Hair teasing comb, 1 (own, or buy: drugstore)", "Sunglasses, 1 pair (own, or buy: dollar store)", "Dark jeans and a dark top, 1 set (own)"], "s": ["Buy the sparkly jacket, toy microphone, and sunglasses.", "Tease the hair big with the comb.", "Safety: go easy teasing near the scalp; no pulling hard.", "Wear the sparkly jacket over the dark jeans and top.", "Put on the sunglasses.", "Carry the toy microphone everywhere and take requests.", "Optional pro finish: learn one 8-count of choreography and do it on request all night. A pop star who performs is unforgettable; one who just stands there is overdressed.", "Optional pro finish: learn one 8-count of choreography and do it on request all night. A pop star who performs is unforgettable; one who just stands there is overdressed."], "time": "15 min", "cost": "$0-8", "effort": "Easy", "faqs": [["Which pop star should I pick?", "Whoever's outfit you can build from your closet, the hair and the attitude matter more than the exact outfit. Commit to one era, not a mashup."], ["How do you get big pop-star hair?", "Backcomb the crown, spray it, and let the ends stay smooth. Volume on top, smooth below, that is the silhouette."]]}, "ice-skater": {"m": ["White dress, 1 (buy: thrift store, or own)", "White tights, 1 pair (own, or buy: clothing store)", "Hair donut for the bun, 1 (buy: drugstore)", "Blush, 1 (own, or buy: drugstore)", "Bobby pins, 1 pack (own)"], "s": ["Buy or pull the white dress, white tights, and hair donut.", "Twist the hair into a high bun around the hair donut and pin it.", "Dab a little blush on the cheeks for the cold-air glow.", "Safety: skip real skates; this costume is for dry land only.", "Wear the white dress with the tights and strike the finishing pose.", "Optional pro finish: wrap white ribbon crisscrossed up the calves over the tights. The laced calves read as skates even in sneakers.", "Optional pro finish: wrap white ribbon crisscrossed up the calves over the tights. The laced calves read as skates even in sneakers."], "time": "10 minutes", "cost": "$0-5", "effort": "Easy", "faqs": [["No ice skates, what goes on the feet?", "White sneakers or white boots. Nobody sees feet past the laced calves; the ribbon lacing does the work."], ["How do you get the perfect skater bun?", "A hair donut plus bobby pins, twist the hair around the donut and pin every inch. The donut is the difference between a bun and a lump."]]}, "ladybug": {"m": ["Red shirt, 1 (own)", "Black pants, 1 pair (own)", "Black felt for dots, 1 sheet 9x12 inches (buy: craft store)", "Headband, 1 (buy: dollar store)", "Black pipe cleaners for antennae, 2 (buy: craft store)", "Black pom-poms, 2 small (buy: craft store)", "Scissors, 1 pair", "Fabric glue, 1 tube (buy: craft store)"], "s": ["Buy the black felt, headband, and pipe cleaners. Pull the red sweatsuit from the closet.", "Cut lots of circles from the black felt with the scissors.", "Arrange all the dots on the shirt DRY first and step back to check, dots cluster in the middle if you glue as you go. Cut 8 to 10 black felt circles with the scissors, arrange them spread across the red shirt, then glue.", "Cut two small wing shapes from the felt scraps, dot them, and pin them at the back.", "Bend pipe cleaners into antennae and attach them to the headband.", "Safety: pin the wings where little hands cannot reach the pins.", "Wear the dotted sweats with the antennae headband.", "Optional pro finish: paint a black center line down the back of the shirt with fabric paint. The center line splits the wings, without it, the dots read as polka dots, not ladybug.", "Optional pro finish: paint a black center line down the back of the shirt with fabric paint. The center line splits the wings, without it, the dots read as polka dots, not ladybug."], "time": "20 min", "cost": "$3-8", "effort": "Easy", "faqs": [["How many dots does a ladybug need?", "Seven is the classic (like the seven-spotted ladybug), but 8 to 10 spread evenly photographs better. Odd numbers look natural; even numbers look patterned."], ["How do you keep felt dots on through the night?", "Fabric glue applied the night before, or safety pins from inside for day-of. Tape peels by hour two, do not trust tape."]]}, "daisy": {"m": ["Yellow craft foam sheets, 2 (buy: craft store)", "Brown craft foam for the flower center, 1 sheet (buy: craft store)", "Green dress, 1 (own, or buy: thrift store)", "Headband, 1 (buy: dollar store, or use your own)", "Glue, 1 tube craft glue (buy: craft store)", "Scissors, 1 pair"], "s": ["Buy the yellow and brown craft foam, headband, and glue.", "Cut 10 to 12 petal shapes from the yellow craft foam with the scissors.", "Arrange all 10 to 12 petals around the headband DRY before gluing, once craft glue sets, petals cannot be repositioned. Glue the petals in a ring around the headband, tips pointing out, overlapping slightly.", "Glue the brown foam circle in the center of the petals.", "Safety: let the glue dry fully before wearing.", "Wear the flower headband with the green dress.", "Optional pro finish: dot the brown center with yellow fabric paint dots for pollen texture. The textured center is what makes it read as a real flower up close.", "Optional pro finish: dot the brown center with yellow fabric paint dots for pollen texture. The textured center is what makes it read as a real flower up close."], "time": "30 min + drying", "cost": "$5-8", "effort": "Easy", "faqs": [["How many petals does a daisy need?", "Ten to twelve. Fewer looks sparse, more looks like a sunflower. Overlap them slightly so no headband shows through."], ["Foam or felt for the petals?", "Craft foam holds its shape and springs back; felt flops by hour two. Foam costs a little more and looks twice as good."]]}, "little-baker": {"m": ["White paper or poster board for the hat, 2 sheets (buy: craft store, or use printer paper)", "Apron, 1 (own, or buy: dollar store)", "Toy whisk, 1 (buy: toy store or dollar store)", "Flour from the kitchen, 1 pinch (optional, for the effect)", "Tape, 1 roll", "Scissors, 1"], "s": ["Buy the paper, apron, and toy whisk.", "Roll the paper into a tall chef hat shape and tape the seam.", "Measure the head with a paper strip BEFORE cutting. The hat band must fit snug or it slides over the eyes. Trim the hat band to fit the head with the scissors.", "Safety: keep real flour away from eyes; a tiny pinch on the apron only.", "Wear the hat and the apron.", "Carry the toy whisk and offer everyone imaginary cupcakes.", "Optional pro finish: dust the apron with a little flour before heading out. One flour smudge is the difference between 'dressed as a baker' and 'is a baker.'", "Optional pro finish: dust the apron with a little flour before heading out. One flour smudge is the difference between 'dressed as a baker' and 'is a baker.'"], "time": "15 min", "cost": "$2-5", "effort": "Easy", "faqs": [["Chef hat or baker hat, different?", "Same hat, different props. Chefs carry the spoon; bakers carry the mixing bowl. The prop names the profession."], ["How do you keep a paper hat on a toddler?", "Elastic chin strap taped inside the band, loose enough for two fingers. Paper hats without straps last about four minutes on a toddler."]]}, "little-artist": {"m": ["Beret or flat cap, 1 (buy: thrift store)", "Cardboard for the palette, 1 piece (make: from a shipping box)", "Washable paint set, 1 (buy: craft store)", "Old smock or oversized t-shirt, 1 (own)", "Paintbrush, 1 (own, or buy: craft store)", "Scissors, 1 (own)"], "s": ["Buy the beret and the washable paint set. Pull the old smock from the closet.", "Draw the kidney-bean palette shape on the cardboard and check the size against the forearm BEFORE cutting. A palette cut too small looks like a toy. Cut it out with the scissors.", "Paint dabs of bright color around the palette edge and let dry.", "Flick a little paint onto the smock for splatters and let dry.", "Safety: use washable paint only; cover the table before splattering.", "Wear the smock and the tilted beret, and carry the palette and brush.", "Optional pro finish: squeeze real paint dabs onto the cardboard palette and carry it. A palette with actual paint on it is the prop that makes strangers say 'oh, an artist!' instead of 'nice beret.'", "Optional pro finish: squeeze real paint dabs onto the cardboard palette and carry it. A palette with actual paint on it is the prop that makes strangers say 'oh, an artist!' instead of 'nice beret.'"], "time": "15 min", "cost": "$3-8", "effort": "Easy", "faqs": [["How do you keep the beret on a small head?", "Bobby-pin it at both temples, tilted to one side. Berets slide straight back without pins, the tilt plus pins locks it."], ["What is on the cardboard palette?", "Dabs of the same face paint colors, arranged in a circle. Match the palette to the cheek dabs and the costume tells one coherent story."]]}, "beekeeper-bee": {"m": ["White long-sleeve shirt and white pants, 1 set (own, or buy: thrift store)", "Fine mesh fabric or a mosquito head net, 1 (buy: craft store or camping aisle)", "Wide-brim hat, 1 (own, or buy: dollar store)", "Yellow shirt and yellow pants, 1 set (own, or buy: thrift store)", "Black electrical tape, 1 roll (buy: dollar store)", "Black pipe cleaners for antennae, 2 (buy: craft store)", "Headband, 1 (buy: dollar store, or use your own)", "Yellow and black face paint sticks, 1 set (buy: craft store)", "Scissors, 1 pair"], "s": ["Buy the mesh fabric, black tape, pipe cleaners, headband, and face paint. Pull the white and yellow outfits from the closet.", "Beekeeper: drape the mesh fabric over the wide-brim hat so it hangs past the shoulders, and tie it at the neck. Cut the face opening wide first, you can trim it neater after the first fitting.", "Bee: wrap 3 to 4 black tape stripes around the yellow shirt and pants, evenly spaced. Press the tape flat so the edges do not peel.", "Bend the pipe cleaners into a V and tape them to the headband for antennae. Add two black face-paint dots on the cheeks.", "Safety: cut the veil opening wide enough that vision stays clear, and tie nothing tight around the neck. Use tape, not string, for the stripes so nothing unravels.", "The adult is the beekeeper: white outfit with the veil hat, since the mesh limits vision. The smaller of the two is the bee: stripes with the antennae headband.", "Optional pro finish: the beekeeper carries a small cardboard sign that says HONEY, and the bee poses mid-buzz next to it. One shared prop is what makes a pair read as a pair."], "time": "25 min", "cost": "$3-10", "effort": "Easy", "faqs": [["How do you make a beekeeper veil you can see through?", "Use fine mesh fabric or a mosquito head net draped over a wide-brim hat, with the face opening cut wide and the fabric tied at the neck, never taped to the skin."], ["Will the black tape stripes stay on all night?", "Press electrical tape flat onto clean, dry fabric and it holds for an evening. For a longer night, use black felt strips with fabric glue instead."]]}, "tetris-duo": {"m": ["Two large cardboard boxes, flattened (make: from shipping boxes)", "Acrylic paint in two bright colors, 1 set (buy: craft store)", "Wide ribbon or webbing for shoulder straps, about 4 yards (buy: craft store)", "Painter's tape, 1 roll (buy: dollar store)", "Scissors or a box cutter, 1", "Ruler or yardstick, 1 (own)"], "s": ["Buy the paint, ribbon, and painter's tape. Break the boxes down flat.", "Mark a grid of 12-inch squares on the cardboard with the ruler. Each block shape is 4 squares: cut an L shape for one person and a T or square shape for the other. Cut the squares oversized first and trim after a fitting.", "Paint each shape its color and let dry fully, flat, for at least 2 hours.", "Tape ribbon loops to the top of each shape for shoulder straps. Test the hang before the party: each shape should sit at chest height.", "Safety: cut on a protected surface with the blade pointed away from fingers, and round the cardboard corners so nobody gets poked in a crowd.", "Each person wears one shape like a sandwich board, front and back panels tied with the ribbon straps.", "Optional pro finish: stand so the two shapes interlock for photos, and let strangers name your pieces. The click-together pose is the whole costume."], "time": "45 min + drying", "cost": "$3-8", "effort": "Easy", "faqs": [["What are the easiest block shapes to build?", "The 2 by 2 square and the L shape: both are rectangles with one extra cut, no fiddly notches. Paint them different colors so they read as two pieces."], ["How do you keep the cardboard from flopping?", "Use double-wall cardboard from a shipping box, not a cereal box, and keep each piece to 4 squares. Bigger pieces fold at the seams."]]}, "little-lifeguard": {"m": ["Red t-shirt, 1 (own, or buy: thrift store)", "Plastic whistle on a lanyard, 1 (buy: dollar store or party store)", "Pool noodle, 1 (buy: dollar store)", "White duct tape, 1 roll (buy: dollar store)", "Red shorts or swim trunks, 1 pair (own)", "White face paint stick for the nose stripe, 1 (buy: craft store)", "Scissors, 1 pair"], "s": ["Buy the whistle, pool noodle, and white duct tape. Pull the red tee and shorts from the closet.", "Cut the pool noodle with the scissors and curve it into a ring, taping the ends together with the white duct tape. An adult should do the cutting: pool noodles need firm pressure.", "Wrap 4 white tape bands evenly around the ring so it reads as a rescue buoy.", "Safety: the whistle is a photo prop the parent holds and brings out for pictures, not a blow-all-night toy. The buoy is a costume prop, not a flotation device. Keep the lanyard short so it cannot catch on anything.", "Wear the red tee and shorts and carry the buoy over one shoulder. The parent keeps the whistle and hands it over for photos.", "Dab the white face paint stripe across the nose.", "Optional pro finish: write LIFEGUARD across the back of the tee with the white duct tape in block letters. Back lettering is what strangers read first."], "time": "20 min", "cost": "$3-8", "effort": "Easy", "faqs": [["How do you make the pool noodle ring stay round?", "Cut the noodle ends at an angle so they meet in a clean joint, then wrap the joint with 3 layers of duct tape. The tape joint is stronger than the foam."], ["Is a real whistle too loud for a kid costume?", "One toot at a time is the rule. Party-store whistles are plenty loud; skip the metal coach whistles."]]}, "little-prince": {"m": ["Gold cardstock or a paper crown, 1 (buy: party store, or make: from cardstock)", "Red or purple fabric for the cape, about 1 yard (own, or buy: craft store)", "Wide ribbon for the sash, about 2 yards (buy: craft store)", "Stick-on plastic gems, 1 pack (buy: dollar store)", "White gloves, 1 pair (buy: dollar store, optional)", "Safety pins, 2", "Scissors, 1 pair", "Glue stick, 1"], "s": ["Buy the gold cardstock, ribbon, and stick-on gems. Pull cape fabric from the craft drawer.", "Cut the cardstock into a crown band sized to the head, overlap 1 inch, and glue. Cut triangle points along the top edge.", "Press the stick-on gems around the crown band, one big gem centered on the front.", "Drape the fabric as a cape. For under-5s, skip the pins: tie the cape's top corners to the shirt shoulders with short ribbon ties, or glue the top edge to the back of the shirt. Nothing tied around the neck.", "Safety: no pins near little hands. Keep the cape above the knees so it cannot trip. Nothing tied around the neck.", "Sash: drape the wide ribbon from one shoulder to the opposite hip and tape or glue it at the waist.", "Optional pro finish: tilt the crown slightly to one side. A crooked crown is the whole charm of a little prince."], "time": "20 min", "cost": "$3-8", "effort": "Easy", "faqs": [["How do you keep a paper crown from tearing?", "Use cardstock, not printer paper, and overlap the band a full inch before gluing. The stick-on gems add stiffness as a bonus."], ["What if we have no cape fabric?", "A red bath towel or a pillowcase works. Pin it at the shoulders, never tie it at the neck, and trim it above the knees."]]}, "fossil-hunter": {"m": ["Khaki or tan vest with pockets, 1 (own, or buy: thrift store)", "Toy paintbrush or makeup brush, 1 (own, or buy: dollar store)", "Toy magnifying glass, 1 (buy: dollar store)", "Cardboard for fossil bones, 1 sheet (make: from a shipping box)", "Small canvas pouch or fanny pack, 1 (own, or buy: dollar store)", "Brown paper lunch bag, 1 (own)", "Scissors, 1 pair", "Pencil, 1"], "s": ["Buy the magnifying glass and pouch. Pull the khaki vest from the closet.", "Draw bone shapes on the cardboard with the pencil: a femur, a rib, a skull. Keep them chunky, thin cardboard bones snap.", "Cut the bones out with the scissors and shade the edges with the pencil for the dug-up look.", "Tuck the cardboard bones into the pouch so the tops peek out.", "Safety: round all cardboard corners, and carry the brush bristles-down so nobody gets poked.", "Wear the khaki vest over a plain shirt, the pouch on the belt, the magnifying glass in one pocket and the brush in the other.", "Optional pro finish: crumple the brown paper bag into a specimen bag and label it with the pencil. One labeled prop sells the whole expedition."], "time": "25 min", "cost": "$3-8", "effort": "Easy", "faqs": [["How do you make cardboard bones look like fossils?", "Cut them chunky, shade the edges with pencil, and rub a little dirt-colored eyeshadow into the surface. Uneven shading beats perfect coloring."], ["What goes in the belt pouch?", "The cardboard bones with their tops peeking out, plus the brush. A pouch that bulges with finds reads as a real dig kit."]]}};

function esc(s) {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;")
          .replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

